def first_existing_path(candidates) -> Path | None:
    """Return the first existing candidate path without creating placeholder files.

    Older gateway passes used this helper for optional companion launch targets.
    The clean placeholder build still references it during startup, so keep it
    tiny and side-effect free: empty Dimension folders stay empty until a real
    mode is dropped in.
    """
    try:
        items = list(candidates or [])
    except Exception:
        items = []
    for candidate in items:
        try:
            path = Path(candidate)
            if path.exists():
                return path
        except Exception:
            continue
    return None

# ---------------------------------------------------------------------------
# Clean-layout compatibility helpers
# ---------------------------------------------------------------------------
def _safe_read_json(path, default=None):
    fallback = {} if default is None else default
    try:
        target = Path(path)
        if not target.exists() or not target.is_file():
            return fallback
        text = target.read_text(encoding="utf-8")
        if not text.strip():
            return fallback
        return json.loads(text)
    except Exception:
        return fallback


def _safe_write_text_atomic(path, text: str) -> bool:
    """Durable project-contained text save with no unsafe direct-write fallback."""
    target = Path(path)
    tmp = target.with_name(target.name + ".tmp")
    try:
        target.parent.mkdir(parents=True, exist_ok=True)
        with tmp.open("w", encoding="utf-8", newline="") as fh:
            fh.write(str(text))
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp, target)
        try:
            dir_fd = os.open(str(target.parent), os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except Exception:
            pass
        return True
    except Exception:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        return False


def _safe_write_json(path, payload) -> bool:
    """Atomic/fsynced JSON save used by campaign, settings and child modes."""
    try:
        data = json.dumps(payload, indent=2, ensure_ascii=False, sort_keys=True) + "\n"
    except Exception:
        return False
    return _safe_write_text_atomic(path, data)


