def write_holoverse_settings(cfg: ObservatoryConfig) -> Path:
    ensure_dirs()
    _safe_write_json(HOLOVERSE_SETTINGS_PATH, build_holoverse_settings_payload(cfg))
    return HOLOVERSE_SETTINGS_PATH
def write_shared_launch_settings(cfg: ObservatoryConfig) -> Path:
    ensure_dirs()
    path = RUNTIME_SHARED_SETTINGS_PATH
    _safe_write_json(path, build_launch_settings_payload(cfg))
    write_holoverse_settings(cfg)
    return path


def write_audio_bus(cfg: ObservatoryConfig) -> Path:
    ensure_dirs()
    path = RUNTIME_AUDIO_BUS_PATH
    _safe_write_json(path, build_audio_bus_payload(cfg))
    return path


def _clamp01(v: float) -> float:
    return max(0.0, min(1.0, float(v)))


DEFAULT_HOLOVERSE_MUSIC_CUES = {
    "hub": {"start": 0.5, "end": 35.5, "rate": 1.0},
    "forest": {"start": 36.0, "end": 63.5, "rate": 0.98},
    "hills": {"start": 64.0, "end": 97.5, "rate": 1.0},
    "mushroom": {"start": 98.0, "end": 117.5, "rate": 0.94},
    "desert": {"start": 118.0, "end": 164.5, "rate": 1.02},
    "ice": {"start": 165.0, "end": 181.5, "rate": -0.92},
    "urban": {"start": 182.0, "end": 217.5, "rate": 1.03},
    "metropolis": {"start": 218.0, "end": 267.5, "rate": 1.0},
    "space": {"start": 234.0, "end": 286.2, "rate": -0.88},
    "holoforge": {"start": 64.0, "end": 97.5, "rate": -0.96},
}

MUSIC_CUE_ALIASES = {
    "holo_space": "space",
    "holospace": "space",
    "holo_forge": "holoforge",
    "holoforge": "holoforge",
}

def load_holoverse_music_cues() -> dict[str, dict[str, float]]:
    data = {}
    try:
        if HOLOVERSE_MUSIC_CUES_PATH.exists():
            raw = json.loads(HOLOVERSE_MUSIC_CUES_PATH.read_text(encoding="utf-8"))
            data = raw.get("cues", raw) if isinstance(raw, dict) else {}
    except Exception:
        data = {}
    merged: dict[str, dict[str, float]] = {}
    for key, default in DEFAULT_HOLOVERSE_MUSIC_CUES.items():
        item = data.get(key, {}) if isinstance(data, dict) else {}
        if not isinstance(item, dict):
            item = {}
        try:
            start = float(item.get("start", default["start"]))
            end = float(item.get("end", default["end"]))
            rate = float(item.get("rate", default["rate"]))
        except Exception:
            start, end, rate = default["start"], default["end"], default["rate"]
        if end <= start + 0.25:
            start, end = default["start"], default["end"]
        if abs(rate) < 0.05:
            rate = default["rate"]
        merged[key] = {"start": max(0.0, start), "end": max(start + 0.25, end), "rate": rate}
    return merged

def resolve_holoverse_music_cue(name: str) -> tuple[str, dict[str, float]] | None:
    raw = str(name or "").strip()
    if not raw:
        return None
    key = raw.lower().replace("cue:", "", 1).strip()
    key = MUSIC_CUE_ALIASES.get(key, key)
    if key.endswith(".wav"):
        stem = Path(key).stem
        for alias, cue in MUSIC_CUE_ALIASES.items():
            if Path(alias).stem == stem:
                key = cue
                break
    cues = load_holoverse_music_cues()
    if key in cues:
        return key, cues[key]
    return None


# Pass 282.79: every HoloVerse area plays its own soundtrack file on loop.  Holoverse.mp3 belongs to
# the MatrixCore hub only; the other areas start as silent placeholders in assets/audio/regions/
# that can be swapped for real tracks.  Dimensions (HoloCore, the Indigo Giant, ...) keep their own
# music and never receive these tracks.
DEFAULT_REGION_MUSIC = {
    "hub": {"file": "Holoverse.mp3", "volume": 1.0},
    "forest": {"file": "regions/forests.mp3", "volume": 1.0},
    "hills": {"file": "regions/green_hills.mp3", "volume": 1.0},
    "mushroom": {"file": "regions/mushroom.mp3", "volume": 1.0},
    "desert": {"file": "regions/desert.mp3", "volume": 1.0},
    "ice": {"file": "regions/ice.mp3", "volume": 1.0},
    "urban": {"file": "regions/urban.mp3", "volume": 1.0},
    "metropolis": {"file": "regions/metropolis.mp3", "volume": 1.0},
    "space": {"file": "regions/holospace.mp3", "volume": 1.0},
    "holoforge": {"file": "regions/holoforge.mp3", "volume": 1.0},
}

_REGION_MUSIC_CACHE: dict = {"stamp": None, "tracks": None}


def load_region_music() -> dict[str, dict]:
    """Region key -> {"path": Path, "volume": float} from assets/audio/region_music.json.

    Re-read only when the file changes (this is called every frame by the soundscape)."""
    try:
        stamp = REGION_MUSIC_PATH.stat().st_mtime_ns if REGION_MUSIC_PATH.is_file() else 0
    except OSError:
        stamp = 0
    if _REGION_MUSIC_CACHE["tracks"] is not None and _REGION_MUSIC_CACHE["stamp"] == stamp:
        return _REGION_MUSIC_CACHE["tracks"]
    raw = {}
    if stamp:
        try:
            data = json.loads(REGION_MUSIC_PATH.read_text(encoding="utf-8"))
            raw = data.get("tracks", data) if isinstance(data, dict) else {}
        except Exception as exc:
            print(f"region_music_manifest_invalid path={REGION_MUSIC_PATH} err={exc}")
            raw = {}
    tracks: dict[str, dict] = {}
    keys = list(DEFAULT_REGION_MUSIC) + [k for k in (raw if isinstance(raw, dict) else {}) if not str(k).startswith("_") and k not in DEFAULT_REGION_MUSIC]
    for key in keys:
        default = DEFAULT_REGION_MUSIC.get(key, {"file": "", "volume": 1.0})
        item = raw.get(key, {}) if isinstance(raw, dict) else {}
        if isinstance(item, str):
            item = {"file": item}
        if not isinstance(item, dict):
            item = {}
        name = str(item.get("file", default["file"]) or "").strip()
        try:
            volume = max(0.0, min(1.0, float(item.get("volume", default["volume"]))))
        except Exception:
            volume = float(default["volume"])
        path = None
        if name:
            candidate = Path(name)
            path = candidate if candidate.is_absolute() else AUDIO_LIBRARY_DIR / candidate
        tracks[str(key).lower()] = {"path": path, "volume": volume, "file": name}
    _REGION_MUSIC_CACHE["stamp"] = stamp
    _REGION_MUSIC_CACHE["tracks"] = tracks
    return tracks


def resolve_region_music_track(name: str) -> tuple[str, Path | None, float] | None:
    """(region key, track file or None when missing, volume) for a soundscape music name.

    None means the name is not a region (the caller may treat it as a plain file).  A region whose
    file is missing resolves with path None, so that area is silent instead of borrowing a song."""
    raw = str(name or "").strip()
    if not raw:
        return None
    key = raw.lower().replace("cue:", "", 1).strip()
    key = MUSIC_CUE_ALIASES.get(key, key)
    tracks = load_region_music()
    item = tracks.get(key)
    if item is None:
        return None
    path = item["path"]
    if path is None or not path.is_file():
        path = None
    return key, path, float(item["volume"])

class SharedAudio:
    def __init__(self, app):
        self.app = app
        self.backend = 'silent'
        self.enabled = False
        self.looping = {}
        self.oneshots = []
        self.pygame = None
        self.pygame_channels = {}
        self.cache = {}
        if SELF_TEST:
            return
        # Pass 22: audio is read-only at runtime. No synthesizers, no reverse caches,
        # no generated folders. Missing audio stays missing instead of being forged.
        self._try_panda()
        if not self.enabled:
            self._try_pygame()
        print(f'audio_backend={self.backend}')

    def _try_panda(self):
        try:
            if not getattr(self.app, 'loader', None):
                return
            # Panda may silently fall back to NullAudioManager when OpenAL cannot
            # open an output device. Treat that as unavailable so pygame can be
            # tried instead of reporting a fake "panda" backend with no sound.
            managers = []
            try:
                managers.extend(list(getattr(self.app, 'sfxManagerList', []) or []))
            except Exception:
                pass
            try:
                music_mgr = getattr(self.app, 'musicManager', None)
                if music_mgr is not None:
                    managers.append(music_mgr)
            except Exception:
                pass
            manager_names = " ".join(str(mgr) for mgr in managers).lower()
            if "nullaudiomanager" in manager_names:
                raise RuntimeError("Panda audio fell back to NullAudioManager")
            test_path = self._resolve_audio_path('menu_open.wav') or (CORE_SFX_DIR / 'menu_open.wav')
            test = self.app.loader.loadSfx(Filename.fromOsSpecific(str(test_path)))
            if not test:
                return
            self.backend = 'panda'
            self.enabled = True
        except Exception as exc:
            print(f'audio_panda_unavailable: {exc}')

    def _try_pygame(self):
        try:
            import pygame
            if not pygame.mixer.get_init():
                pygame.mixer.pre_init(22050, size=-16, channels=2, buffer=512)
                pygame.mixer.init()
            self.pygame = pygame
            self.backend = 'pygame'
            self.enabled = True
        except Exception as exc:
            self.backend = f'silent:{exc.__class__.__name__}'
            print(f'audio_pygame_unavailable: {exc}')

    def _bus_gain(self, bus: str, base: float = 1.0) -> float:
        cfg = self.app.cfg
        bus_value = 1.0
        if bus == 'sfx':
            bus_value = cfg.sfx_volume
        elif bus == 'music':
            bus_value = cfg.music_volume
        elif bus == 'ambience':
            bus_value = cfg.ambience_volume
        return _clamp01(base * cfg.master_volume * bus_value)

    def _resolve_audio_path(self, filename: str) -> Path | None:
        raw_input = str(filename or '').strip()
        if not raw_input:
            return None
        try:
            direct = Path(raw_input)
            if direct.is_absolute() and direct.exists() and direct.is_file():
                return direct
        except Exception:
            pass
        raw = raw_input.replace('\\', '/').strip('/')
        candidates = [
            CORE_SFX_DIR / raw,
            CANONICAL_SHARED_SFX_DIR / raw,
            AUDIO_LIBRARY_DIR / raw,
        ]
        for root in (CORE_SFX_DIR, CANONICAL_SHARED_SFX_DIR):
            try:
                candidates.extend(root.rglob(Path(raw).name))
            except Exception:
                pass
        for candidate in candidates:
            try:
                if candidate.exists() and candidate.is_file():
                    return candidate
            except Exception:
                continue
        return None

    def _music_cue(self, name: str) -> tuple[str, dict[str, float]] | None:
        return resolve_holoverse_music_cue(name)

    def _load(self, filename: str, bus: str = 'sfx'):
        path = self._resolve_audio_path(filename)
        if path is None:
            return None
        cache_key = str(path)
        if self.backend == 'panda':
            if cache_key not in self.cache:
                snd = self.app.loader.loadSfx(Filename.fromOsSpecific(str(path)))
                self.cache[cache_key] = snd
            return self.cache.get(cache_key)
        if self.backend == 'pygame' and self.pygame:
            if cache_key not in self.cache:
                self.cache[cache_key] = self.pygame.mixer.Sound(str(path))
            return self.cache.get(cache_key)
        return None

    def play(self, filename: str, bus='sfx', volume=1.0):
        if not self.enabled:
            return
        snd = self._load(filename, bus=bus)
        if snd is None:
            return
        gain = self._bus_gain(bus, volume)
        try:
            snd.setVolume(gain)
        except Exception:
            pass
        try:
            if self.backend == 'panda':
                snd.play()
            elif self.backend == 'pygame':
                ch = snd.play()
                if ch:
                    ch.set_volume(gain)
                    self.oneshots.append((snd, ch, bus, volume))
        except Exception:
            pass

    def _start_music_cue(self, slot: str, cue_name: str, *, bus: str = "music", volume: float = 1.0) -> None:
        resolved = self._music_cue(cue_name)
        if resolved is None or not HOLOVERSE_MUSIC_FILE.exists():
            self.stop_loop(slot)
            return
        cue_key, cue = resolved
        gain = self._bus_gain(bus, volume)
        current = self.looping.get(slot)
        if current and current.get("kind") == "music_cue" and current.get("cue") == cue_key:
            current["bus"] = bus
            current["volume"] = volume
            self._apply_loop_gain(slot)
            return
        # One authoritative music stream. Starting a new cue replaces any older
        # HoloVerse music cue regardless of which scene-owned slot started it.
        for other in tuple(self.looping.keys()):
            info = self.looping.get(other) or {}
            if info.get("kind") == "music_cue":
                self.stop_loop(other)
        start = float(cue["start"]); end = float(cue["end"]); rate = float(cue["rate"])
        info = {"kind": "music_cue", "cue": cue_key, "filename": os.fspath(HOLOVERSE_MUSIC_FILE),
                "bus": bus, "volume": volume, "start": start, "end": end, "rate": rate}
        try:
            if self.backend == "panda":
                snd = self.app.loader.loadMusic(Filename.fromOsSpecific(str(HOLOVERSE_MUSIC_FILE)))
                if not snd:
                    return
                snd.setLoop(False)
                snd.setVolume(gain)
                snd.setPlayRate(rate)
                snd.setTime((end - 0.05) if rate < 0.0 else start)
                snd.play()
                info["sound"] = snd
            elif self.backend == "pygame" and self.pygame is not None:
                # pygame cannot reverse a streamed MP3. It still uses the exact
                # same file and cue boundary, but negative cues fall back forward.
                self.pygame.mixer.music.stop()
                self.pygame.mixer.music.load(str(HOLOVERSE_MUSIC_FILE))
                self.pygame.mixer.music.set_volume(gain)
                self.pygame.mixer.music.play(loops=0, start=start)
                info["pygame_elapsed_start"] = time.monotonic()
                info["pygame_reverse_fallback"] = bool(rate < 0.0)
            else:
                return
        except Exception as exc:
            try: print(f"music_cue_start_failed cue={cue_key} err={exc.__class__.__name__}:{exc}")
            except Exception: pass
            return
        self.looping[slot] = info

    def _start_music_track(self, slot: str, region: tuple, *, bus: str = "music", volume: float = 1.0) -> None:
        """Loop one region's own soundtrack file (Pass 282.79)."""
        key, path, track_volume = region
        if path is None:
            # No track for this area (file removed or not added yet): silence, never another song.
            self.stop_loop(slot)
            return
        volume = max(0.0, min(1.0, float(volume) * float(track_volume)))
        filename = os.fspath(path)
        current = self.looping.get(slot)
        if current and current.get("kind") == "music_track" and current.get("filename") == filename:
            current["bus"] = bus
            current["volume"] = volume
            self._apply_loop_gain(slot)
            return
        # One music stream at a time, whichever slot started the previous one.
        for other in tuple(self.looping.keys()):
            info = self.looping.get(other) or {}
            if info.get("kind") in ("music_cue", "music_track"):
                self.stop_loop(other)
        gain = self._bus_gain(bus, volume)
        info = {"kind": "music_track", "cue": key, "filename": filename, "bus": bus, "volume": volume}
        try:
            if self.backend == "panda":
                snd = self.app.loader.loadMusic(Filename.fromOsSpecific(filename))
                if not snd:
                    return
                snd.setLoop(True)
                snd.setVolume(gain)
                snd.play()
                info["sound"] = snd
            elif self.backend == "pygame" and self.pygame is not None:
                self.pygame.mixer.music.stop()
                self.pygame.mixer.music.load(filename)
                self.pygame.mixer.music.set_volume(gain)
                self.pygame.mixer.music.play(loops=-1)
            else:
                return
        except Exception as exc:
            try: print(f"music_track_start_failed region={key} file={filename} err={exc.__class__.__name__}:{exc}")
            except Exception: pass
            return
        self.looping[slot] = info

    def play_loop(self, slot: str, filename: str, bus='ambience', volume=1.0):
        if not self.enabled:
            return
        if str(bus or '').lower() == 'music':
            region = resolve_region_music_track(filename)
            if region is not None:
                self._start_music_track(slot, region, bus=bus, volume=volume)
                return
        if str(bus or '').lower() == 'music' and self._music_cue(filename) is not None:
            self._start_music_cue(slot, filename, bus=bus, volume=volume)
            return
        snd = self._load(filename, bus=bus)
        if snd is None:
            self.stop_loop(slot)
            return
        gain = self._bus_gain(bus, volume)
        current = self.looping.get(slot)
        if current and current.get('kind') == 'static_loop' and current.get('filename') == filename:
            current['bus'] = bus; current['volume'] = volume
            self._apply_loop_gain(slot)
            return
        self.stop_loop(slot)
        info = {'kind': 'static_loop', 'filename': filename, 'sound': snd, 'bus': bus, 'volume': volume}
        self.looping[slot] = info
        try:
            if self.backend == 'panda':
                snd.setVolume(gain); snd.setLoop(True); snd.play()
            elif self.backend == 'pygame':
                channel = snd.play(loops=-1)
                if channel:
                    channel.set_volume(gain); self.pygame_channels[slot] = channel
        except Exception:
            pass

    def stop_loop(self, slot: str):
        info = self.looping.pop(slot, None)
        if not info:
            return
        try:
            if info.get('kind') in ('music_cue', 'music_track') and self.backend == 'pygame' and self.pygame is not None:
                self.pygame.mixer.music.stop()
            elif self.backend == 'panda':
                snd = info.get('sound')
                if snd is not None: snd.stop()
            elif self.backend == 'pygame':
                ch = self.pygame_channels.pop(slot, None)
                if ch: ch.stop()
        except Exception:
            pass

    def stop_external_panda_audio(self):
        """Stop Panda3D sounds not tracked by SharedAudio.

        Same-window dimensions are scenes inside one game, but source adapters can
        load SFX/music directly through the host loader.  This gives HoloVerse a
        single permanent cleanup point so old dimension music cannot carry into
        the next scene.
        """
        managers = []
        try:
            managers.extend(list(getattr(self.app, "sfxManagerList", []) or []))
        except Exception:
            pass
        try:
            mgr = getattr(self.app, "musicManager", None)
            if mgr is not None:
                managers.append(mgr)
        except Exception:
            pass
        for mgr in managers:
            for method_name in ("stopAllSounds", "stop_all_sounds", "stopAll", "stop_all"):
                method = getattr(mgr, method_name, None)
                if callable(method):
                    try:
                        method()
                    except Exception:
                        pass
                    break

    def stop_all(self, *, stop_oneshots: bool = True):
        """Stop every HoloVerse-owned sound channel.

        Dimension switches are scene changes, not separate apps.  Without one
        hard-stop point, hub loops, native dimension beds, and
        pygame one-shots can overlap after a return.
        """
        for slot in tuple(self.looping.keys()):
            self.stop_loop(slot)
        if self.backend == 'pygame':
            for slot, ch in list(self.pygame_channels.items()):
                try:
                    if ch:
                        ch.stop()
                except Exception:
                    pass
            self.pygame_channels.clear()
            if self.pygame is not None:
                try:
                    self.pygame.mixer.music.stop()
                except Exception:
                    pass
            if stop_oneshots and self.pygame is not None:
                try:
                    self.pygame.mixer.stop()
                except Exception:
                    pass
        if self.backend == 'panda':
            for snd in list(self.cache.values()):
                try:
                    snd.stop()
                except Exception:
                    pass
        if stop_oneshots:
            self.oneshots.clear()
        self.stop_external_panda_audio()

    def _apply_loop_gain(self, slot: str):
        info = self.looping.get(slot)
        if not info:
            return
        gain = self._bus_gain(info['bus'], info['volume'])
        try:
            if info.get('kind') in ('music_cue', 'music_track') and self.backend == 'pygame' and self.pygame is not None:
                self.pygame.mixer.music.set_volume(gain)
            elif self.backend == 'panda':
                snd = info.get('sound')
                if snd is not None: snd.setVolume(gain)
            elif self.backend == 'pygame':
                ch = self.pygame_channels.get(slot)
                if ch: ch.set_volume(gain)
        except Exception:
            pass

    def _refresh_music_cue(self, slot: str, info: dict) -> None:
        start = float(info.get('start', 0.0)); end = float(info.get('end', start + 1.0)); rate = float(info.get('rate', 1.0))
        if self.backend == 'panda':
            snd = info.get('sound')
            if snd is None: return
            try:
                pos = float(snd.getTime())
                boundary = (rate >= 0.0 and pos >= end - 0.06) or (rate < 0.0 and pos <= start + 0.06)
                if boundary:
                    snd.stop(); snd.setLoop(False); snd.setPlayRate(rate)
                    snd.setTime((end - 0.05) if rate < 0.0 else start); snd.play()
            except Exception:
                pass
        elif self.backend == 'pygame' and self.pygame is not None:
            # Streamed pygame fallback always travels forward inside the same cue.
            try:
                elapsed = max(0.0, (self.pygame.mixer.music.get_pos() or 0) / 1000.0)
                if elapsed >= max(0.25, end - start):
                    self.pygame.mixer.music.play(loops=0, start=start)
                    self.pygame.mixer.music.set_volume(self._bus_gain(info['bus'], info['volume']))
            except Exception:
                pass

    def refresh_mix(self):
        for slot in tuple(self.looping.keys()):
            self._apply_loop_gain(slot)
            info = self.looping.get(slot) or {}
            if info.get('kind') == 'music_cue':
                self._refresh_music_cue(slot, info)
        if self.backend == 'pygame':
            alive = []
            for snd, ch, bus, volume in self.oneshots:
                if ch and ch.get_busy():
                    try:
                        ch.set_volume(self._bus_gain(bus, volume))
                    except Exception:
                        pass
                    alive.append((snd, ch, bus, volume))
            self.oneshots = alive


def hsv_color(h: float, s: float, v: float, a: float = 1.0):
    r, g, b = colorsys.hsv_to_rgb(h % 1.0, max(0.0, min(1.0, s)), max(0.0, min(1.0, v)))
    return (r, g, b, a)




