class WorldActor:
    def __init__(self, root, kind, seed, home):
        self.root = root
        self.kind = kind
        self.seed = seed
        self.home = Vec3(home)
        self.phase = random.Random(seed).random() * math.tau
        self.follow_timer = 0.0


# HoloCore no longer ships a scene implementation inside HoloVerse.
# It is an external native reality under MatrixCore Project and owns its
# complete same-window adapter in HoloCore/holoverse_native_adapter.py.


# Connected signal mini-scene was removed intentionally.  External native
# realities, including HoloCore, own their scene implementation beside main.py
# and mount through the generic Dimension Archive lifecycle.

def lerp(a, b, t):
    return a + (b - a) * t


def lerp_rgb(a, b, t):
    return tuple(lerp(a[i], b[i], t) for i in range(3))


class CommandHubApp(ShowBase):
    def userExit(self):
        try:
            clear_holoverse_runtime_cache("userExit")
        except Exception:
            pass
        # Pass 282.68: never leave a child game or a stuck python behind when HoloVerse closes.
        for attr in ("external_process", "external_proc"):
            proc = getattr(self, attr, None)
            try:
                if proc is not None and proc.poll() is None:
                    proc.terminate()
            except Exception:
                pass
        def _hard_exit_watchdog():
            time.sleep(6.0)
            os._exit(0)
        try:
            threading.Thread(target=_hard_exit_watchdog, name="HoloVerseExitWatchdog", daemon=True).start()
        except Exception:
            pass
        return super().userExit()


