    def _gleebs_intro_task(self, task):
        self.maybe_start_gleebs_intro()
        return Task.done

    # ------------------------------------------------------------------
    # Pass 23: full-game campaign spine
    # ------------------------------------------------------------------
    def campaign_state_file_exists(self) -> bool:
        return CAMPAIGN_STATE_PATH.exists()

    def campaign_has_legacy_progress(self) -> bool:
        candidates = [
            APP_DATA_DIR / "holoverse" / "regions" / "flat" / "holoforge" / "holoforge_scene.json",
            APP_DATA_DIR / "holoverse" / "regions" / "forest" / "growth" / "forest_growth_state.json",
            APP_DATA_DIR / "holoverse" / "regions" / "hills" / "life" / "hills_life_state.json",
            APP_DATA_DIR / "holoverse" / "regions" / "mushroom" / "oddities" / "oddities_state.json",
            APP_DATA_DIR / "holoverse" / "regions" / "desert" / "ships" / "desert_ship_state.json",
            APP_DATA_DIR / "holoverse" / "regions" / "ice" / "races" / "frost_circuit_state.json",
            APP_DATA_DIR / "holoverse" / "regions" / "metropolis" / "robot_lab" / "robot_blueprints.json",
            APP_DATA_DIR / "holoverse" / "regions" / "urban" / "warzone" / "urban_warzone_state.json",
        ]
        return any(path.exists() for path in candidates)

    def load_campaign_state(self, *, create: bool = True) -> dict:
        existing = _safe_read_json(CAMPAIGN_STATE_PATH) if CAMPAIGN_STATE_PATH.exists() else {}
        if not existing and not create:
            return {}
        merged = merge_dict_defaults(existing, campaign_default_payload())
        signals = merged.setdefault("signals", {})
        for key in CAMPAIGN_SIGNAL_ORDER:
            base = campaign_default_payload()["signals"][key]
            signals[key] = merge_dict_defaults(signals.get(key) if isinstance(signals.get(key), dict) else {}, base)
        if create and merged != existing:
            self.save_campaign_state(merged)
        self.campaign_state = merged
        return merged

    def save_campaign_state(self, payload: dict) -> dict:
        data = merge_dict_defaults(dict(payload or {}), campaign_default_payload())
        data["updated_at"] = datetime.now().isoformat(timespec="seconds")
        CAMPAIGN_STATE_PATH.parent.mkdir(parents=True, exist_ok=True)
        _safe_write_json(CAMPAIGN_STATE_PATH, data)
        self.campaign_state = data
        return data

    def campaign_signal_state_paths(self) -> dict[str, Path]:
        base = APP_DATA_DIR / "holoverse" / "regions"
        return {
            "forest_growth": base / "forest" / "growth" / "forest_growth_state.json",
            # Oddities moved to Green Hills in Pass 282.57; its save keeps the old folder.
            "oddities": base / "mushroom" / "oddities" / "oddities_state.json",
            "ember_hangar": base / "desert" / "ships" / "desert_ship_state.json",
            "frost_circuit": base / "ice" / "races" / "frost_circuit_state.json",
            "urban_warzone": base / "urban" / "warzone" / "urban_warzone_state.json",
        }

    @staticmethod
    def _campaign_file_stamp(path: Path | None):
        if path is None:
            return None
        try:
            st = path.stat()
            return (int(st.st_mtime_ns), int(st.st_size))
        except (FileNotFoundError, OSError):
            return None

    def campaign_probe_signal(self, key: str, *, force: bool = False) -> tuple[bool, str, str]:
        path = self.campaign_signal_state_paths().get(key)
        stamp = self._campaign_file_stamp(path)
        cache = getattr(self, "campaign_signal_probe_cache", {})
        stamp_cache = getattr(self, "campaign_signal_file_stamps", {})
        if not force and key in cache and stamp_cache.get(key) == stamp:
            return cache[key]
        data = _safe_read_json(path) if path is not None and stamp is not None else {}
        result = (False, "0", "")
        try:
            if key == "holoforge":
                count = int(data.get("object_count", len(data.get("objects", []) if isinstance(data.get("objects"), list) else [])) or 0)
                result = (count >= 3, f"{min(count,3)}/3 objects", "holoforge_scene")
            elif key == "forest_growth":
                summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
                count = int(summary.get("total_plants", len(data.get("plants", []) if isinstance(data.get("plants"), list) else [])) or 0)
                result = (count >= 5, f"{min(count,5)}/5 plants", "forest_state")
            elif key == "hills_of_life":
                summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
                count = int(summary.get("total_animals", len(data.get("animals", []) if isinstance(data.get("animals"), list) else [])) or 0)
                result = (count >= 2, f"{min(count,2)}/2 animals", "hills_state")
            elif key == "oddities":
                summary = data.get("summary") if isinstance(data.get("summary"), dict) else {}
                count = int(summary.get("total_oddities", len(data.get("items", []) if isinstance(data.get("items"), list) else [])) or 0)
                result = (count >= 3, f"{min(count,3)}/3 oddities", "oddities_state")
            elif key == "ember_hangar":
                default_id = str(data.get("default_ship_id") or "").strip()
                ok = bool(default_id and default_id != "starter_holocraft")
                result = (ok, "ship bound" if ok else "0/1 ship", "ember_state")
            elif key == "frost_circuit":
                count = int(data.get("races_completed", 0) or 0)
                result = (count >= 1, f"{min(count,1)}/1 race", "frost_state")
            elif key == "metropolis_robot_lab":
                active = str(data.get("active_ally_id") or "").strip()
                if not active and isinstance(data.get("active_ally"), dict):
                    active = str(data.get("active_ally", {}).get("id") or "").strip()
                result = (bool(active), "ally bound" if active else "0/1 ally", "metropolis_state")
            elif key == "urban_warzone":
                wave = max(int(data.get("best_wave", 0) or 0), int(data.get("last_wave", 0) or 0))
                result = (wave >= 3, f"wave {min(wave,3)}/3", "urban_state")
        except Exception:
            result = (False, "0", "")
        cache[key] = result
        stamp_cache[key] = stamp
        self.campaign_signal_probe_cache = cache
        self.campaign_signal_file_stamps = stamp_cache
        return result

    def mark_campaign_signal(self, key: str, *, source: str = "runtime", progress_text: str = "complete") -> bool:
        if key not in CAMPAIGN_SIGNAL_SPECS:
            return False
        state = self.load_campaign_state(create=True)
        signals = state.setdefault("signals", {})
        entry = signals.setdefault(key, campaign_default_payload()["signals"][key])
        if bool(entry.get("complete", False)):
            if progress_text:
                entry["progress"] = str(progress_text)
                self.save_campaign_state(state)
            return False
        entry["complete"] = True
        entry["completed_at"] = datetime.now().isoformat(timespec="seconds")
        entry["source"] = str(source or "runtime")
        entry["progress"] = str(progress_text or "complete")
        state["signals"][key] = entry
        self.save_campaign_state(state)
        count = self.campaign_signal_count(state)
        self.campaign_last_signal_count = count
        if getattr(self, "center_hint", None) is not None and not getattr(self, "campaign_title_open", False):
            self.center_hint["text"] = f"SIGNAL STABILIZED // {CAMPAIGN_SIGNAL_SPECS[key]['short']} // {count}/{len(CAMPAIGN_SIGNAL_ORDER)}"
        try:
            if getattr(self, "audio", None):
                self.audio.play('world_shift.wav', 'sfx', 0.72)
        except Exception:
            pass
        return True

    def campaign_signal_count(self, state: dict | None = None) -> int:
        state = state if isinstance(state, dict) else self.load_campaign_state(create=False)
        signals = state.get("signals") if isinstance(state.get("signals"), dict) else {}
        return sum(1 for key in CAMPAIGN_SIGNAL_ORDER if bool((signals.get(key) or {}).get("complete", False)))

    def campaign_refresh_signals(self, *, force: bool = False) -> dict:
        if not self.campaign_state_file_exists():
            return {}
        now = time.monotonic()
        if not force and (now - float(getattr(self, "campaign_last_poll_at", 0.0))) < float(getattr(self, "campaign_poll_interval", 0.75)):
            return self.campaign_state if isinstance(self.campaign_state, dict) else {}
        self.campaign_last_poll_at = now
        # The campaign file is owned by this process. Keep its merged state in
        # memory during gameplay; regional state files are checked by cheap
        # (mtime,size) signatures and parsed only when one actually changes.
        if force or not isinstance(getattr(self, "campaign_state", None), dict) or not self.campaign_state:
            state = self.load_campaign_state(create=True)
        else:
            state = self.campaign_state
        signals = state.setdefault("signals", {})
        changed = False
        for key in CAMPAIGN_SIGNAL_ORDER:
            if key in CAMPAIGN_MARKED_SIGNALS:
                continue
            complete, progress_text, source = self.campaign_probe_signal(key, force=force)
            entry = signals.setdefault(key, campaign_default_payload()["signals"][key])
            if progress_text and str(entry.get("progress", "")) != str(progress_text):
                entry["progress"] = str(progress_text)
                changed = True
            if complete and not bool(entry.get("complete", False)):
                entry["complete"] = True
                entry["completed_at"] = datetime.now().isoformat(timespec="seconds")
                entry["source"] = source
                changed = True
                count_after = sum(1 for k in CAMPAIGN_SIGNAL_ORDER if bool((signals.get(k) or {}).get("complete", False)))
                if getattr(self, "center_hint", None) is not None and not getattr(self, "campaign_title_open", False):
                    self.center_hint["text"] = f"SIGNAL STABILIZED // {CAMPAIGN_SIGNAL_SPECS[key]['short']} // {count_after}/{len(CAMPAIGN_SIGNAL_ORDER)}"
        if changed:
            self.save_campaign_state(state)
        self.campaign_last_signal_count = self.campaign_signal_count(state)
        return state

    def campaign_poll_task(self, task):
        # Panda's do-later queue is the correct authority for periodic work; do
        # not re-enter campaign synchronization from every rendered frame.
        if getattr(self, "active_native_mode", None) is None and not bool(getattr(self, "external_suspended", False)):
            if not bool(getattr(self, "campaign_title_open", False)) and not bool(getattr(self, "campaign_ending_open", False)):
                if self.campaign_state_file_exists():
                    self.campaign_refresh_signals()
        task.delayTime = float(getattr(self, "campaign_poll_interval", 0.75))
        return Task.again

    def campaign_next_objective(self, state: dict | None = None) -> tuple[str, str]:
        state = state if isinstance(state, dict) else self.load_campaign_state(create=False)
        if not state:
            first = CAMPAIGN_SIGNAL_ORDER[0]
            return first, CAMPAIGN_SIGNAL_SPECS[first]["goal"]
        if bool(state.get("completed", False)):
            return "complete", "HoloVerse is stabilized. Continue exploring any region."
        signals = state.get("signals") if isinstance(state.get("signals"), dict) else {}
        for key in CAMPAIGN_SIGNAL_ORDER:
            if not bool((signals.get(key) or {}).get("complete", False)):
                return key, str(CAMPAIGN_SIGNAL_SPECS[key]["goal"])
        return "convergence", "All nine signals are stable. Return to MatrixCore and begin Convergence."

    def campaign_ready_for_convergence(self, state: dict | None = None) -> bool:
        state = state if isinstance(state, dict) else self.load_campaign_state(create=False)
        return bool(state) and not bool(state.get("completed", False)) and self.campaign_signal_count(state) >= len(CAMPAIGN_SIGNAL_ORDER)

    def campaign_progress_text(self) -> str:
        state = self.campaign_refresh_signals(force=True) if self.campaign_state_file_exists() else {}
        if not state:
            return "No campaign signal has started yet."
        signals = state.get("signals") if isinstance(state.get("signals"), dict) else {}
        lines = []
        for key in CAMPAIGN_SIGNAL_ORDER:
            entry = signals.get(key) if isinstance(signals.get(key), dict) else {}
            mark = "STABLE" if bool(entry.get("complete", False)) else str(entry.get("progress") or "OPEN")
            lines.append(f"{CAMPAIGN_SIGNAL_SPECS[key]['short']}: {mark}")
        count = self.campaign_signal_count(state)
        _, next_goal = self.campaign_next_objective(state)
        return f"SIGNALS {count}/{len(CAMPAIGN_SIGNAL_ORDER)}\n" + "\n".join(lines) + f"\n\nNEXT: {next_goal}"

    def reset_for_new_campaign(self) -> dict:
        # Only contained runtime state is wiped. Settings, committed assets, and
        # source content remain untouched.
        try:
            if APP_DATA_DIR.exists():
                shutil.rmtree(APP_DATA_DIR)
        except Exception:
            pass
        try:
            _safe_write_json(MATRIXCORE_PROGRESSION_PATH, matrixcore_default_progression_payload())
        except Exception:
            pass
        state = campaign_default_payload()
        self.campaign_signal_probe_cache = {}
        self.campaign_signal_file_stamps = {}
        self.campaign_last_poll_at = 0.0
        self.save_campaign_state(state)
        self.matrixcore_data = self.ensure_matrixcore_foundation(force=True)
        return state

