    def show_campaign_title(self):
        self.campaign_title_open = True
        self.campaign_ending_open = False
        self.campaign_ending_root.hide()
        self.campaign_title_root.show()
        has_continue = self.campaign_state_file_exists() or self.campaign_has_legacy_progress()
        self.campaign_continue_button.show() if has_continue else self.campaign_continue_button.hide()
        if has_continue:
            state = self.load_campaign_state(create=self.campaign_state_file_exists()) if self.campaign_state_file_exists() else {}
            count = self.campaign_signal_count(state) if state else 0
            self.campaign_title_status["text"] = f"CONTINUE SIGNAL // {count}/{len(CAMPAIGN_SIGNAL_ORDER)} STABLE" if state else "CONTINUE EXISTING HOLOVERSE"
        else:
            self.campaign_title_status["text"] = "NO CAMPAIGN SAVE // BEGIN A NEW SIGNAL"
        self.hud_root.hide()
        self.crosshair_root.hide()
        props = WindowProperties(); props.setCursorHidden(False)
        if self.win is not None and hasattr(self.win, "requestProperties"): self.win.requestProperties(props)

    def _leave_campaign_title(self):
        self.campaign_title_open = False
        self.campaign_title_settings = False
        self.campaign_title_root.hide()
        if getattr(self.cfg, "hud_visible", True): self.hud_root.show()
        self.crosshair_root.show()
        props = WindowProperties(); props.setCursorHidden(not SELF_TEST)
        if self.win is not None and hasattr(self.win, "requestProperties"): self.win.requestProperties(props)
        if not SELF_TEST: self.recenter_mouse(force=True)

    def continue_campaign_from_title(self, auto_vr: bool = False):
        if not self.campaign_state_file_exists():
            self.save_campaign_state(campaign_default_payload())
        self.campaign_refresh_signals(force=True)
        self._leave_campaign_title()
        self.center_hint["text"] = "MATRIXCORE // SIGNAL CAMPAIGN ONLINE"

    def new_campaign_from_title(self):
        has_existing = self.campaign_state_file_exists() or self.campaign_has_legacy_progress()
        now = time.monotonic()
        if has_existing and now > float(getattr(self, "campaign_new_confirm_until", 0.0)):
            self.campaign_new_confirm_until = now + 4.0
            self.campaign_title_status["text"] = "NEW GAME ERASES CONTAINED CAMPAIGN STATE // PRESS AGAIN TO CONFIRM"
            return
        self.campaign_new_confirm_until = 0.0
        self.reset_for_new_campaign()
        self._leave_campaign_title()
        try:
            self.teleport_to_hub()
        except Exception:
            pass
        self.center_hint["text"] = "NEW SIGNAL // RETURN NINE REGIONAL PROOFS TO MATRIXCORE"

    def open_campaign_settings(self):
        self.campaign_title_settings = True
        self.campaign_title_root.hide()
        self.menu_open = True
        self.menu_root.show()
        self.set_menu_tab("display")
        props = WindowProperties(); props.setCursorHidden(False)
        if self.win is not None and hasattr(self.win, "requestProperties"): self.win.requestProperties(props)

    def begin_campaign_convergence(self):
        state = self.campaign_refresh_signals(force=True)
        if not self.campaign_ready_for_convergence(state):
            _, goal = self.campaign_next_objective(state)
            self.center_hint["text"] = f"CONVERGENCE LOCKED // {goal.upper()}"
            return False
        if int(self.current_holoverse_region_number()) != 0:
            self.center_hint["text"] = "CONVERGENCE // RETURN TO MATRIXCORE FIRST"
            return False
        state["completed"] = True
        state["completed_at"] = datetime.now().isoformat(timespec="seconds")
        state["convergence_seen"] = True
        self.save_campaign_state(state)
        if getattr(self, "core_console_open", False): self.close_core_console()
        self.campaign_ending_open = True
        self.campaign_ending_root.show()
        self.hud_root.hide(); self.crosshair_root.hide()
        props = WindowProperties(); props.setCursorHidden(False)
        if self.win is not None and hasattr(self.win, "requestProperties"): self.win.requestProperties(props)
        try:
            if self.audio: self.audio.play('world_shift.wav', 'sfx', 0.95)
        except Exception: pass
        return True

    def close_campaign_ending(self):
        self.campaign_ending_open = False
        self.campaign_ending_root.hide()
        if getattr(self.cfg, "hud_visible", True): self.hud_root.show()
        self.crosshair_root.show()
        props = WindowProperties(); props.setCursorHidden(not SELF_TEST)
        if self.win is not None and hasattr(self.win, "requestProperties"): self.win.requestProperties(props)
        if not SELF_TEST: self.recenter_mouse(force=True)
        self.center_hint["text"] = "HOLOVERSE STABILIZED // FREE EXPLORATION"

    def return_to_campaign_title(self):
        self.campaign_ending_open = False
        self.campaign_ending_root.hide()
        self.show_campaign_title()

    def campaign_title_smoke_setup(self, task):
        self.show_campaign_title()
        return Task.done

    def campaign_title_smoke_capture(self, task):
        try: self.win.saveScreenshot(Filename.fromOsSpecific(os.fspath(LOG_DIR / "campaign_title_smoke.bmp")))
        except Exception: pass
        return Task.done

    def campaign_title_smoke_exit(self, task):
        self.userExit(); return Task.done

    def campaign_ending_smoke_setup(self, task):
        state = campaign_default_payload()
        for key in CAMPAIGN_SIGNAL_ORDER:
            state["signals"][key]["complete"] = True
            state["signals"][key]["progress"] = "complete"
        self.save_campaign_state(state)
        self.campaign_title_open = False; self.campaign_title_root.hide()
        self.begin_campaign_convergence()
        return Task.done

    def campaign_ending_smoke_capture(self, task):
        try: self.win.saveScreenshot(Filename.fromOsSpecific(os.fspath(LOG_DIR / "campaign_ending_smoke.bmp")))
        except Exception: pass
        return Task.done

    def campaign_ending_smoke_exit(self, task):
        self.userExit(); return Task.done

    def campaign_progression_smoke_setup(self, task):
        # Build deterministic minimum-completion fixtures using the exact state
        # files the regional runtimes own, then let the normal probe code find
        # them. This validates campaign progression without bypassing it.
        fixtures = {
            "forest_growth": {"summary": {"total_plants": 5}, "plants": []},
            "oddities": {"summary": {"total_oddities": 3}, "items": []},
            "ember_hangar": {"default_ship_id": "smoke_ship"},
            "frost_circuit": {"races_completed": 1},
            "urban_warzone": {"best_wave": 3, "last_wave": 3},
        }
        paths = self.campaign_signal_state_paths()
        for key, payload in fixtures.items():
            path = paths[key]
            path.parent.mkdir(parents=True, exist_ok=True)
            _safe_write_json(path, payload)
        self.save_campaign_state(campaign_default_payload())
        # Pass 282.57: the three gate signals are marked the way a gate entry marks them.
        for title, key in CAMPAIGN_GATE_SIGNAL_BY_TITLE.items():
            self.mark_campaign_signal(key, source="campaign_progression_smoke", progress_text=f"entered {title}")
        before = self.campaign_refresh_signals(force=True)
        count_before_space = self.campaign_signal_count(before)
        self.mark_campaign_signal("holospace", source="campaign_progression_smoke", progress_text="Dyson Reach")
        ready = self.campaign_refresh_signals(force=True)
        count_ready = self.campaign_signal_count(ready)
        convergence_ready = self.campaign_ready_for_convergence(ready)
        convergence_triggered = self.begin_campaign_convergence()
        final_state = self.load_campaign_state(create=False)
        report = {
            "kind": "holoverse_pass23_campaign_progression_smoke",
            "count_before_holospace": count_before_space,
            "count_ready": count_ready,
            "expected_signals": len(CAMPAIGN_SIGNAL_ORDER),
            "all_signals": {key: bool((final_state.get("signals", {}).get(key) or {}).get("complete", False)) for key in CAMPAIGN_SIGNAL_ORDER},
            "convergence_ready": bool(convergence_ready),
            "convergence_triggered": bool(convergence_triggered),
            "campaign_completed": bool(final_state.get("completed", False)),
            "ending_open": bool(self.campaign_ending_open),
            "contained_state": str(CAMPAIGN_STATE_PATH).startswith(str(ROOT)),
        }
        report["pass"] = (
            count_before_space == 8
            and count_ready == len(CAMPAIGN_SIGNAL_ORDER)
            and all(report["all_signals"].values())
            and report["convergence_ready"]
            and report["convergence_triggered"]
            and report["campaign_completed"]
            and report["ending_open"]
            and report["contained_state"]
        )
        _safe_write_json(LOG_DIR / "campaign_progression_smoke_report.json", report)
        print("campaign_progression_smoke=" + json.dumps(report, sort_keys=True))
        return Task.done

    def campaign_progression_smoke_capture(self, task):
        try:
            self.win.saveScreenshot(Filename.fromOsSpecific(os.fspath(LOG_DIR / "campaign_progression_smoke.bmp")))
        except Exception:
            pass
        return Task.done

    def campaign_progression_smoke_exit(self, task):
        self.userExit(); return Task.done

    def setup_audio(self):
        self.audio = SharedAudio(self)
        self.soundscape_key = None
        self.soundscape_loop = None
        self.soundscape_base_loop = None
        self.soundscape_air_base_loop = None
        self.soundscape_air_loop = None
        self.soundscape_stinger_at = 0.0
        if self.audio and self.audio.enabled:
            self.update_soundscape(0.0, force=True)

    def _world_soundscape_from_text(self, text: str):
        low = str(text or '').lower()
        if any(token in low for token in ('holospace', 'space', 'orbit')):
            return ('space', 'space', '', 0.56, 0.0, 'HoloSpace reach')
        if 'urban' in low or 'sable' in low or 'war' in low or 'combat' in low:
            return ('urban', 'urban', '', 0.64, 0.0, 'urban region')
        if 'metropolis' in low or 'archivist' in low or 'city' in low or 'neon' in low:
            return ('metropolis', 'metropolis', '', 0.58, 0.0, 'metropolis region')
        if 'ice' in low or 'mirror' in low or 'frost' in low:
            return ('ice', 'ice', '', 0.48, 0.0, 'ice region')
        if 'mushroom' in low or 'solace' in low or 'oddities' in low or 'spore' in low or 'water' in low or 'deep' in low:
            return ('mushroom', 'mushroom', '', 0.46, 0.0, 'mushroom region')
        if 'desert' in low or 'ember' in low or 'hangar' in low:
            return ('desert', 'desert', '', 0.52, 0.0, 'desert region')
        if 'hill' in low or 'nyx' in low:
            return ('hills', 'hills', '', 0.50, 0.0, 'green hills region')
        if 'forest' in low or 'vanta' in low or 'growth' in low:
            return ('forest', 'forest', '', 0.50, 0.0, 'forests region')
        if 'holoforge' in low or 'forge' in low:
            return ('holoforge', 'holoforge', '', 0.52, 0.0, 'holoforge')
        return None

    def _target_soundscape(self):
        soundtrack_on = bool(getattr(self.cfg, 'soundtrack_enabled', True))
        intensity = max(0.0, min(1.0, float(getattr(self.cfg, 'soundtrack_intensity', 0.55))))
        ambience = max(0.0, min(1.0, float(getattr(self.cfg, 'ambience_intensity', 0.45))))
        if not soundtrack_on:
            return ('muted', '', '', 0.0, 0.0, 'soundtrack muted')

        if bool(getattr(self, 'holospace_active', False)):
            return ('space', 'space', '', 0.44 + 0.22 * intensity, 0.0, 'holospace orbit')

        if bool(getattr(self, 'world_unlocked', False)) or float(getattr(self, 'transition_target', 0.0)) > 0.0 or float(getattr(self, 'transition_progress', 0.0)) > 0.02:
            spec = {}
            try:
                spec = self.current_world_spec() or {}
            except Exception:
                spec = {}
            name = ' '.join(str(spec.get(k, '')) for k in ('name', 'kind', 'profile'))
            mapped = self._world_soundscape_from_text(name)
            if mapped is None:
                mapped = ('artifact', '', '', 0.0, 0.0, 'artifact world (no region track)')
            key, music, air, music_gain, air_gain, label = mapped
            return (f'artifact_{key}', music, air, min(0.72, music_gain + 0.16 * intensity), min(0.30, air_gain + 0.08 * ambience), label)

        shell_audio = self.world_shell_audio_handoff if isinstance(getattr(self, 'world_shell_audio_handoff', {}), dict) else {}
        zone = self.current_zone_name()
        shell_text = ' '.join([
            str(zone),
            str(getattr(self, 'world_shell_mount_biome', '')),
            str(shell_audio.get('active_biome', '')),
            str(shell_audio.get('tone', '')),
            str(shell_audio.get('recommended_loop', '')),
        ])
        mapped = self._world_soundscape_from_text(shell_text)
        if mapped and bool(getattr(self.cfg, 'world_shell_audio_handoff', True)):
            key, music, air, music_gain, air_gain, label = mapped
            influence = 0.0
            try:
                influence = max(0.0, min(1.0, float(shell_audio.get('influence', 0.0))))
            except Exception:
                influence = 0.0
            return (f'shell_{key}', music, air, min(0.70, music_gain + 0.16 * intensity + influence * 0.10), min(0.30, air_gain + ambience * 0.08), label)

        r = math.sqrt(self.player_pos.x ** 2 + self.player_pos.y ** 2)
        if r < self.hub_radius + 1.0:
            return ('hub', 'hub', '', 0.38 + 0.22 * intensity, 0.0, 'matrixcore hub')
        # Pass 282.79: the FLAT region (the hub ring and the open land around it) keeps Holoverse.mp3.
        return ('hub', 'hub', '', 0.38 + 0.22 * intensity, 0.0, 'flat region')

    def update_soundscape(self, dt: float = 0.0, *, force: bool = False):
        if not self.audio:
            return
        self.audio.refresh_mix()
        # Same-window activities own the one master music stream while active.
        if getattr(self, "active_native_mode", None) is not None or getattr(self, "external_process", None) is not None:
            try:
                self.audio.stop_loop("hub_music")
                self.audio.stop_loop("hub_air")
            except Exception:
                pass
            return
        key, cue_name, _air, music_gain, _air_gain, label = self._target_soundscape()
        now = time.time()
        scene_changed = force or key != getattr(self, 'soundscape_key', None) or cue_name != getattr(self, 'soundscape_base_loop', None)
        if scene_changed:
            self.soundscape_key = key
            self.soundscape_base_loop = cue_name
            self.soundscape_loop = cue_name
            if not force and now - float(getattr(self, 'soundscape_stinger_at', 0.0)) > 1.6:
                self.audio.play('world_shift.wav', bus='sfx', volume=0.18)
                self.soundscape_stinger_at = now
        if cue_name:
            self.audio.play_loop('hub_music', cue_name, bus='music', volume=max(0.0, min(1.0, music_gain)))
        else:
            self.audio.stop_loop('hub_music')
        self.audio.stop_loop('hub_air')
        region = resolve_region_music_track(cue_name) if cue_name else None
        if region is not None:
            track = region[1].name.upper() if region[1] is not None else "NO TRACK (SILENT)"
            self.world_shell_audio_status = f"{str(label or key).upper()} // {region[0].upper()} // {track} // LOOP"
        else:
            self.world_shell_audio_status = f"{str(label or key).upper()} // NO MUSIC"

    def setup_vr(self):
        # Desktop first-person mode is authoritative unless VR is explicitly requested.
        # This prevents old VR config files or missing headset runtimes from hijacking normal startup.
        if VR_DISABLED:
            self.vr_status = "DESKTOP // VR DISABLED"
            self.cfg.vr_enabled = False
            save_config(self.cfg)
            return
        if not VR_ALLOWED:
            self.vr_status = "DESKTOP // VR OPT-IN"
            return
        if P3DOpenXR is None:
            self.vr_status = "DESKTOP // XR MODULE MISSING"
            return
        self.cfg.vr_enabled = True
        save_config(self.cfg)
        try:
            self.vr_origin = self.render.attachNewNode("vr-origin")
            self.vr_origin.setPos(0, -10, 0)
            self.xr = P3DOpenXR(self)
            self.xr.init(root=self.vr_origin, mirroring=1, mirror_mode="average", near=0.05, far=self.cfg.fog_distance)
            self.vr_active = True
            self.vr_status = "OPENXR ACTIVE"
            self.cfg.player_eye_height = 3.95
            self.build_vr_hand_debug()
        except Exception as exc:
            self.xr = None
            self.vr_origin = None
            self.vr_active = False
            self.vr_status = f"DESKTOP // XR FALLBACK: {exc.__class__.__name__}"
            print(f"openxr_init_failed: {exc}")

    def build_vr_hand_debug(self):
        if not self.xr:
            return
        hand_color_left = (0.42, 0.86, 1.0, 0.88)
        hand_color_right = (1.0, 0.42, 0.64, 0.88)
        for side, anchor, color in (("left", self.xr.left_hand_anchor, hand_color_left), ("right", self.xr.right_hand_anchor, hand_color_right)):
            segs = LineSegs(f"vr-hand-{side}")
            segs.setThickness(max(1.4, self.cfg.line_thickness * 0.9))
            segs.setColor(*color)
            palm = [Vec3(-0.05, 0.0, -0.03), Vec3(0.05, 0.0, -0.03), Vec3(0.06, 0.0, 0.04), Vec3(-0.06, 0.0, 0.04)]
            segs.moveTo(palm[0]); segs.drawTo(palm[1]); segs.drawTo(palm[2]); segs.drawTo(palm[3]); segs.drawTo(palm[0])
            for fx in (-0.04, -0.015, 0.015, 0.04):
                segs.moveTo(fx, 0.0, 0.035)
                segs.drawTo(fx, 0.12, 0.03)
            segs.moveTo(-0.06, 0.0, -0.005); segs.drawTo(-0.12 if side == "left" else 0.0, 0.06, -0.01)
            node = anchor.attachNewNode(segs.create())
            node.setAntialias(AntialiasAttrib.MLine)
            node.setTransparency(TransparencyAttrib.MAlpha)
            if side == "left":
                self.vr_left_hand = node
            else:
                self.vr_right_hand = node

    def head_world_pos(self):
        if self.vr_active and self.xr and getattr(self.xr, "hmd_anchor", None) is not None:
            try:
                return self.xr.hmd_anchor.getPos(self.render)
            except Exception:
                pass
        return Vec3(self.player_pos)

    def get_view_basis(self):
        if self.vr_active and self.xr and getattr(self.xr, "hmd_anchor", None) is not None:
            quat = self.xr.hmd_anchor.getQuat(self.render)
        else:
            quat = self.camera.getQuat(self.render)
        forward = quat.getForward()
        right = quat.getRight()
        up = quat.getUp()
        return forward, right, up

    def sync_player_from_vr(self):
        if self.vr_active:
            self.player_pos = self.head_world_pos()
            base_offset = float(getattr(self.cfg, "vr_height_offset", 0.0))
            if getattr(self.cfg, "vr_seated_mode", False):
                base_offset += 0.55
            self.player_pos.z += base_offset

    def current_vr_turn_mode(self):
        mode = str(getattr(self.cfg, "vr_turn_mode", "snap")).strip().lower()
        return mode if mode in {"snap", "smooth"} else "snap"

    def update_vr_turn(self, dt):
        if not self.vr_active or self.vr_origin is None or self.menu_open:
            return
        self.vr_turn_cooldown = max(0.0, self.vr_turn_cooldown - dt)
        turn_axis = 0.0
        if self.keys.get("q"):
            turn_axis += 1.0
        if self.keys.get("e"):
            turn_axis -= 1.0
        if self.gamepad:
            try:
                rx = self.gamepad.findAxis(InputDevice.Axis.right_x)
                if rx and abs(rx.value) > 0.22:
                    turn_axis += -rx.value
            except Exception:
                pass
        if abs(turn_axis) < 0.001:
            return
        pivot = self.head_world_pos()
        rel = self.vr_origin.getPos(self.render) - pivot
        if self.current_vr_turn_mode() == "smooth":
            step = max(-1.0, min(1.0, turn_axis)) * float(getattr(self.cfg, "vr_smooth_turn_rate", 75.0)) * dt
        else:
            if self.vr_turn_cooldown > 0.0:
                return
            step = float(getattr(self.cfg, "vr_snap_turn_degrees", 30.0)) * (1.0 if turn_axis > 0 else -1.0)
            self.vr_turn_cooldown = 0.22
        ang = math.radians(step)
        rot = Vec3(rel.x * math.cos(ang) - rel.y * math.sin(ang), rel.x * math.sin(ang) + rel.y * math.cos(ang), rel.z)
        self.vr_origin.setPos(pivot + rot)
        self.vr_origin.setH(self.vr_origin.getH() + step)
        self.sync_player_from_vr()

    def setup_window(self):
        props = WindowProperties()
        props.setTitle(GAME_NAME)
        props.setSize(LAUNCH_W, LAUNCH_H)
        props.setCursorHidden(not SELF_TEST)
        if not SELF_TEST:
            props.setForeground(True)
            if LAUNCH_BORDERLESS:
                props.setUndecorated(True)
                props.setOrigin(LAUNCH_X, LAUNCH_Y)
                props.setSize(LAUNCH_W, LAUNCH_H)
                props.setFullscreen(False)
                props.setFixedSize(True)
            elif LAUNCH_BORDERED_FULLSCREEN:
                props.setUndecorated(False)
                props.setOrigin(LAUNCH_X, LAUNCH_Y)
                props.setSize(LAUNCH_W, LAUNCH_H)
                props.setFullscreen(False)
                props.setFixedSize(False)
            else:
                props.setUndecorated(False)
                props.setFullscreen(bool(LAUNCH_FULLSCREEN))
        if self.win is not None and hasattr(self.win, "requestProperties"):
            self.win.requestProperties(props)
        self.setBackgroundColor(self.cfg.background_value, self.cfg.background_value, self.cfg.background_value)

    def setup_scene(self):
        self.root_3d = self.render.attachNewNode("root-3d")
        self.surface_root = self.root_3d.attachNewNode("surface-root")
        self.line_root = self.root_3d.attachNewNode("line-root")
        self.accent_root = self.root_3d.attachNewNode("accent-root")
        self.dome_root = self.root_3d.attachNewNode("dome-root")
        self.lens_root = self.root_3d.attachNewNode("lens-root")
        self.sky_root = self.root_3d.attachNewNode("sky-root")
        self.world_root = self.root_3d.attachNewNode("world-root")
        self.galaxy_root = self.root_3d.attachNewNode("galaxy-root")
        self.world_root.setTransparency(TransparencyAttrib.MAlpha)
        self.galaxy_root.setTransparency(TransparencyAttrib.MAlpha)
        self.camLens.setNearFar(0.05, self.cfg.fog_distance)
        self.camLens.setFov(self.cfg.fov)

        self.fog = Fog("hub-fog")
        self.hub_base_bg_rgb = (self.cfg.background_value, self.cfg.background_value, self.cfg.background_value)
        self.hub_base_fog_near = self.cfg.fog_distance * 0.48
        self.hub_base_fog_far = self.cfg.fog_distance
        self.fog.setColor(*self.hub_base_bg_rgb)
        self.fog.setLinearRange(self.hub_base_fog_near, self.hub_base_fog_far)
        self.render.setFog(self.fog)

        self.hub_base_ambient_rgb = (0.58, 0.62, 0.68)
        self.hub_base_sun_rgb = (0.34, 0.37, 0.42)
        self.ambient_light = AmbientLight("ambient")
        self.ambient_light.setColor((*self.hub_base_ambient_rgb, 1.0))
        self.ambient_light_np = self.render.attachNewNode(self.ambient_light)
        self.render.setLight(self.ambient_light_np)

        self.sun_light = DirectionalLight("sun")
        self.sun_light.setColor((*self.hub_base_sun_rgb, 1.0))
        self.sun_np = self.render.attachNewNode(self.sun_light)
        self.sun_np.setHpr(-20, -48, 0)
        self.render.setLight(self.sun_np)

    def load_static_hub_texture(self, name: str):
        """Load a committed Hub texture without generating or mutating assets."""
        path = HUB_TEXTURE_DIR / name
        tex = self.loader.loadTexture(Filename.fromOsSpecific(str(path))) if path.exists() else None
        if tex:
            tex.setWrapU(SamplerState.WM_repeat)
            tex.setWrapV(SamplerState.WM_repeat)
            tex.setMinfilter(SamplerState.FT_linear_mipmap_linear)
            tex.setMagfilter(SamplerState.FT_linear)
        return tex

    def ensure_hub_textures(self):
        """Install the two authored MatrixCore texture authorities.

        Pass 25 deliberately uses one shared outer-space texture on every Hub
        structural infill surface.  There is no launch-time texture generation:
        wall, ceiling, dome, and the lower wall belt all read the same committed
        matrixcore_space.png asset so the Hub looks open to a continuous void
        from both its interior and exterior-facing sides.
        """
        space = self.load_static_hub_texture("matrixcore_space.png")
        core = self.load_static_hub_texture("hub_core.png")
        self.hub_textures = {
            "space": space,
            "wall": space,
            "ceiling": space,
            "dome": space,
            "core": core,
        }

    def add_textured_panel(self, parent, pos, hpr, sx, sy, texture_key, alpha=1.0, tex_scale=(1.0, 1.0), two_sided=True):
        cm = CardMaker(f"panel-{texture_key}")
        cm.setFrame(-sx * 0.5, sx * 0.5, -sy * 0.5, sy * 0.5)
        np = parent.attachNewNode(cm.generate())
        np.setPos(pos)
        np.setHpr(hpr)
        np.setTransparency(TransparencyAttrib.MAlpha)
        np.setColor(1, 1, 1, alpha)
        np.setDepthWrite(False)
        if two_sided:
            np.setTwoSided(True)
        tex = self.hub_textures.get(texture_key)
        if tex:
            np.setTexture(tex, 1)
            np.setTexScale(TextureStage.getDefault(), tex_scale[0], tex_scale[1])
        if texture_key in {"space", "wall", "ceiling", "dome"}:
            np.setPythonTag("matrixcore_space_surface", True)
        self.hub_fill_nodes.append(np)
        return np

    def build_hub_infill(self):
        self.hub_fill_nodes = []
        # 282.5 side walls are intentionally NOT textured infill.  The restrained
        # HoloCore-style bay cards are built by add_home_wall_occlusion_belt();
        # duplicating them here would recreate the broad red slabs this pass removes.

        # MatrixCore inner panels scale upward with the enlarged observatory but
        # remain compact enough that Gleebs still owns the readable center.
        for i in range(8):
            ang = math.radians(22.5) + math.tau * i / 8
            n = Vec3(math.cos(ang), math.sin(ang), 0)
            pos = n * 2.30 + Vec3(0, 0, 4.05)
            self.add_textured_panel(self.surface_root, pos, Vec3(math.degrees(ang) + 90, 0, 0), 1.72, 7.35, "core", tex_scale=(1.0, 2.15))

        self.matrixcore_core_nodes = []

        # Keep the central ceiling open. Eight upper dome facets follow the new
        # octagonal ribs, leaving an oculus over MatrixCore rather than a single
        # giant square card cutting across the observatory.
        dome_bands = [
            (25.5, 10.9, 14.0, 0.92),
            (21.0, 14.0, 17.6, 0.80),
            (15.8, 17.6, 21.2, 0.66),
        ]
        for width, z0, z1, radius_scale in dome_bands:
            pitch = -24.0 - (z0 - 10.9) * 1.55
            radius = (self.hub_radius - 2.8) * radius_scale
            for i in range(8):
                ang = math.radians(22.5) + math.tau * i / 8
                n = Vec3(math.cos(ang), math.sin(ang), 0)
                pos = n * radius + Vec3(0, 0, (z0 + z1) * 0.5)
                self.add_textured_panel(self.surface_root, pos, Vec3(math.degrees(ang) + 90, pitch, 0), width, z1 - z0, "dome", alpha=0.72, tex_scale=(1.35, 0.56))
        self.update_hub_fill_visuals(force=True)


    def set_hub_fill_enabled(self, enabled: bool, instant=False):
        self.cfg.hub_fill_enabled = enabled
        self.hub_fill_target = 1.0 if enabled else 0.0
        if instant:
            self.hub_fill_alpha = self.hub_fill_target
            self.update_hub_fill_visuals(force=True)
        save_config(self.cfg)

    def update_hub_fill_visuals(self, force=False):
        alpha = self.hub_fill_alpha * self.cfg.hub_fill_opacity
        fill_nodes = list(getattr(self, "hub_fill_nodes", []) or [])
        fill_nodes.extend(list(getattr(self, "observatory_bay_fill_nodes", []) or []))
        for np in fill_nodes:
            np.setColorScale(1, 1, 1, alpha)
            if alpha > 0.001:
                np.show()
            else:
                np.hide()

    def build_gleebs_hologram(self):
        """Project Gleebs as MatrixCore's in-world hologram without adding UI boxes."""
        try:
            if getattr(self, "gleebs_hologram_root", None) is not None:
                self.gleebs_hologram_root.removeNode()
        except Exception:
            pass
        self.gleebs_hologram_parts = []
        self.gleebs_hologram_root = self.accent_root.attachNewNode("matrixcore-gleebs-hologram")
        self.gleebs_hologram_root.setPos(0, 0, 3.55)
        self.gleebs_hologram_root.setTransparency(TransparencyAttrib.MAlpha)
        self.gleebs_hologram_alpha = 0.0
        self.gleebs_hologram_target_alpha = 0.0
        self.gleebs_hologram_distance = 999.0
        self.gleebs_hologram_root.setAlphaScale(0.0)
        self.gleebs_hologram_root.hide()
        for idx, (radius, z, alpha) in enumerate(((1.18, -1.02, 0.54), (1.58, -0.82, 0.34), (0.72, 1.15, 0.24))):
            node = self.add_polyline(self.gleebs_hologram_root, self.polygon_points(radius, z, 48, 0), (0.18, 1.0, 1.0, alpha), self.cfg.line_thickness * (0.78 if idx == 0 else 0.54), True, "gleebs-holo-ring")
            self.gleebs_hologram_parts.append(node)
        for i in range(8):
            a = math.tau * i / 8.0
            p0 = Vec3(math.cos(a) * 0.72, math.sin(a) * 0.72, -0.92)
            p1 = Vec3(math.cos(a) * 0.30, math.sin(a) * 0.30, 1.32)
            node = self.add_polyline(self.gleebs_hologram_root, [p0, p1], (0.10, 0.88, 1.0, 0.20), self.cfg.line_thickness * 0.42, False, "gleebs-holo-column")
            self.gleebs_hologram_parts.append(node)
        tex = None
        try:
            gleebs_texture_source = GLEEBS_TEXTURE_POT_PATH if GLEEBS_TEXTURE_POT_PATH.exists() else GLEEBS_TEXTURE_PATH
            if gleebs_texture_source.exists():
                tex = self.loader.loadTexture(Filename.fromOsSpecific(str(gleebs_texture_source)))
                tex.setMinfilter(SamplerState.FT_linear_mipmap_linear)
                tex.setMagfilter(SamplerState.FT_linear)
        except Exception:
            tex = None
        cm = CardMaker("gleebs-hologram-card")
        cm.setFrame(-0.92, 0.92, -1.12, 1.12)
        card = self.gleebs_hologram_root.attachNewNode(cm.generate())
        card.setPos(0, -0.06, 0.20)
        card.setTransparency(TransparencyAttrib.MAlpha)
        card.setTwoSided(True)
        card.setLightOff(1)
        card.setDepthWrite(False)
        try:
            card.setBin("transparent", 30)
            card.setBillboardPointEye()
        except Exception:
            pass
        if tex is not None:
            card.setTexture(tex, 1)
            card.setColorScale(1.0, 0.08, 0.08, 0.72)
        else:
            card.setColor(1.0, 0.06, 0.06, 0.22)
        self.gleebs_hologram_card = card
        self.gleebs_hologram_parts.append(card)
        return self.gleebs_hologram_root

    def update_gleebs_hologram(self, dt: float = 0.0):
        root = getattr(self, "gleebs_hologram_root", None)
        if root is None or root.isEmpty():
            return

        # 282.20: Gleebs is a terminal presence, not a binary proximity prop.
        # Measure against the actual hologram/terminal world position rather than
        # assuming the station origin, then ease the whole hierarchy in/out.
        try:
            terminal_pos = root.getPos(self.render)
            dx = float(self.player_pos.x) - float(terminal_pos.x)
            dy = float(self.player_pos.y) - float(terminal_pos.y)
            dist = math.sqrt(dx * dx + dy * dy)
        except Exception:
            dist = math.sqrt(float(self.player_pos.x) ** 2 + float(self.player_pos.y) ** 2)
        self.gleebs_hologram_distance = dist
        target_alpha = terminal_proximity_alpha(dist, full_distance=6.5, hidden_distance=14.5)
        self.gleebs_hologram_target_alpha = target_alpha
        current_alpha = approach_fade(
            float(getattr(self, "gleebs_hologram_alpha", 0.0)),
            target_alpha,
            max(0.0, float(dt)),
            response=6.5,
        )
        self.gleebs_hologram_alpha = current_alpha

        if current_alpha <= 0.002 and target_alpha <= 0.001:
            root.setAlphaScale(0.0)
            root.hide()
            return
        root.show()
        root.setAlphaScale(current_alpha)

        t = float(getattr(self, "elapsed", 0.0))
        pulse = 0.5 + 0.5 * math.sin(t * 3.1)
        root.setZ(3.55 + math.sin(t * 1.35) * 0.10)
        root.setH(root.getH() + dt * 10.0)
        card = getattr(self, "gleebs_hologram_card", None)
        if card is not None and not card.isEmpty():
            alpha = 0.54 + pulse * 0.20
            card.setColorScale(1.0, 0.06 + pulse * 0.06, 0.06, alpha)
        for node in getattr(self, "gleebs_hologram_parts", []) or []:
            try:
                if node is card:
                    continue
                node.setColorScale(1.0, 0.04 + pulse * 0.06, 0.04, 0.55 + pulse * 0.30)
            except Exception:
                pass

    def gleebs_dialogue_line(self, dialogue_id: str) -> str:
        override = str(getattr(self, "gleebs_dialogue_text_override", "") or "").strip()
        data = dict(getattr(self, "gleebs_dialogue_data", {}) or self.ensure_gleebs_dialogue_seed())
        lines = data.get("lines", {}) if isinstance(data.get("lines"), dict) else {}
        raw = str(lines.get(dialogue_id, dialogue_id)).strip()
        if dialogue_id == "gleebs_welcome_001":
            return "Hey. I'm Gleebs. MatrixCore is home. Choose an experiment when you're ready."
        if dialogue_id == "gleebs_first_return_001":
            return str(getattr(self, "gleebs_return_line", "") or "") or "Welcome home. MatrixCore has the return signal."
        if override and "{guidance}" in raw:
            raw = raw.replace("{guidance}", override)
        if "{dimension}" in raw or "{advice}" in raw:
            dimension = str(getattr(self, "gleebs_dialogue_dimension", "") or "")
            advice = str(getattr(self, "gleebs_dialogue_advice", "") or "")
            raw = raw.replace("{dimension}", dimension or "unknown dimension").replace("{advice}", advice or "Signal pending.")
        if "{bot}" in raw or "{role}" in raw or "{support}" in raw or "{mode}" in raw:
            bot = str(getattr(self, "gleebs_dialogue_bot", "") or "")
            role = str(getattr(self, "gleebs_dialogue_bot_role", "") or "")
            support = str(getattr(self, "gleebs_dialogue_bot_support", "") or "")
            mode = str(getattr(self, "gleebs_dialogue_bot_mode", "") or "")
            raw = raw.replace("{bot}", bot or "that bot").replace("{role}", role or "builder ally").replace("{support}", support or "MatrixCore has logged the support signal.").replace("{mode}", mode or "that dimension")
        return raw

    def gleebs_dialogue_quote(self, dialogue_id: str) -> str:
        """Return a short bottom personality quote for Gleebs' transient signal."""
        data = dict(getattr(self, "gleebs_dialogue_data", {}) or self.ensure_gleebs_dialogue_seed())
        bank = data.get("bottom_quotes", {}) if isinstance(data.get("bottom_quotes"), dict) else {}
        choices = bank.get(str(dialogue_id)) or bank.get("default") or []
        if isinstance(choices, str):
            choices = [choices]
        choices = [str(item).strip() for item in list(choices or []) if str(item).strip()]
        if not choices:
            return ""
        try:
            # Stable per dialogue/event enough to feel varied without changing every frame.
            token = f"{dialogue_id}:{int(time.monotonic() * 10)}:{getattr(self, 'gleebs_last_context_signal', 'boot')}"
            idx = abs(hash(token)) % len(choices)
        except Exception:
            idx = 0
        return choices[idx]

    def gleebs_dialogue_signature(self, dialogue_id: str) -> str:
        quote = str(getattr(self, "gleebs_current_quote", "") or self.gleebs_dialogue_quote(dialogue_id))
        return f"Gleebs // {quote}" if quote else "Gleebs // MatrixCore signal"

    def gleebs_dialogue_panel_blocked(self) -> bool:
        """Return True when a persistent UI or launched mode should suppress Gleebs' transient voice overlay."""
        return bool(
            getattr(self, "menu_open", False)
            or getattr(self, "bot_dialogue_open", False)
            or getattr(self, "active_native_mode", None) is not None
            or getattr(self, "external_process", None) is not None
            or getattr(self, "external_suspended", False)
        )

    def update_gleebs_dialogue_safe_lane(self):
        """Pass 282.63: Gleebs speaks in a bottom-centre subtitle box."""
        try:
            self._layout_gleebs_caption()
        except Exception:
            pass

    def queue_gleebs_dialogue(self, dialogue_id: str, *, flag: str | None = None, duration: float = 8.0, mark_seen: bool = True, requires_near_core: bool = True, once: bool = True) -> bool:
        dialogue_id = str(dialogue_id or "").strip()
        if not dialogue_id:
            return False
        # Pass 06: Gleebs has three normal-play jobs only. Historical dialogue
        # remains archived in the data file, but it cannot re-enter the live queue.
        allowed = {"gleebs_welcome_001", "matrixcore_home_signal_001", "gleebs_first_return_001"}
        if dialogue_id not in allowed and not bool(getattr(self, "developer_diagnostics_enabled", False)):
            return False
        flag = str(flag or dialogue_id).strip()
        if once and self.matrixcore_dialogue_flag_seen(flag):
            return False
        active_id = str(getattr(self, "gleebs_dialogue_id", "") or "")
        if active_id == dialogue_id:
            return False
        for item in list(getattr(self, "gleebs_dialogue_queue", []) or []):
            if str(item.get("id", "")) == dialogue_id or str(item.get("flag", "")) == flag:
                return False
        max_queue = 4
        try:
            progress = self.load_matrixcore_progression()
            max_queue = int((progress.get("dialogue_queue_policy") or {}).get("max_queue", max_queue))
        except Exception:
            pass
        queue = list(getattr(self, "gleebs_dialogue_queue", []) or [])
        if len(queue) >= max_queue:
            queue = queue[-max_queue + 1:]
        queue.append({
            "id": dialogue_id,
            "flag": flag,
            "duration": float(duration or 8.0),
            "mark_seen": bool(mark_seen),
            "requires_near_core": bool(requires_near_core),
            "once": bool(once),
        })
        self.gleebs_dialogue_queue = queue
        return True

    def queue_gleebs_sequence(self, items: list[dict]) -> int:
        count = 0
        for item in list(items or []):
            if not isinstance(item, dict):
                continue
            if self.queue_gleebs_dialogue(
                str(item.get("id", "")),
                flag=str(item.get("flag") or item.get("id", "")),
                duration=float(item.get("duration", 8.0) or 8.0),
                mark_seen=bool(item.get("mark_seen", True)),
                requires_near_core=bool(item.get("requires_near_core", True)),
                once=bool(item.get("once", True)),
            ):
                count += 1
        return count

    def pump_gleebs_dialogue_queue(self):
        if not hasattr(self, "gleebs_dialogue_root"):
            return False
        if getattr(self, "gleebs_dialogue_active", False):
            return False
        if self.gleebs_dialogue_panel_blocked():
            return False
        if time.monotonic() < float(getattr(self, "gleebs_dialogue_queue_wait_until", 0.0) or 0.0):
            return False
        queue = list(getattr(self, "gleebs_dialogue_queue", []) or [])
        while queue:
            item = dict(queue.pop(0) or {})
            self.gleebs_dialogue_queue = queue
            flag = str(item.get("flag") or item.get("id") or "")
            if bool(item.get("once", True)) and flag and self.matrixcore_dialogue_flag_seen(flag):
                continue
            if bool(item.get("requires_near_core", True)) and not self.is_near_core():
                queue.insert(0, item)
                self.gleebs_dialogue_queue = queue
                return False
            return self.show_gleebs_dialogue(
                str(item.get("id", "")),
                flag=flag,
                duration=float(item.get("duration", 8.0) or 8.0),
                mark_seen=bool(item.get("mark_seen", True)),
            )
        self.gleebs_dialogue_queue = []
        return False

    def show_gleebs_dialogue(self, dialogue_id: str, *, flag: str | None = None, duration: float = 10.0, mark_seen: bool = True):
        text = self.gleebs_dialogue_line(dialogue_id)
        if not text:
            return False
        if self.gleebs_dialogue_panel_blocked():
            return self.queue_gleebs_dialogue(dialogue_id, flag=flag, duration=duration, mark_seen=mark_seen, requires_near_core=False, once=False)
        self.update_gleebs_dialogue_safe_lane()
        self.gleebs_dialogue_id = str(dialogue_id)
        self.gleebs_dialogue_flag = str(flag or dialogue_id)
        self.gleebs_dialogue_text = text
        # A return line plays wherever the player came back to (planet, gate), not only at the core.
        self.gleebs_dialogue_anywhere = dialogue_id == "gleebs_first_return_001"
        if self.gleebs_dialogue_anywhere:
            self.gleebs_return_line = ""
        self.gleebs_current_quote = ""
        self.gleebs_dialogue_started_at = time.monotonic()
        self.gleebs_dialogue_duration = max(2.5, float(duration or 10.0))
        self.gleebs_dialogue_fade = 0.0
        self.gleebs_dialogue_fade_target = 1.0
        self.gleebs_dialogue_close_on_fade = False
        self.gleebs_dialogue_dismiss_reason = ""
        self.gleebs_dialogue_active = True
        if hasattr(self, "gleebs_dialogue_root"):
            for lbl in (self.gleebs_dialogue_shadow_wide, self.gleebs_dialogue_shadow, self.gleebs_dialogue_label):
                lbl["text"] = text
            try:
                self.gleebs_dialogue_glow["text"] = ""
            except Exception:
                pass
            if hasattr(self, "gleebs_dialogue_quote_label"):
                self.gleebs_dialogue_quote_label["text"] = ""
            self.gleebs_dialogue_hint["text"] = ""
            self.update_gleebs_dialogue_safe_lane()     # size the caption box to this line
            self.gleebs_dialogue_root.show()
        if mark_seen:
            self.mark_matrixcore_dialogue_flag(self.gleebs_dialogue_flag, dialogue_id=dialogue_id)
        if self.audio:
            try:
                self.audio.play('menu_open.wav', 'sfx', 0.25)
            except Exception:
                pass
        return True

    def dismiss_gleebs_dialogue(self, reason: str = "dismiss", *, clear_queue: bool = True):
        if clear_queue:
            try:
                self.gleebs_dialogue_queue = []
            except Exception:
                pass
        if not getattr(self, "gleebs_dialogue_active", False):
            return False
        self.gleebs_dialogue_fade_target = 0.0
        self.gleebs_dialogue_close_on_fade = True
        self.gleebs_dialogue_dismiss_reason = str(reason or "dismiss")
        if hasattr(self, "gleebs_dialogue_hint"):
            self.gleebs_dialogue_hint["text"] = ""
        return True

    def maybe_start_gleebs_intro(self):
        """One short first-arrival hello. No sequence, creator lore, or travel lecture."""
        if SELF_TEST or AUTO_EXIT:
            return
        if self.matrixcore_dialogue_flag_seen("gleebs_welcome_001"):
            return
        self.queue_gleebs_dialogue(
            "gleebs_welcome_001",
            flag="gleebs_welcome_001",
            duration=5.5,
            mark_seen=True,
            requires_near_core=True,
            once=True,
        )
        self.pump_gleebs_dialogue_queue()

    def maybe_queue_matrixcore_open_dialogue(self):
        # MatrixCore consultation itself owns the concise current suggestion.
        return False

    def maybe_queue_gleebs_return_dialogue(self, mode_name: str = "", response: str = ""):
        """One brief home reaction after a primary experiment return.

        Pass 282.67: when the dimension left a gleebs_response in its result, Gleebs says that
        line instead of the generic welcome, wherever the player is standing."""
        if SELF_TEST or AUTO_EXIT:
            return False
        self.gleebs_return_line = " ".join(str(response or "").split())[:240]
        if not self.matrixcore_dialogue_flag_seen("gleebs_welcome_001"):
            return False
        self.gleebs_dialogue_dimension = str(mode_name or "experiment")
        self.gleebs_dialogue_text_override = str(mode_name or "experiment")
        queued = self.queue_gleebs_dialogue(
            "gleebs_first_return_001",
            flag="gleebs_first_return_001",
            duration=7.0 if self.gleebs_return_line else 4.5,
            mark_seen=False,
            requires_near_core=False,
            once=False,
        )
        self.gleebs_dialogue_text_override = ""
        self.pump_gleebs_dialogue_queue()
        return queued

    def update_gleebs_dialogue(self, dt: float = 0.0):
        if not hasattr(self, "gleebs_dialogue_root"):
            return
        if not getattr(self, "gleebs_dialogue_active", False):
            self.pump_gleebs_dialogue_queue()
            return
        self.update_gleebs_dialogue_safe_lane()
        now = time.monotonic()
        dist = math.sqrt(self.player_pos.x ** 2 + self.player_pos.y ** 2)
        if dist > 14.5 and not bool(getattr(self, "gleebs_dialogue_anywhere", False)):
            self.dismiss_gleebs_dialogue("distance", clear_queue=True)
        elif self.gleebs_dialogue_panel_blocked():
            self.dismiss_gleebs_dialogue("panel", clear_queue=False)
        elif now - float(getattr(self, "gleebs_dialogue_started_at", now)) > float(getattr(self, "gleebs_dialogue_duration", 8.0)):
            self.dismiss_gleebs_dialogue("timeout", clear_queue=False)
        target = float(getattr(self, "gleebs_dialogue_fade_target", 0.0))
        current = float(getattr(self, "gleebs_dialogue_fade", 0.0))
        blend = min(1.0, max(0.08, dt * 4.4))
        current = current + (target - current) * blend
        if abs(current - target) < 0.025:
            current = target
        self.gleebs_dialogue_fade = current
        alpha = max(0.0, min(1.0, current))
        pulse = 0.5 + 0.5 * math.sin(float(getattr(self, "elapsed", 0.0)) * 5.4)
        try:
            # Pass 282.63: white text with one soft drop shadow on a glass panel
            # (it was red text with four misaligned shadow copies).
            self.gleebs_dialogue_shadow_wide["text_fg"] = (0.0, 0.0, 0.0, 0.0)
            self.gleebs_dialogue_shadow["text_fg"] = (0.0, 0.0, 0.0, 0.70 * alpha)
            self.gleebs_dialogue_glow["text_fg"] = (0.0, 0.0, 0.0, 0.0)
            self.gleebs_dialogue_label["text_fg"] = (UI_INK[0], UI_INK[1], UI_INK[2], alpha)
            if hasattr(self, "gleebs_dialogue_quote_label"):
                self.gleebs_dialogue_quote_label["text_fg"] = (UI_INK_DIM[0], UI_INK_DIM[1], UI_INK_DIM[2], 0.90 * alpha)
            self.gleebs_dialogue_hint["text_fg"] = (UI_INK_DIM[0], UI_INK_DIM[1], UI_INK_DIM[2], 0.70 * alpha)
            panel = getattr(self, "gleebs_caption_panel", None)
            if panel is not None:
                panel["frameColor"] = (UI_PANEL[0], UI_PANEL[1], UI_PANEL[2], UI_PANEL[3] * alpha)
                self.gleebs_caption_speaker["text_fg"] = (UI_GLEEBS[0], UI_GLEEBS[1], UI_GLEEBS[2], alpha)
        except Exception:
            pass
        if current <= 0.001 and bool(getattr(self, "gleebs_dialogue_close_on_fade", False)):
            reason = str(getattr(self, "gleebs_dialogue_dismiss_reason", "") or "dismiss")
            self.gleebs_dialogue_active = False
            self.gleebs_dialogue_close_on_fade = False
            self.gleebs_dialogue_id = ""
            self.gleebs_current_quote = ""
            try:
                self.gleebs_dialogue_root.hide()
            except Exception:
                pass
            if reason in {"timeout", "panel"}:
                self.gleebs_dialogue_queue_wait_until = time.monotonic() + 0.60
                self.pump_gleebs_dialogue_queue()

    def is_near_core(self):
        return math.sqrt(self.player_pos.x ** 2 + self.player_pos.y ** 2) < 6.8

    def is_looking_at_core(self, cone_cos=0.58):
        if not self.is_near_core():
            return False
        try:
            forward, _right, _up = self.get_view_basis()
            if forward.lengthSquared() <= 0.0001:
                return True
            forward.normalize()
            target = Vec3(0.0, 0.0, 3.2) - self.head_world_pos()
            if target.lengthSquared() <= 0.0001:
                return True
            target.normalize()
            return float(forward.dot(target)) >= float(cone_cos)
        except Exception:
            return True

    def matrixcore_archive_dialogue_entries(self) -> list[dict]:
        data = getattr(self, "matrixcore_data", None)
        if not isinstance(data, dict) or not data:
            data = self.ensure_matrixcore_foundation()
            self.matrixcore_data = data
        lore = data.get("lore") if isinstance(data.get("lore"), dict) else load_matrixcore_lore_study()
        archive = data.get("archive") if isinstance(data.get("archive"), list) else []
        entries = matrixcore_archive_index_from_lore_study(lore)
        if not entries:
            entries = list(archive or [])
        clean: list[dict] = []
        for idx, entry in enumerate(entries):
            if not isinstance(entry, dict):
                continue
            title = compact_ui_text(entry.get("title") or f"Archive {idx:02d}", 54)
            excerpt = compact_ui_text(entry.get("excerpt") or entry.get("summary") or "", 285)
            phase = compact_ui_text(entry.get("phase") or "", 42)
            if not excerpt:
                continue
            clean.append({"id": int(entry.get("id", idx) or idx), "title": title, "excerpt": excerpt, "phase": phase})
        if clean:
            return clean
        core_truth = compact_ui_text(lore.get("core_truth") if isinstance(lore, dict) else "", 285)
        if core_truth:
            return [{"id": 0, "title": "MatrixCore", "excerpt": core_truth, "phase": "core_truth"}]
        return [{"id": 0, "title": "MatrixCore", "excerpt": "MatrixCore is the memory-brain of HoloVerse. It should speak through Gleebs, not trap the traveler in a menu.", "phase": "fallback"}]

    def matrixcore_next_archive_dialogue_text(self, source: str = "matrixcore") -> str:
        entries = self.matrixcore_archive_dialogue_entries()
        progress = self.load_matrixcore_progression()
        matrixcore = progress.setdefault("matrixcore", {})
        idx = int(matrixcore.get("archive_dialogue_index", 0) or 0) % max(1, len(entries))
        entry = entries[idx]
        matrixcore["archive_dialogue_index"] = (idx + 1) % max(1, len(entries))
        matrixcore["last_archive_dialogue_title"] = str(entry.get("title", "MatrixCore"))
        matrixcore["last_archive_dialogue_source"] = str(source or "matrixcore")
        matrixcore["last_archive_dialogue_at"] = datetime.now().isoformat(timespec="seconds")
        self.save_matrixcore_progression(progress)
        phase = str(entry.get("phase", "") or "").replace("_", " ").strip()
        phase_text = f" [{phase}]" if phase else ""
        return f"{entry.get('title', 'MatrixCore')}{phase_text}: {entry.get('excerpt', '')}"

    def trigger_matrixcore_dialogue(self, source: str = "matrixcore") -> bool:
        if getattr(self, "core_console_open", False):
            self.close_core_console()
        self.menu_open = False
        try:
            self.menu_root.hide()
            self.core_console_root.hide()
        except Exception:
            pass
        self.record_matrixcore_consult(str(source or "matrixcore_dialogue"))
        text = self.matrixcore_next_archive_dialogue_text(source)
        previous_override = str(getattr(self, "gleebs_dialogue_text_override", "") or "")
        self.gleebs_dialogue_text_override = text
        try:
            shown = self.show_gleebs_dialogue("gleebs_matrixcore_archive_001", flag="", duration=11.5, mark_seen=False)
        finally:
            self.gleebs_dialogue_text_override = previous_override
        if shown:
            try:
                self.gleebs_current_quote = ""
                self.gleebs_dialogue_quote_label["text"] = ""
                self.gleebs_dialogue_hint["text"] = ""
            except Exception:
                pass
        if self.audio:
            try:
                self.audio.play('menu_open.wav', 'sfx', 0.32)
            except Exception:
                pass
        self.center_hint["text"] = "MATRIXCORE // GLEEBS SIGNAL"
        return bool(shown)

    def open_core_console(self):
        # Pass 05: interacting with MatrixCore is a concise home signal, not a
        # launcher panel or rotating archive dump. Historical lore remains stored.
        self.record_matrixcore_consult("matrixcore_home_signal")
        guidance = self.matrixcore_guidance_state()
        previous_override = str(getattr(self, "gleebs_dialogue_text_override", "") or "")
        self.gleebs_dialogue_text_override = str(
            guidance.get("next_action", "Choose a primary experiment station. Walk to it and press E.")
        )
        try:
            dialogue_data = dict(getattr(self, "gleebs_dialogue_data", {}) or self.ensure_gleebs_dialogue_seed())
            dialogue_lines = dialogue_data.setdefault("lines", {})
            dialogue_lines["matrixcore_home_signal_001"] = "{guidance}"
            self.gleebs_dialogue_data = dialogue_data
            shown = self.show_gleebs_dialogue(
                "matrixcore_home_signal_001", flag="", duration=6.5, mark_seen=False
            )
        finally:
            self.gleebs_dialogue_text_override = previous_override
        if self.audio:
            try:
                self.audio.play('menu_open.wav', 'sfx', 0.28)
            except Exception:
                pass
        self.center_hint["text"] = "MATRIXCORE // HOME SIGNAL"
        return bool(shown)

    def close_core_console(self):
        self.core_console_open = False
        self.core_console_root.hide()
        self.mouse_captured = True
        self.core_console_set_cursor(False)
        if not SELF_TEST:
            self.recenter_mouse(force=True)
        self.hide_native_status_overlay()
        if self.audio:
            self.audio.play('menu_close.wav', 'sfx', 0.7)

    def suspend_for_external_app(self, label: str, embedded: bool = False):
        self.external_launch_label = label
        self.external_suspended = True
        self.external_resume_pending = False
        self.external_resume_marked = False
        self.external_pause_started_at = time.monotonic()
        self.close_core_console()
        self.menu_open = False
        self.mouse_captured = False
        self.keys.clear()
        # TAB is the only HoloVerse-owned input while a dimension is active.
        # Clear any host ESC hold state at the handoff so a pre-entry key press
        # cannot later open/quit HoloVerse over the dimension.
        self.esc_hold_active = False
        self.esc_hold_exit_triggered = False
        self.esc_hold_start = 0.0
        self.esc_hold_deadline = 0.0
        # Pass 282.57b: remember where the player stood so returning puts them back
        # at the gate they used, not the hub start.
        try:
            self.external_return_view = {
                "pos": Vec3(self.player_pos), "yaw": float(self.player_yaw), "pitch": float(self.player_pitch),
                "region": int(self.current_holoverse_region_number()),
            }
        except Exception:
            self.external_return_view = None
        self._suspend_host_player_input_for_dimension()
        self.move_velocity = Vec2(0, 0)
        if hasattr(self, "root_3d") and self.root_3d is not None and not self.root_3d.isEmpty():
            self.root_3d.stash()
        if hasattr(self, "hud_root") and self.hud_root is not None and not self.hud_root.isEmpty():
            self.hud_root.hide()
        if hasattr(self, "crosshair_root") and self.crosshair_root is not None and not self.crosshair_root.isEmpty():
            self.crosshair_root.hide()
        if self.audio:
            self.audio.stop_loop("hub_music")
            self.audio.stop_loop("hub_air")
        if self.win is not None and hasattr(self.win, "requestProperties"):
            props = WindowProperties()
            props.setCursorHidden(False)
            if embedded:
                # Keep the HoloVerse window alive as the parent display surface.
                props.setForeground(True)
                try:
                    props.setMinimized(False)
                except Exception:
                    pass
            else:
                props.setForeground(False)
                props.setUndecorated(False)
                props.setFullscreen(False)
                props.setFixedSize(False)
                try:
                    props.setMinimized(True)
                except Exception:
                    pass
            self.win.requestProperties(props)
        self.external_launch_started_at = time.monotonic()
        self.show_mode_loading_overlay(label, route="LOADING", elapsed=0.0, detail="EMBEDDED" if embedded else "HOSTED")
        print(f"external_pause_begin label={label} embedded={int(bool(embedded))}")

    def _read_external_return_signal(self) -> dict:
        path = getattr(self, "external_return_signal_path", None)
        if not path:
            return {}
        try:
            path = Path(path)
            if not path.exists() or not path.is_file():
                return {}
            payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
            return payload if isinstance(payload, dict) else {}
        except Exception as exc:
            try:
                print(f"external_return_signal_read_failed err={exc}")
            except Exception:
                pass
            return {}

    def _handle_external_return_signal_action(self, payload: dict, returned_label: str = "MODE") -> bool:
        request = str((payload or {}).get("request") or "").strip().lower()
        if not request:
            return False
        if request in {"open_gate_menu", "open_gates", "show_gates", "pyramid_gates"}:
            try:
                self.set_menu_tab("gates")
                if not bool(getattr(self, "menu_open", False)):
                    self.toggle_menu()
                else:
                    self.refresh_menu_actions()
                    self.refresh_ui()
                self.center_hint["text"] = "PYRAMID GATES // SELECT A DIMENSION"
                self.show_bridge_transition("PYRAMID GATES", "MATRIXCORE / DIMENSION ARCHIVE", target=1.0, hold=0.25)
            except Exception:
                pass
            return True
        if request in {"launch_dimension", "launch_gate", "open_dimension"}:
            gate_id = canonical_dimension_lookup_key(
                (payload or {}).get("dimension_id")
                or (payload or {}).get("id")
                or (payload or {}).get("mode")
                or (payload or {}).get("title")
                or ""
            )
            if gate_id:
                try:
                    self.set_menu_tab("gates")
                    self.center_hint["text"] = "PYRAMID GATE // OPENING DIMENSION"
                    return bool(self.matrixcore_launch_dimension_gate(gate_id))
                except Exception as exc:
                    try:
                        print(f"external_return_launch_gate_failed gate={gate_id} err={exc.__class__.__name__}:{exc}")
                    except Exception:
                        pass
            try:
                self.set_menu_tab("gates")
                if not bool(getattr(self, "menu_open", False)):
                    self.toggle_menu()
                self.center_hint["text"] = "PYRAMID GATE // ROUTE NEEDS CONFIG"
            except Exception:
                pass
            return False
        return False

    def _write_external_return_signal(self, reason: str = "user") -> None:
        path = getattr(self, "external_return_signal_path", None)
        if not path:
            return
        try:
            path = Path(path)
            path.parent.mkdir(parents=True, exist_ok=True)
            payload = {
                "request": "return_to_core",
                "reason": str(reason or "user"),
                "mode": str(getattr(self, "external_launch_label", "MODE") or "MODE"),
                "timestamp": time.time(),
                "parent_pid": os.getpid(),
            }
            path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
        except Exception as exc:
            print(f"external_return_signal_write_failed err={exc}")

    def _force_external_return_after_delay(self, proc: subprocess.Popen, label: str, delay: float = 3.0) -> None:
        try:
            time.sleep(max(0.4, float(delay)))
            if proc is not getattr(self, "external_process", None):
                return
            if proc.poll() is None:
                print(f"external_return_force_terminate label={label}")
                try:
                    proc.terminate()
                except Exception:
                    try:
                        proc.kill()
                    except Exception:
                        pass
        except Exception:
            pass

    def _terminate_external_process_handle(self, proc: subprocess.Popen | None, label: str, reason: str = "window-closed", kill_after: float = 1.2) -> None:
        if proc is None:
            return
        try:
            if proc.poll() is None:
                print(f"external_process_terminate label={label} reason={reason}")
                try:
                    proc.terminate()
                except Exception:
                    try:
                        proc.kill()
                    except Exception:
                        return
                def _kill_later():
                    try:
                        time.sleep(max(0.25, float(kill_after)))
                        if proc.poll() is None:
                            print(f"external_process_kill label={label} reason={reason}")
                            proc.kill()
                    except Exception:
                        pass
                threading.Thread(target=_kill_later, daemon=True).start()
        except Exception:
            pass

    def _mark_external_resume_pending(self, proc: subprocess.Popen | None = None, label: str | None = None, reason: str = "process-exited", route: str | None = None) -> bool:
        active_proc = getattr(self, "external_process", None)
        if proc is not None and active_proc is not None and proc is not active_proc:
            return False
        label = str(label or getattr(self, "external_launch_label", "MODE") or "MODE")
        rc = None
        try:
            rc = proc.poll() if proc is not None else (active_proc.poll() if active_proc is not None else None)
        except Exception:
            rc = None
        self.external_return_code = rc
        self.external_resume_pending = True
        if not bool(getattr(self, "external_resume_marked", False)):
            self.external_resume_marked = True
            try:
                self._append_mode_gateway_history("external_return", label=label, route=route or MODE_LAUNCH_EXTERNAL, extra={"return_code": rc, "reason": reason})
            except Exception:
                pass
        return True

    def _external_process_poll_update(self, reason: str = "poll") -> bool:
        proc = getattr(self, "external_process", None)
        if proc is None:
            if bool(getattr(self, "external_suspended", False)):
                self.external_resume_pending = True
                return True
            return False
        try:
            if proc.poll() is not None:
                return self._mark_external_resume_pending(proc=proc, reason=reason)
        except Exception:
            return self._mark_external_resume_pending(proc=proc, reason=f"{reason}-poll-error")
        return False

    def _embedded_child_window_closed_update(self) -> bool:
        embedder = getattr(self, "embedded_child_host", None)
        if embedder is None:
            return False
        if not bool(getattr(embedder, "ever_attached", False)):
            return False
        if not bool(getattr(embedder, "child_window_closed", False)):
            return False
        closed_at = float(getattr(embedder, "child_window_closed_at", 0.0) or 0.0)
        if closed_at and (time.monotonic() - closed_at) < 0.20:
            return False
        proc = getattr(self, "external_process", None)
        label = str(getattr(self, "external_launch_label", "MODE") or "MODE")
        reason = str(getattr(embedder, "child_window_closed_reason", "child-window-closed") or "child-window-closed")
        self._write_external_return_signal(reason=reason)
        self._terminate_external_process_handle(proc, label, reason=reason, kill_after=1.0)
        return self._mark_external_resume_pending(proc=proc, label=label, reason=reason, route=MODE_LAUNCH_EMBEDDED)

    def _release_stuck_embedded_wait_lock(self, reason: str = "embedded-attach-timeout") -> bool:
        """Recover from a child-window embed attempt that never attaches.

        The old behavior could leave HoloVerse suspended forever while the
        loading overlay waited for a child window. Keep the child process alive
        as a hosted external fallback, release the hub, and let ESC / Close All
        Apps terminate it if the child itself is broken.
        """
        if not bool(getattr(self, "external_suspended", False)):
            return False
        proc = getattr(self, "external_process", None)
        if proc is None:
            self.external_resume_pending = True
            return True
        try:
            if proc.poll() is not None:
                return self._mark_external_resume_pending(proc=proc, reason=f"{reason}-process-exited", route=MODE_LAUNCH_EMBEDDED)
        except Exception:
            return self._mark_external_resume_pending(proc=proc, reason=f"{reason}-poll-error", route=MODE_LAUNCH_EMBEDDED)
        label = str(getattr(self, "external_launch_label", "MODE") or "MODE")
        embedder = getattr(self, "embedded_child_host", None)
        attach_error = str(getattr(embedder, "attach_error", "") or "")
        try:
            if embedder is not None:
                embedder.stop()
        except Exception:
            pass
        self.embedded_child_host = None
        self.embedded_child_attached = False
        self.external_suspended = False
        self.external_resume_pending = False
        self.mouse_captured = True
        try:
            if hasattr(self, "root_3d") and self.root_3d is not None and not self.root_3d.isEmpty():
                self.root_3d.unstash()
            if getattr(self.cfg, "hud_visible", True):
                if hasattr(self, "hud_root") and self.hud_root is not None and not self.hud_root.isEmpty():
                    self.hud_root.show()
                if hasattr(self, "crosshair_root") and self.crosshair_root is not None and not self.crosshair_root.isEmpty():
                    self.crosshair_root.show()
        except Exception:
            pass
        try:
            if self.win is not None and hasattr(self.win, "requestProperties"):
                props = WindowProperties()
                props.setCursorHidden(True)
                props.setForeground(True)
                self.win.requestProperties(props)
        except Exception:
            pass
        self.hide_native_status_overlay()
        self.center_hint["text"] = f"CORE // {label.upper()} HOSTED FALLBACK // ESC RETURNS"
        try:
            self._append_mode_gateway_history("embedded_attach_timeout_released", label=label, route=MODE_LAUNCH_EXTERNAL, extra={"reason": reason, "attach_error": attach_error, "pid": int(getattr(proc, "pid", 0) or 0)})
        except Exception:
            pass
        threading.Thread(target=self._focus_external_window_later, args=(proc, label), daemon=True).start()
        return True

    def _embedded_launch_timeout_update(self) -> bool:
        if not bool(getattr(self, "external_suspended", False)):
            return False
        embedder = getattr(self, "embedded_child_host", None)
        if embedder is None or bool(getattr(embedder, "attached", False)):
            return False
        elapsed = time.monotonic() - float(getattr(self, "external_launch_started_at", time.monotonic()) or time.monotonic())
        timeout = max(float(getattr(WindowsChildWindowEmbedder, "ATTACH_TIMEOUT_SECONDS", 8.0)) + 1.0, 9.0)
        if bool(getattr(embedder, "attach_timed_out", False)) or elapsed >= timeout:
            return self._release_stuck_embedded_wait_lock(reason="embedded-child-window-not-found")
        return False

    def request_external_return_to_core(self, reason: str = "user") -> None:
        """Ask the active hosted child mode to close and return to Core."""
        proc = getattr(self, "external_process", None)
        if proc is None:
            return
        try:
            if proc.poll() is None:
                self.center_hint["text"] = "CORE // RETURNING FROM MODE"
                self.external_return_requested_at = time.monotonic()
                self._append_mode_gateway_history("embedded_return_requested", label=getattr(self, "external_launch_label", "MODE"), route=MODE_LAUNCH_EMBEDDED, extra={"reason": reason, "graceful": True})
                self._write_external_return_signal(reason=reason)
                embedder = getattr(self, "embedded_child_host", None)
                if embedder is not None:
                    try:
                        embedder.request_graceful_close()
                    except Exception:
                        pass
                threading.Thread(target=self._force_external_return_after_delay, args=(proc, getattr(self, "external_launch_label", "MODE"), 3.2), daemon=True).start()
            else:
                self.external_resume_pending = True
        except Exception:
            self.external_resume_pending = True

    def resume_from_external_app(self):
        return_signal_payload = self._read_external_return_signal() if hasattr(self, "_read_external_return_signal") else {}
        if getattr(self, "embedded_child_host", None) is not None:
            try:
                self.embedded_child_host.stop()
            except Exception:
                pass
        self.embedded_child_host = None
        self.embedded_child_attached = False
        try:
            if getattr(self, "external_return_signal_path", None):
                Path(self.external_return_signal_path).unlink(missing_ok=True)
        except Exception:
            pass
        self.external_return_signal_path = None
        self.external_return_requested_at = 0.0
        self.external_suspended = False
        self.external_resume_pending = False
        self.external_resume_marked = False
        self.external_process = None
        self.hide_native_status_overlay()
        try:
            self._stop_native_mode_audio()
        except Exception:
            pass
        self.mouse_captured = True
        if hasattr(self, "root_3d") and self.root_3d is not None and not self.root_3d.isEmpty():
            self.root_3d.unstash()
        if getattr(self.cfg, "hud_visible", True):
            if hasattr(self, "hud_root") and self.hud_root is not None and not self.hud_root.isEmpty():
                self.hud_root.show()
            if hasattr(self, "crosshair_root") and self.crosshair_root is not None and not self.crosshair_root.isEmpty():
                self.crosshair_root.show()
        if self.win is not None and hasattr(self.win, "requestProperties"):
            props = WindowProperties()
            props.setCursorHidden(True)
            props.setForeground(True)
            try:
                props.setMinimized(False)
            except Exception:
                pass
            if LAUNCH_BORDERLESS:
                props.setUndecorated(True)
                props.setOrigin(LAUNCH_X, LAUNCH_Y)
                props.setSize(LAUNCH_W, LAUNCH_H)
                props.setFullscreen(False)
                props.setFixedSize(True)
            elif LAUNCH_BORDERED_FULLSCREEN:
                props.setUndecorated(False)
                props.setOrigin(LAUNCH_X, LAUNCH_Y)
                props.setSize(LAUNCH_W, LAUNCH_H)
                props.setFullscreen(False)
                props.setFixedSize(False)
            else:
                props.setUndecorated(False)
                props.setFullscreen(bool(LAUNCH_FULLSCREEN))
            self.win.requestProperties(props)
        try:
            self._restore_hub_ground_control_state(reason="external_return")
            self.reload_default_holoverse_shell(reason="external_return")
            self.sync_active_world_runtime_state()
        except Exception:
            pass
        # Pass 282.57b fix: the pause unregisters HoloVerse's controls
        # (_suspend_host_player_input_for_dimension) but this resume never put them
        # back, so only TAB worked after a dimension that runs in its own window
        # (Afterlife of IO).  Same-window dimensions already restore here.
        try:
            self._restore_host_player_input_after_dimension()
        except Exception as exc:
            print(f"external_input_restore_failed err={exc.__class__.__name__}:{exc}")
        self._restore_external_return_view()
        self.recenter_mouse(force=True)
        # Windows may refuse the first foreground request after another process
        # owned the screen ("SetForegroundWindow() failed"); ask again shortly.
        try:
            for delay in (0.4, 1.2):
                self.taskMgr.doMethodLater(delay, self._refocus_after_external_task, f"external-refocus-{delay}")
        except Exception:
            pass
        self.center_hint["text"] = "CORE // RETURNED"
        returned_label = str(getattr(self, "external_launch_label", "MODE") or "MODE")
        self.record_matrixcore_dimension_signal("dimension_return", returned_label, label=returned_label, route=MODE_LAUNCH_EMBEDDED, source="embedded_external", reason="external_resume")
        # 282.50: a dimension in its own window (Afterlife of IO) may leave a result in the return
        # signal file, the same packet native dimensions give through get_holoverse_result().
        external_result = return_signal_payload.get("result") if isinstance(return_signal_payload, dict) else None
        if isinstance(external_result, dict) and external_result:
            try:
                self.record_native_dimension_result(returned_label, "gleebs_archive_external", external_result)
                print(f"external_dimension_result label={returned_label} signal={external_result.get('signal', '')}")
            except Exception as exc:
                print(f"external_dimension_result_failed label={returned_label} err={exc.__class__.__name__}:{exc}")
        handled_return_signal = False
        try:
            handled_return_signal = bool(self._handle_external_return_signal_action(return_signal_payload, returned_label))
        except Exception as exc:
            try:
                print(f"external_return_signal_action_failed err={exc.__class__.__name__}:{exc}")
            except Exception:
                pass
        if not handled_return_signal:
            response = str(external_result.get("gleebs_response") or "") if isinstance(external_result, dict) else ""
            self.maybe_queue_gleebs_return_dialogue(returned_label, response)
        pause_seconds = max(0.0, time.monotonic() - float(getattr(self, "external_pause_started_at", time.monotonic())))
        print(f"external_resume_ok label={self.external_launch_label} rc={self.external_return_code} paused_seconds={pause_seconds:.2f}")

    def _refocus_after_external_task(self, task):
        if bool(getattr(self, "external_suspended", False)) or self.win is None:
            return Task.done
        try:
            props = WindowProperties()
            props.setForeground(True)
            props.setCursorHidden(bool(getattr(self, "mouse_captured", True)))
            self.win.requestProperties(props)
            if bool(getattr(self, "mouse_captured", True)):
                self.recenter_mouse(force=True)
        except Exception:
            pass
        return Task.done

    def _restore_external_return_view(self) -> bool:
        """Put the player back where they stood before an own-window dimension,
        when they are still in the same region (e.g. at IO's gate)."""
        view = getattr(self, "external_return_view", None)
        self.external_return_view = None
        if not isinstance(view, dict):
            return False
        try:
            if int(self.current_holoverse_region_number()) != int(view.get("region", -1)):
                return False
            pos = Vec3(view["pos"])
            self.player_pos = pos
            self.player_yaw = float(view.get("yaw", self.player_yaw))
            self.player_pitch = float(view.get("pitch", self.player_pitch))
            self.camera.setPos(pos)
            self.camera.setHpr(self.player_yaw, self.player_pitch, 0)
            mount = getattr(self, "world_shell_mount", None)
            if mount is not None and callable(getattr(mount, "sync_from_app", None)):
                mount.sync_from_app()
            return True
        except Exception as exc:
            print(f"external_return_view_failed err={exc.__class__.__name__}:{exc}")
            return False

    def _watch_external_process(self, proc: subprocess.Popen, label: str):
        rc = None
        try:
            rc = proc.wait()
        except Exception as exc:
            print(f"external_wait_error label={label} err={exc}")
        finally:
            # Ignore stale watcher completions from an older child process.
            # Without this guard, an old thread can rename the active launch or
            # flip the parent back into a wait/return state after a new mode has
            # already started.
            if proc is not getattr(self, "external_process", None):
                return
            self.external_return_code = rc
            self.external_launch_label = label
            self._mark_external_resume_pending(proc=proc, label=label, reason="process-wait-complete", route=MODE_LAUNCH_EXTERNAL)

    def _focus_external_window_later(self, proc: subprocess.Popen, label: str) -> None:
        """Focus the actual game window after hosted launch.

        This is a Windows-only best-effort repair for the case where the parent
        command prompt remains the active window instead of the launched
        Dimension.
        """
        if os.name != "nt":
            return
        deadline = time.monotonic() + 6.0
        while time.monotonic() < deadline:
            try:
                if proc is not getattr(self, "external_process", None) or proc.poll() is not None:
                    return
                if _focus_visible_window_for_pid(int(getattr(proc, "pid", 0) or 0), label=label):
                    self._append_mode_gateway_history("external_focus", label=label, route=MODE_LAUNCH_EXTERNAL, extra={"pid": int(getattr(proc, "pid", 0) or 0), "result": "focused"})
                    return
            except Exception:
                pass
            time.sleep(0.12)
        try:
            self._append_mode_gateway_history("external_focus", label=label, route=MODE_LAUNCH_EXTERNAL, extra={"pid": int(getattr(proc, "pid", 0) or 0), "result": "window-not-found"})
        except Exception:
            pass

    def show_native_status_overlay(self, label: str, route: str = "MODE", subtitle: str | None = None) -> None:
        """Legacy compatibility hook.

        Pass 277 intentionally removes the host-owned experimental dimension
        status strip. Linked/native realities render only their real game HUD.
        TAB remains the instant return law and ESC opens the normal HoloVerse
        menu, which exposes RETURN TO HOLOVERSE while a dimension is active.
        """
        return None

    def show_mode_loading_overlay(self, label: str, route: str = "LOADING", elapsed: float = 0.0, detail: str = "") -> None:
        seconds = max(0.0, float(elapsed or 0.0))
        suffix = f" // {str(detail).upper()}" if str(detail or "").strip() else ""
        subtitle = f"OPENING {seconds:04.1f}s{suffix}"
        self.center_hint["text"] = f"OPENING {str(label or 'EXPERIMENT').upper()}"
        self.show_native_status_overlay(label, route=route, subtitle=subtitle)

    def hide_native_status_overlay(self) -> None:
        # Kept as a no-op compatibility hook for older lifecycle call sites.
        return None

    def _set_bridge_transition_alpha(self, alpha: float) -> None:
        root = getattr(self, "bridge_transition_root", None)
        if root is None:
            return
        alpha = max(0.0, min(1.0, float(alpha or 0.0)))
        self.bridge_transition_alpha = alpha
        if alpha <= 0.002 and float(getattr(self, "bridge_transition_target", 0.0) or 0.0) <= 0.0:
            try:
                root.hide()
            except Exception:
                pass
            return
        try:
            root.show()
        except Exception:
            pass
        try:
            panel = getattr(self, "bridge_transition_panel", None)
            if panel is not None:
                panel["frameColor"] = (0.0, 0.006, 0.012, 0.86 * alpha)
            label = getattr(self, "bridge_transition_label", None)
            if label is not None:
                label["text_fg"] = (0.74, 1.0, 1.0, 0.95 * alpha)
            subtitle = getattr(self, "bridge_transition_subtitle", None)
            if subtitle is not None:
                subtitle["text_fg"] = (0.46, 0.94, 1.0, 0.82 * alpha)
        except Exception:
            pass

    def present_dimension_loading(self, title: str) -> None:
        """Pass 282.78: show the entry card *before* a same-window dimension loads.

        Loading a dimension blocks the frame for a few seconds, so the transition card was set but
        never drawn and the screen simply froze.  Draw it now (two frames, so both buffers hold it)."""
        try:
            self.show_bridge_transition(f"ENTERING {str(title or 'DIMENSION').upper()}", "LOADING  //  ONE MOMENT", target=1.0, hold=0.2)
            self._set_bridge_transition_alpha(0.95)
            for _ in range(2):
                self.graphicsEngine.renderFrame()
        except Exception as exc:
            print(f"dimension_loading_card_failed err={exc.__class__.__name__}:{exc}")

    def show_bridge_transition(self, title: str, subtitle: str = "", *, target: float = 1.0, hold: float = 0.0) -> None:
        if getattr(self, "bridge_transition_root", None) is None:
            return
        try:
            if getattr(self, "bridge_transition_label", None) is not None:
                self.bridge_transition_label["text"] = str(title or "TRANSITION")
            if getattr(self, "bridge_transition_subtitle", None) is not None:
                self.bridge_transition_subtitle["text"] = str(subtitle or "SAME-SCREEN GATEWAY")
            self.bridge_transition_target = max(0.0, min(1.0, float(target)))
            self.bridge_transition_hold_until = max(float(getattr(self, "bridge_transition_hold_until", 0.0) or 0.0), time.monotonic() + max(0.0, float(hold or 0.0)))
            if float(getattr(self, "bridge_transition_alpha", 0.0) or 0.0) <= 0.002:
                self._set_bridge_transition_alpha(0.025)
            else:
                self._set_bridge_transition_alpha(float(getattr(self, "bridge_transition_alpha", 0.0) or 0.0))
        except Exception:
            pass

    def fade_bridge_transition(self, *, hold: float = 0.0) -> None:
        if getattr(self, "bridge_transition_root", None) is None:
            return
        if getattr(self, "active_native_mode", None) is not None:
            # Pass 282.62: a native dimension now owns the frame and the host
            # update (which animates this banner) is frozen, so the "ENTERING ..."
            # banner used to stay on screen inside the dimension.  Drop it now and
            # fade the new reality in from black instead.
            self.bridge_transition_target = 0.0
            self.bridge_transition_hold_until = 0.0
            self._set_bridge_transition_alpha(0.0)
            self.begin_screen_fade_in(0.85)
            return
        self.bridge_transition_target = 0.0
        self.bridge_transition_hold_until = max(float(getattr(self, "bridge_transition_hold_until", 0.0) or 0.0), time.monotonic() + max(0.0, float(hold or 0.0)))

    def update_bridge_transition(self, dt: float) -> None:
        if getattr(self, "bridge_transition_root", None) is None:
            return
        alpha = float(getattr(self, "bridge_transition_alpha", 0.0) or 0.0)
        target = float(getattr(self, "bridge_transition_target", 0.0) or 0.0)
        if target <= 0.0 and time.monotonic() < float(getattr(self, "bridge_transition_hold_until", 0.0) or 0.0):
            target = max(1.0, alpha)
        speed = 5.2
        blend = min(1.0, max(0.0, float(dt or 0.0)) * speed)
        if abs(target - alpha) <= 0.004:
            alpha = target
        else:
            alpha = alpha + (target - alpha) * blend
        self._set_bridge_transition_alpha(alpha)

    def return_active_mode_from_button(self):
        if getattr(self, "active_native_mode", None) is not None:
            self.return_from_native_mode(reason="button")
            return
        if getattr(self, "external_process", None) is not None:
            self.request_external_return_to_core(reason="button")
            return
        self.hide_native_status_overlay()
        if getattr(self, "center_hint", None) is not None:
            self.center_hint["text"] = "CORE // NO ACTIVE GAME"

    def quit_holoverse_from_menu(self):
        """Single-click app exit from the modernized system menu.

        Hold-ESC remains the safe universal quit path in MatrixCore. Native
        dimensions own ESC and all other local controls; TAB alone returns.
        """
        if getattr(self, "active_native_mode", None) is not None:
            return
        try:
            self.close_all_mode_apps()
        except Exception:
            pass
        try:
            if getattr(self, "center_hint", None) is not None:
                self.center_hint["text"] = "EXITING HOLOVERSE"
            if getattr(self, "audio", None):
                self.audio.play('menu_close.wav', 'sfx', 0.72)
        except Exception:
            pass
        self.userExit()

    def dispatch_native_action(self, action: str) -> bool:
        """Legacy adapter-action bridge; player input no longer uses it.

        Pass 282.9 establishes strict input ownership: once a native dimension is
        mounted, HoloVerse carries only TAB as its universal return key.  All
        other keyboard/mouse events stay on Panda's normal messenger and are
        handled directly by the dimension's own bindings.  Keeping this method
        as a no-op protects older internal callers without reintroducing host
        button interception.
        """
        return False

    def _mode_adapter_path(self, mode: dict) -> Path | None:
        manifest = dict(mode.get("manifest") or {})
        folder = Path(mode.get("folder", ROOT))
        adapter_name = str(manifest.get("native_adapter") or MODE_NATIVE_ADAPTER_NAME).strip() or MODE_NATIVE_ADAPTER_NAME
        adapter = folder / adapter_name
        return adapter if adapter.exists() and adapter.is_file() else None

    def _add_native_import_root(self, folder: Path) -> None:
        root = os.fspath(Path(folder).resolve())
        if root in sys.path:
            return
        sys.path.append(root)
        self._native_import_root = root

    def _remove_native_import_root(self) -> None:
        root = getattr(self, "_native_import_root", None)
        self._native_import_root = None
        if root:
            try:
                sys.path.remove(root)
            except ValueError:
                pass

    def _load_native_mode_object(self, mode: dict, entry: Path | None, label: str):
        adapter_path = self._mode_adapter_path(mode)
        if adapter_path is None:
            raise FileNotFoundError(f"native adapter missing for {label}")
        module_name = f"holoverse_native_{re.sub(r'[^a-zA-Z0-9_]+', '_', str(mode.get('name', 'mode')))}_{int(time.time() * 1000)}"
        spec = importlib.util.spec_from_file_location(module_name, adapter_path)
        if spec is None or spec.loader is None:
            raise ImportError(f"could not load adapter spec: {adapter_path}")
        module = importlib.util.module_from_spec(spec)
        sys.modules[module_name] = module
        # Adapters import their own packages (The Archivist: ``from archive3d.mode import ...``),
        # so the project folder must be importable while the dimension is mounted.  Appended,
        # never prepended, so a dimension module can never shadow one of HoloVerse's own.
        self._add_native_import_root(Path(adapter_path).parent)
        try:
            spec.loader.exec_module(module)
        except Exception:
            sys.modules.pop(module_name, None)
            raise
        self.native_adapter_module_name = module_name
        if hasattr(module, "create_mode"):
            return module.create_mode(self, mode=mode, entry_path=entry, label=label)
        cls = getattr(module, "HoloVerseNativeMode", None)
        if cls is None:
            raise AttributeError(f"adapter lacks create_mode or HoloVerseNativeMode: {adapter_path}")
        return cls(self, mode=mode, entry_path=entry, label=label)

    def _native_node_key(self, node_path):
        try:
            node = node_path.node()
            raw = getattr(node, "this", None)
            if raw is not None:
                try:
                    return ("ptr", int(raw))
                except Exception:
                    return ("ptr", str(raw))
            return ("node", id(node), str(node))
        except Exception:
            try:
                return ("np", id(node_path), str(node_path))
            except Exception:
                return ("unknown", id(node_path))

    def _snapshot_native_scene_state(self) -> dict:
        snapshot = {}
        roots = (
            ("render", getattr(self, "render", None)),
            ("aspect2d", getattr(self, "aspect2d", None)),
            ("render2d", getattr(self, "render2d", None)),
            ("camera", getattr(self, "camera", None)),
        )
        for root_name, root in roots:
            keys = set()
            try:
                if root is None or root.isEmpty():
                    snapshot[root_name] = keys
                    continue
                for child in root.getChildren():
                    keys.add(self._native_node_key(child))
            except Exception:
                pass
            snapshot[root_name] = keys
        return snapshot

    def _purge_native_scene_residue(self, label: str = "") -> int:
        snapshot = getattr(self, "native_scene_baseline", None)
        if not isinstance(snapshot, dict):
            return 0
        removed = 0
        native_name_tokens = (
            "native", "code_red_vector", "code red vector", "etch", "fractured",
            "holo_campaign", "holo campaign", "holo_conquest", "holo conquest",
            "vector_wars", "vector wars", "holocore", "holo_vessel",
        )
        roots = (
            ("render", getattr(self, "render", None)),
            ("aspect2d", getattr(self, "aspect2d", None)),
            ("render2d", getattr(self, "render2d", None)),
            ("camera", getattr(self, "camera", None)),
        )
        for root_name, root in roots:
            try:
                if root is None or root.isEmpty():
                    continue
                baseline = snapshot.get(root_name, set())
                for child in list(root.getChildren()):
                    key = self._native_node_key(child)
                    if key in baseline:
                        continue
                    name = ""
                    try:
                        name = str(child.getName() or "").lower()
                    except Exception:
                        pass
                    should_remove = True
                    # Keep the guard conservative for unexpected Core nodes, but
                    # always remove obvious native residue and camera-mounted props.
                    if root_name not in {"camera", "aspect2d", "render2d"}:
                        should_remove = any(token in name for token in native_name_tokens)
                    if should_remove:
                        try:
                            child.removeNode()
                            removed += 1
                        except Exception:
                            pass
            except Exception:
                pass
        if removed:
            try:
                print(f"native_mode_residue_cleaned label={label or getattr(self, 'native_mode_label', '')} count={removed}")
            except Exception:
                pass
        return removed

    def _native_dimension_audio_profile(self, label: str) -> dict:
        """Map HoloVerse's own region activities to their region soundtrack (assets/audio/region_music.json).

        Pass 282.79: any other dimension (HoloCore, the Indigo Giant, Vector Wars, ...) plays its own
        soundtrack, so HoloVerse adds no music to it (empty cue)."""
        key = re.sub(r"[^a-z0-9]+", "_", str(label or "dimension").lower()).strip("_")
        table = {
            "forest_growth": {"cue": "forest", "volume": 0.54},
            "hills_of_life": {"cue": "hills", "volume": 0.54},
            "oddities": {"cue": "hills", "volume": 0.52},           # Solace keeps Oddities in GREEN HILLS
            "ember_hangar": {"cue": "desert", "volume": 0.56},
            "frost_circuit": {"cue": "ice", "volume": 0.54},
            "urban_warzone": {"cue": "urban", "volume": 0.62},
            "metropolis_robot_lab": {"cue": "metropolis", "volume": 0.58},
            "holospace_region": {"cue": "space", "volume": 0.58},
            "holoforge": {"cue": "holoforge", "volume": 0.54},
        }
        if key in table:
            return dict(table[key])
        for token, profile in table.items():
            if token and token in key:
                return dict(profile)
        return {"cue": "", "volume": 0.0}

    def _start_native_mode_audio(self, label: str):
        audio = getattr(self, "audio", None)
        if audio is None:
            return
        try:
            if hasattr(audio, "stop_all"):
                audio.stop_all(stop_oneshots=True)
            else:
                audio.stop_loop("hub_music")
                audio.stop_loop("hub_air")
                audio.stop_loop("holocore_dimension_music")
                audio.stop_loop("holocore_dimension_air")
                audio.stop_loop("native_dimension_music")
                audio.stop_loop("native_dimension_air")
            profile = self._native_dimension_audio_profile(label)
            cue = str(profile.get("cue") or "")
            volume = max(0.0, min(1.0, float(profile.get("volume", 0.55))))
            audio.play("artifact_link.wav", bus="sfx", volume=0.68)
            region = resolve_region_music_track(cue) if cue else None
            if region is not None:
                audio.play_loop("native_dimension_music", cue, bus="music", volume=volume)
            else:
                audio.stop_loop("native_dimension_music")
            audio.stop_loop("native_dimension_air")
            if region is None:
                source = "dimension_own_soundtrack"
            else:
                source = region[1].name if region[1] is not None else "no_track_silent"
            self.native_mode_audio_profile = {"label": str(label or "MODE"), "cue": cue, "source": source}
        except Exception as exc:
            try:
                print(f"native_mode_audio_start_error label={label} err={exc.__class__.__name__}:{exc}")
            except Exception:
                pass

    def _stop_native_mode_audio(self):
        audio = getattr(self, "audio", None)
        if audio is None:
            return
        try:
            if hasattr(audio, "stop_all"):
                audio.stop_all(stop_oneshots=True)
            else:
                audio.stop_loop("native_dimension_music")
                audio.stop_loop("native_dimension_air")
        except Exception:
            pass
        self.native_mode_audio_profile = {}

    def _restore_hub_ground_control_state(self, reason: str = "return", preserve_view: bool = False) -> None:
        """Restore safe ground controls after a mode exits.

        ``preserve_view`` is used by same-window native dimensions: their host
        lifecycle already snapshots the exact HoloVerse camera/lens/player view,
        so this helper must clear transient movement/flight state without
        overwriting that snapshot with generic hub defaults.
        """
        try:
            self.shell_flight_craft_active = False
            self.shell_flight_craft_velocity = Vec3(0, 0, 0)
            self.shell_flight_craft_boost = 1.0
            node = getattr(self, "shell_flight_craft_visual_root", None)
            if node is not None and not node.isEmpty():
                node.removeNode()
            self.shell_flight_craft_visual_root = None
            self.shell_flight_craft_visual_signature = ""
        except Exception:
            pass
        try:
            self.holospace_active = False
            self.holospace_transition_active = False
            self.holospace_velocity = Vec3(0, 0, 0)
            self.holospace_speed_boost = 1.0
            self.show_holospace_cockpit(False)
            self.apply_holospace_world_isolation(False)
        except Exception:
            pass
        try:
            self.move_velocity = Vec2(0, 0)
            self.vertical_velocity = 0.0
            self.on_ground = True
            self.keys.clear()
        except Exception:
            pass
        if not bool(preserve_view):
            try:
                self.player_pos = Vec3(self.base_teleport)
                self.player_yaw = 0.0
                self.player_pitch = -6.0
                self.camera.setPos(self.player_pos)
                self.camera.setHpr(self.player_yaw, self.player_pitch, 0)
                if getattr(self, "camLens", None) is not None:
                    self.camLens.setFov(75)
                    self.camLens.setNearFar(0.08, 5000.0)
            except Exception:
                pass

    def _native_display_regions_for_camera(self, camera_np):
        """Return display regions currently rendering from *camera_np*.

        Native dimensions must never borrow/move HoloVerse's real camera.  We
        therefore swap only the display regions that normally use ``self.cam``
        to a temporary dimension camera and leave 2-D/interface regions alone.
        """
        regions = []
        if self.win is None or camera_np is None:
            return regions
        try:
            count = int(self.win.getNumDisplayRegions())
        except Exception:
            return regions
        for index in range(count):
            try:
                region = self.win.getDisplayRegion(index)
                bound = region.getCamera()
                if bound is not None and not bound.isEmpty() and bound == camera_np:
                    regions.append(region)
            except Exception:
                continue
        return regions

    def _begin_native_camera_isolation(self):
        """Give the active dimension a disposable camera without moving HoloVerse.

        Existing full-source adapters intentionally consume ``host.camera``,
        ``host.cam`` and ``host.camLens``.  During a native dimension those
        aliases are rebound to a new camera/lens pair.  The original ShowBase
        camera remains alive, unchanged, and disconnected from the 3-D display
        region until the dimension exits.
        """
        if getattr(self, "_native_camera_binding", None):
            return True
        original_camera = getattr(self, "camera", None)
        original_cam = getattr(self, "cam", None)
        original_cam_node = getattr(self, "camNode", None)
        original_lens = getattr(self, "camLens", None)
        if original_camera is None or original_cam is None or original_lens is None:
            return False
        try:
            lens = original_lens.makeCopy()
        except Exception:
            return False
        try:
            dimension_camera_root = self.render.attachNewNode("native-dimension-camera-root")
            dimension_camera_node = Camera("native-dimension-camera")
            dimension_camera_node.setLens(lens)
            dimension_cam = dimension_camera_root.attachNewNode(dimension_camera_node)
            try:
                dimension_camera_root.setPos(original_camera.getPos(self.render))
                dimension_camera_root.setHpr(original_camera.getHpr(self.render))
            except Exception:
                pass
            regions = self._native_display_regions_for_camera(original_cam)
            bindings = []
            for region in regions:
                try:
                    bindings.append((region, region.getCamera()))
                    region.setCamera(dimension_cam)
                except Exception:
                    continue
            self._native_camera_binding = {
                "camera": original_camera,
                "cam": original_cam,
                "camNode": original_cam_node,
                "camLens": original_lens,
                "dimension_camera_root": dimension_camera_root,
                "dimension_cam": dimension_cam,
                "dimension_camNode": dimension_camera_node,
                "dimension_camLens": lens,
                "display_regions": bindings,
                "host_camera_pos": Vec3(original_camera.getPos(self.render)),
                "host_camera_hpr": Vec3(original_camera.getHpr(self.render)),
            }
            # Rebind ShowBase's conventional camera aliases.  Any linked game
            # using ``base.camera`` sees only the disposable dimension camera.
            self.camera = dimension_camera_root
            self.cam = dimension_cam
            self.camNode = dimension_camera_node
            self.camLens = lens
            print(f"native_camera_isolation_begin regions={len(bindings)}")
            return True
        except Exception as exc:
            try:
                if 'dimension_camera_root' in locals() and dimension_camera_root is not None and not dimension_camera_root.isEmpty():
                    dimension_camera_root.removeNode()
            except Exception:
                pass
            print(f"native_camera_isolation_failed err={exc.__class__.__name__}:{exc}")
            return False

    def _enforce_native_host_freeze(self):
        """Keep HoloVerse player/camera state immutable while a dimension runs."""
        saved = getattr(self, "native_saved_camera", None)
        binding = getattr(self, "_native_camera_binding", None)
        if not isinstance(saved, dict):
            return
        try:
            self.player_pos = Vec3(saved.get("player_pos", self.player_pos))
            self.player_yaw = float(saved.get("yaw", self.player_yaw))
            self.player_pitch = float(saved.get("pitch", self.player_pitch))
            self.move_velocity = Vec2(0, 0)
            if hasattr(self, "player_velocity"):
                self.player_velocity = Vec3(0, 0, 0)
        except Exception:
            pass
        # The original camera is deliberately not ``self.camera`` while native
        # mode is active. Reassert its frozen transform anyway as an invariant
        # against accidental retained references inside an adapter.
        if isinstance(binding, dict):
            original = binding.get("camera")
            try:
                if original is not None and not original.isEmpty():
                    original.setPos(self.render, binding.get("host_camera_pos"))
                    original.setHpr(self.render, binding.get("host_camera_hpr"))
            except Exception:
                pass

    def _end_native_camera_isolation(self):
        binding = getattr(self, "_native_camera_binding", None)
        if not isinstance(binding, dict):
            return False
        # Restore display regions before deleting the disposable camera.
        for region, camera_np in list(binding.get("display_regions", [])):
            try:
                region.setCamera(camera_np)
            except Exception:
                pass
        self.camera = binding.get("camera")
        self.cam = binding.get("cam")
        self.camNode = binding.get("camNode")
        self.camLens = binding.get("camLens")
        try:
            root = binding.get("dimension_camera_root")
            if root is not None and not root.isEmpty():
                root.removeNode()
        except Exception:
            pass
        self._native_camera_binding = None
        print("native_camera_isolation_end")
        return True

    def _native_task_identity(self, task):
        """Return Panda TaskManager identity, never Python wrapper identity.

        TaskManager.getAllTasks() may expose new Python wrappers around the same
        underlying AsyncTask.  Python id(task) therefore cannot be used to decide
        whether a task existed before a dimension entered.  Panda assigns each
        task a stable manager id; fall back to name only for lightweight test
        doubles that do not expose it.
        """
        try:
            panda_id = getattr(task, "id")
            if callable(panda_id):
                panda_id = panda_id()
            return ("panda-task-id", int(panda_id))
        except Exception:
            pass
        try:
            name = str(getattr(task, "name", "") or task.getName())
        except Exception:
            name = str(getattr(task, "name", "") or "")
        return ("task-name-fallback", name)

    def _snapshot_native_task_state(self) -> set:
        try:
            return {self._native_task_identity(task) for task in self.taskMgr.getAllTasks()}
        except Exception:
            return set()

    def _ensure_host_update_task_alive(self) -> bool:
        """Guarantee MatrixCore's frame task survived dimension teardown."""
        try:
            for task in list(self.taskMgr.getAllTasks()):
                name = str(getattr(task, "name", "") or "")
                if not name:
                    try:
                        name = str(task.getName())
                    except Exception:
                        name = ""
                if name == "update-task":
                    return True
        except Exception:
            pass
        try:
            self.taskMgr.add(self.update_task, "update-task")
            print("native_return_update_task_recovered")
            return True
        except Exception as exc:
            try:
                print(f"native_return_update_task_recovery_failed err={exc.__class__.__name__}:{exc}")
            except Exception:
                pass
            return False

    def _purge_native_task_residue(self, label: str = "") -> int:
        baseline = getattr(self, "native_task_baseline", None)
        if not isinstance(baseline, set):
            return 0
        removed = 0
        try:
            for task in list(self.taskMgr.getAllTasks()):
                if self._native_task_identity(task) in baseline:
                    continue
                # The host frame task is sacred even if a malformed dimension
                # disturbed the task snapshot.  Losing it makes the restored hub
                # render one final frame and then appear frozen.
                try:
                    task_name = str(getattr(task, "name", "") or task.getName())
                except Exception:
                    task_name = str(getattr(task, "name", "") or "")
                if task_name == "update-task":
                    continue
                try:
                    self.taskMgr.remove(task)
                    removed += 1
                except Exception:
                    pass
        except Exception:
            pass
        if removed:
            print(f"native_mode_task_residue_cleaned label={label or getattr(self, 'native_mode_label', '')} count={removed}")
        self._ensure_host_update_task_alive()
        return removed

    def _unload_native_adapter_module(self) -> bool:
        name = str(getattr(self, "native_adapter_module_name", "") or "")
        self.native_adapter_module_name = ""
        if not name:
            return False
        try:
            sys.modules.pop(name, None)
            return True
        except Exception:
            return False

    def _snapshot_native_listener_owners(self) -> set:
        owners = set()
        try:
            msg = self._real_panda_messenger()
            for event in msg.getEvents():
                for entry in (msg.whoAccepts(event) or {}).values():
                    fn = entry[0] if isinstance(entry, (list, tuple)) else entry
                    owner = getattr(fn, "__self__", None)
                    if owner is not None:
                        owners.add(id(owner))
        except Exception:
            pass
        return owners

    def _destroy_orphaned_native_gui(self, label: str = "") -> int:
        """Destroy DirectGui widgets a dimension left behind once their nodes were purged.

        _purge_native_scene_residue removes a dimension's leftover 2-D nodes, but a DirectButton
        removed that way keeps its click listeners on the messenger (one retired dimension left 17 per visit).
        Only widgets created during the visit and no longer attached to the 2-D scene are touched.
        """
        baseline = getattr(self, "native_listener_baseline", None)
        if not isinstance(baseline, set):
            return 0
        try:
            from direct.gui.DirectGuiBase import DirectGuiBase
            msg = self._real_panda_messenger()
        except Exception:
            return 0
        roots = [r for r in (getattr(self, "render2d", None), getattr(self, "render", None)) if r is not None]
        orphans = {}
        for event in list(msg.getEvents()):
            for entry in list((msg.whoAccepts(event) or {}).values()):
                fn = entry[0] if isinstance(entry, (list, tuple)) else entry
                owner = getattr(fn, "__self__", None)
                if owner is None or id(owner) in baseline or not isinstance(owner, DirectGuiBase):
                    continue
                try:
                    attached = (not owner.isEmpty()) and any(owner.getTop() == root for root in roots)
                except Exception:
                    attached = False
                if not attached:
                    orphans[id(owner)] = owner
        for owner in orphans.values():
            try:
                owner.destroy()
            except Exception:
                pass
            try:
                msg.ignoreAll(owner)
            except Exception:
                pass
        if orphans:
            print(f"native_mode_gui_residue_destroyed label={label} count={len(orphans)}")
        return len(orphans)

    def suspend_for_native_mode(self, label: str):
        self.native_listener_baseline = self._snapshot_native_listener_owners()
        self.native_scene_baseline = self._snapshot_native_scene_state()
        self.native_task_baseline = self._snapshot_native_task_state()
        # Capture the host presentation BEFORE any handoff helper closes UI,
        # releases mouse capture, hides roots, or changes window properties.
        # Pass 282.41 captured some of this state after handoff had already
        # mutated it, which made an exact return impossible even when teardown
        # otherwise succeeded.
        self.native_saved_camera = {
            "pos": Vec3(self.camera.getPos(self.render)),
            "hpr": Vec3(self.camera.getHpr(self.render)),
            "player_pos": Vec3(self.player_pos),
            "yaw": float(self.player_yaw),
            "pitch": float(self.player_pitch),
            "lens_fov": self.camLens.getFov() if getattr(self, "camLens", None) is not None else None,
            "lens_near": self.camLens.getNear() if getattr(self, "camLens", None) is not None else None,
            "lens_far": self.camLens.getFar() if getattr(self, "camLens", None) is not None else None,
            "background_color": Vec4(self.win.getClearColor()) if self.win is not None else None,
            "current_bg_rgb": tuple(getattr(self, "current_bg_rgb", ())) or None,
            "current_hub_rgb": tuple(getattr(self, "current_hub_rgb", ())) or None,
            "hud_hidden": bool(self.hud_root.isHidden()) if getattr(self, "hud_root", None) is not None else False,
            "crosshair_hidden": bool(self.crosshair_root.isHidden()) if getattr(self, "crosshair_root", None) is not None else False,
            "root_3d_stashed": bool(self.root_3d.isStashed()) if getattr(self, "root_3d", None) is not None else False,
            "cursor_hidden": bool(self.win.getProperties().getCursorHidden()) if self.win is not None and hasattr(self.win, "getProperties") else True,
            "mouse_mode": self.win.getProperties().getMouseMode() if self.win is not None and hasattr(self.win, "getProperties") else None,
            "mouse_captured": bool(getattr(self, "mouse_captured", True)),
        }
        self.native_adapter_module_name = ""
        self.native_mode_label = label
        self.native_mode_start_time = time.monotonic()
        self.native_mode_return_pending = False
        # Native artifact dimensions own the visible camera/window while mounted.
        # Treat them like a hard focus/scene isolation state so Core window events
        # from Windows overlays/recording cannot recenter or reassert hub control.
        self.native_mode_isolated = True
        self.active_world_runtime_state_label = "NATIVE_MODE"
        self.runtime_world_signature = f"NATIVE DIMENSION // {str(label or 'MODE').upper()}"
        self.close_core_console()
        self.menu_open = False
        try:
            if hasattr(self, "menu_root") and self.menu_root is not None and not self.menu_root.isEmpty():
                self.menu_root.hide()
        except Exception:
            pass
        self.mouse_captured = False
        self.keys.clear()
        self.move_velocity = Vec2(0, 0)
        # Pass 282.16: native dimensions get a real input handoff, not merely
        # inert host handlers.  The previous native path had a restore helper but
        # never called the matching suspend helper, so teardown could skip
        # setup_input() and leave ESC / the pause HUD unbound after TAB returned.
        # Clear hold state at the boundary and unregister every host gameplay/menu
        # event except TAB before the dimension registers its own listeners.
        self.esc_hold_active = False
        self.esc_hold_exit_triggered = False
        self.esc_hold_start = 0.0
        self.esc_hold_deadline = 0.0
        self._suspend_host_player_input_for_dimension()
        # A saved Ember aircraft is global for the default HoloVerse world, but
        # it must not remain active or visually overlap a same-window dimension.
        try:
            self.shell_flight_craft_active = False
            self.shell_flight_craft_velocity = Vec3(0, 0, 0)
            self.shell_flight_craft_boost = 1.0
            node = getattr(self, "shell_flight_craft_visual_root", None)
            if node is not None and not node.isEmpty():
                node.removeNode()
            self.shell_flight_craft_visual_root = None
            self.shell_flight_craft_visual_signature = ""
        except Exception:
            pass
        # Swap the active 3-D display region to a disposable dimension camera.
        # HoloVerse's original camera/player remain physically frozen off-screen.
        self._begin_native_camera_isolation()
        if hasattr(self, "root_3d") and self.root_3d is not None and not self.root_3d.isEmpty():
            self.root_3d.stash()
        if hasattr(self, "hud_root") and self.hud_root is not None and not self.hud_root.isEmpty():
            self.hud_root.hide()
        if hasattr(self, "crosshair_root") and self.crosshair_root is not None and not self.crosshair_root.isEmpty():
            self.crosshair_root.hide()
        if self.audio:
            # A native dimension owns the entire audio field while mounted.  Stop
            # every HoloVerse-owned cue before the adapter is created, then remain
            # silent until TAB returns home.  This happens before dimension audio
            # exists, so the hard stop cannot silence the incoming game's sounds.
            try:
                self.audio.stop_all(stop_oneshots=True)
            except Exception:
                try:
                    self.audio.stop_loop("hub_music")
                    self.audio.stop_loop("hub_air")
                except Exception:
                    pass
            self.native_mode_audio_profile = {"label": str(label or "MODE"), "source": "dimension_only_host_silent"}
        if self.win is not None and hasattr(self.win, "requestProperties"):
            props = WindowProperties()
            mode_requires_capture = True
            try:
                active_manifest = dict(getattr(self, "_pending_native_manifest", {}) or {})
                if active_manifest:
                    mode_requires_capture = bool(active_manifest.get("requires_mouse_capture", True))
                elif "holomap" in str(label or "").lower().replace(" ", ""):
                    mode_requires_capture = False
            except Exception:
                mode_requires_capture = True
            props.setCursorHidden(bool(mode_requires_capture))
            props.setForeground(True)
            self.win.requestProperties(props)
        # No host-owned dimension HUD or menu input. The linked reality gets the
        # full visual/input field; TAB alone remains HoloVerse's return affordance.
        if getattr(self, "center_hint", None) is not None:
            self.center_hint["text"] = ""
        self._append_mode_gateway_history("native_begin", label=label, route=MODE_LAUNCH_NATIVE)
        print(f"native_host_dormancy_begin label={label} host_audio=stopped host_clock=frozen")
        print(f"native_mode_begin label={label}")

    _NATIVE_BRIDGE_HELD = ("w", "a", "s", "d", "shift", "space", "control", "alt",
                           "arrow_left", "arrow_right", "arrow_up", "arrow_down")
    _NATIVE_BRIDGE_PRESS = ("mouse1", "mouse3", "e", "q", "r", "t", "v", "f", "g", "b", "n", "c",
                            "i", "j", "k", "l", "u", "o", "p", "y", "z", "x", "h", "m", "enter",
                            "wheel_up", "wheel_down", "[", "]",
                            "f1", "f3", "f4", "f5", "f6", "f7", "f8", "f9", "f10", "f11", "f12")
    _NATIVE_BRIDGE_ACTION_NAMES = {"[": "bracket_left", "]": "bracket_right"}

    @staticmethod
    def _real_panda_messenger():
        from direct.showbase import MessengerGlobal
        current = MessengerGlobal.messenger
        return getattr(current, "_real", current)

    def _dimension_owns_key_input(self) -> bool:
        """True when anything but HoloVerse itself listens for the movement / use keys."""
        try:
            panda_messenger = self._real_panda_messenger()
        except Exception:
            return True
        for event in ("w", "a", "s", "d", "space", "e", "mouse1"):
            try:
                acceptors = panda_messenger.whoAccepts(event) or {}
            except Exception:
                return True
            for entry in acceptors.values():
                fn = entry[0] if isinstance(entry, (list, tuple)) else entry
                if getattr(fn, "__self__", None) is not self:
                    return True
        return False

    def _install_native_input_bridge(self, mode_obj, label: str = "") -> bool:
        """Forward keys to dimensions built on the host-forwarded input contract.

        Since Pass 282.16 HoloVerse unregisters its own controls when a dimension enters.
        Dimensions that take their input from HoloVerse instead of registering keys
        themselves (``on_host_action`` and/or ``host.keys``: HoloUtopia, HoloTactics, Vector Arena)
        were left with no input at all.  The bridge is a separate
        listener object, so HoloVerse's own handlers stay unregistered, and it is only
        installed when the dimension has the hook and registered no keys of its own
        (HoloCore, HoloShell and the Indigo Giant bind their keys directly).
        """
        self._remove_native_input_bridge()
        handler = getattr(mode_obj, "on_host_action", None)
        if not callable(handler) or self._dimension_owns_key_input():
            return False
        try:
            from direct.showbase.DirectObject import DirectObject
            bridge = DirectObject()
            # Register on Panda's real messenger: HoloUtopia replaces the global messenger
            # with a capturing proxy, which would swallow a plain DirectObject.accept().
            real = self._real_panda_messenger()

            def listen(event, method, extra):
                real.accept(event, bridge, method, extra, 1)

            for key in self._NATIVE_BRIDGE_HELD:
                listen(key, self._native_bridge_held, [key, True])
                listen(f"{key}-up", self._native_bridge_held, [key, False])
            for key in self._NATIVE_BRIDGE_PRESS:
                action = self._NATIVE_BRIDGE_ACTION_NAMES.get(key, key)
                listen(key, self._native_bridge_action, [action])
                if key in ("mouse1", "mouse3", "e", "q"):
                    listen(f"{key}-up", self._native_bridge_action, [f"{action}_up"])
            for number in range(10):
                listen(str(number), self._native_bridge_action, [f"number_{number}"])
            self._native_input_bridge = bridge
            print(f"native_input_bridge label={label} installed=1")
            return True
        except Exception as exc:
            self._native_input_bridge = None
            print(f"native_input_bridge_failed label={label} err={exc.__class__.__name__}:{exc}")
            return False

    # ------------------------------------------------------------------
    # Pass 282.77: HoloVerse pause for same-window dimensions
    # ------------------------------------------------------------------
    def _install_native_pause_listener(self, label: str = "") -> None:
        """ESC pauses a dimension that has no ESC handling of its own.

        HoloVerse unbinds its own ESC while a dimension runs, so in dimensions without a pause
        menu (HoloCore, Vector Arena, HoloTactics, ...) ESC did nothing and the camera kept
        following the mouse.  Dimensions with their own pause menu keep it; a dimension can also
        call ``host.toggle_dimension_pause()`` itself (The Archivist does when ESC has nothing
        left to close)."""
        self._remove_native_pause_listener()
        try:
            msg = self._real_panda_messenger()
            for entry in (msg.whoAccepts("escape") or {}).values():
                fn = entry[0] if isinstance(entry, (list, tuple)) else entry
                if getattr(fn, "__self__", None) is not self:
                    return                      # the dimension owns ESC (its own pause menu)
            from direct.showbase.DirectObject import DirectObject
            listener = DirectObject()
            msg.accept("escape", listener, self.toggle_dimension_pause, [], 1)
            self._native_pause_listener = listener
            print(f"native_pause_listener label={label} installed=1")
        except Exception as exc:
            print(f"native_pause_listener_failed label={label} err={exc.__class__.__name__}:{exc}")

    def _remove_native_pause_listener(self) -> None:
        listener = getattr(self, "_native_pause_listener", None)
        self._native_pause_listener = None
        if listener is not None:
            try:
                self._real_panda_messenger().ignoreAll(listener)
            except Exception:
                pass

    def toggle_dimension_pause(self, *args) -> bool:
        if getattr(self, "active_native_mode", None) is None:
            return False
        if bool(getattr(self, "native_paused", False)):
            self._resume_native_dimension()
        else:
            self._pause_native_dimension()
        return True

    def _pause_native_dimension(self) -> None:
        if bool(getattr(self, "native_paused", False)):
            return
        self.native_paused = True
        # Freeze the dimension's own tasks (its camera / mouse look runs in them) - every task
        # it started, never HoloVerse's frame task.
        baseline = getattr(self, "native_task_baseline", None) or set()
        held = []
        try:
            for task in list(self.taskMgr.getAllTasks()):
                if self._native_task_identity(task) in baseline:
                    continue
                name = str(task.getName() or "")
                if name == "update-task" or name.startswith(("native-", "screen-fade", "holoverse-native-pause")):
                    continue
                self.taskMgr.remove(task)
                held.append(task)
        except Exception as exc:
            print(f"native_pause_task_hold_failed err={exc.__class__.__name__}:{exc}")
        self._native_paused_tasks = held
        try:
            props = self.win.getProperties()
            self._native_pause_pointer = (bool(props.getCursorHidden()), props.getMouseMode())
            wp = WindowProperties()
            wp.setCursorHidden(False)
            wp.setMouseMode(WindowProperties.M_absolute)
            self.win.requestProperties(wp)
        except Exception:
            self._native_pause_pointer = None
        self._show_native_pause_overlay(True)
        print(f"native_dimension_paused label={getattr(self, 'native_mode_label', '')} held_tasks={len(held)}")

    def _resume_native_dimension(self, *, quiet: bool = False) -> None:
        if not bool(getattr(self, "native_paused", False)):
            return
        self.native_paused = False
        for task in list(getattr(self, "_native_paused_tasks", []) or []):
            try:
                self.taskMgr.add(task)
            except Exception as exc:
                print(f"native_resume_task_failed err={exc.__class__.__name__}:{exc}")
        self._native_paused_tasks = []
        pointer = getattr(self, "_native_pause_pointer", None)
        self._native_pause_pointer = None
        if pointer is not None and not quiet:
            try:
                wp = WindowProperties()
                wp.setCursorHidden(pointer[0])
                wp.setMouseMode(pointer[1])
                self.win.requestProperties(wp)
                # Re-centre so the dimension's mouse look does not read the whole pause as one swipe.
                self.win.movePointer(0, self.win.getXSize() // 2, self.win.getYSize() // 2)
            except Exception:
                pass
        self._show_native_pause_overlay(False)

    def _pause_return_home(self) -> None:
        self.handle_tab_action()

    def _show_native_pause_overlay(self, visible: bool) -> None:
        root = getattr(self, "_native_pause_overlay", None)
        if visible and (root is None or root.isEmpty()):
            try:
                root = self.aspect2d.attachNewNode("holoverse-native-pause-overlay")
                root.setBin("fixed", 140)
                DirectFrame(parent=root, frameColor=(0.0, 0.01, 0.02, 0.55), frameSize=(-3.0, 3.0, -1.5, 1.5))
                kw = self._core_text_kw()
                DirectLabel(parent=root, text="PAUSED", text_scale=0.085, text_fg=(0.80, 1.0, 1.0, 1.0),
                            frameColor=(0, 0, 0, 0), pos=(0, 0, 0.06), **kw)
                DirectLabel(parent=root, text="ESC  RESUME     //     TAB  RETURN TO MATRIXCORE", text_scale=0.032,
                            text_fg=(0.55, 0.92, 1.0, 0.95), frameColor=(0, 0, 0, 0), pos=(0, 0, -0.06), **kw)
                # Pass 282.78: clickable too (the cursor is free while paused).
                for text, z, command in (("RESUME", -0.20, self._resume_native_dimension),
                                         ("RETURN TO MATRIXCORE", -0.33, self._pause_return_home)):
                    button = DirectButton(parent=root, text=text, command=command, pos=(0, 0, z), scale=0.062,
                                          frameSize=(-5.2, 5.2, -0.42, 0.62), text_scale=0.5, relief=1,
                                          rolloverSound=None, clickSound=None, **kw)
                    try:
                        self.apply_core_button_style(button, role="mode", available=True)
                    except Exception:
                        pass
                self._native_pause_overlay = root
            except Exception as exc:
                print(f"native_pause_overlay_failed err={exc.__class__.__name__}:{exc}")
                return
        if root is not None and not root.isEmpty():
            if visible:
                root.show()
            else:
                root.hide()

    def _native_bridge_held(self, key: str, down: bool) -> None:
        if bool(getattr(self, "native_paused", False)) and down:
            return
        try:
            self.keys[key] = bool(down)
        except Exception:
            pass
        self._native_bridge_action(key if down else f"{key}_up")

    def _native_bridge_action(self, action: str) -> None:
        if bool(getattr(self, "native_paused", False)):
            return
        mode_obj = getattr(self, "active_native_mode", None)
        handler = getattr(mode_obj, "on_host_action", None)
        if not callable(handler):
            return
        try:
            handler(action)
        except Exception as exc:
            print(f"native_input_bridge_action_error action={action} err={exc.__class__.__name__}:{exc}")

    def _remove_native_input_bridge(self) -> None:
        bridge = getattr(self, "_native_input_bridge", None)
        self._native_input_bridge = None
        if bridge is None:
            return
        try:
            self._real_panda_messenger().ignoreAll(bridge)
        except Exception:
            pass
        try:
            self.keys.clear()
        except Exception:
            pass

    def _after_native_mode_enter(self, mode_obj, label: str = "") -> None:
        """Host fix-ups once a same-window dimension has entered.

        Every route that mounts a dimension calls this: launch_native_mode and the Dimension
        Registry's own launch (Gleebs' archive, HoloSpace planets, guide bots).
        """
        self._apply_native_mode_cursor(mode_obj, label)
        self._install_native_input_bridge(mode_obj, label)
        self._install_native_pause_listener(label)

    def _apply_native_mode_cursor(self, mode_obj, label: str = "") -> None:
        """Let a dimension that is driven by mouse clicks (menus, click-to-move) keep a cursor.

        suspend_for_native_mode hides the cursor for every dimension whose manifest does not say
        otherwise, which left mouse-driven dimensions such as The Indigo Giant with an invisible
        cursor over their title menu.  A mode object may set ``requires_mouse_capture = False``.
        The cursor state is restored from native_saved_camera when the dimension returns.
        """
        label_key = canonical_dimension_lookup_key(label)
        # Registry launches label as "DIMENSION // <TITLE>", so match the name inside the label.
        mouse_driven = any(key in label_key for key in MOUSE_DRIVEN_NATIVE_DIMENSIONS)
        if getattr(mode_obj, "requires_mouse_capture", True) is not False and not mouse_driven:
            return
        try:
            if self.win is not None and hasattr(self.win, "requestProperties"):
                props = WindowProperties()
                props.setCursorHidden(False)
                self.win.requestProperties(props)
            print(f"native_mode_cursor label={label} visible=1")
        except Exception as exc:
            print(f"native_mode_cursor_failed label={label} err={exc.__class__.__name__}:{exc}")

    def collect_native_mode_result(self, mode_obj) -> dict:
        if mode_obj is None:
            return {}
        for method_name in ("get_holoverse_result", "get_result", "result"):
            method = getattr(mode_obj, method_name, None)
            if callable(method):
                try:
                    payload = method()
                    return dict(payload) if isinstance(payload, dict) else {}
                except Exception as exc:
                    try:
                        print(f"native_mode_result_error label={getattr(self, 'native_mode_label', '')} method={method_name} err={exc.__class__.__name__}:{exc}")
                    except Exception:
                        pass
                    return {}
        payload = getattr(mode_obj, "holoverse_result", {})
        return dict(payload) if isinstance(payload, dict) else {}

    def record_native_dimension_result(self, mode_name: str, route: str, result: dict) -> dict:
        if not isinstance(result, dict) or not result:
            return {}
        progress = self.load_matrixcore_progression()
        bucket = progress.setdefault("dimension_results", {})
        if not isinstance(bucket, dict):
            bucket = {}
        mode_name = str(mode_name or "Dimension").strip() or "Dimension"
        entry = bucket.get(mode_name) if isinstance(bucket.get(mode_name), dict) else {}
        score_delta = int(float(result.get("score_delta", 0) or 0))
        entry["count"] = int(entry.get("count", 0) or 0) + 1
        entry["last_at"] = datetime.now().isoformat(timespec="seconds")
        entry["route"] = str(route or entry.get("route", ""))
        entry["score_total"] = int(entry.get("score_total", 0) or 0) + score_delta
        entry["last_score_delta"] = score_delta
        entry["completed"] = bool(result.get("completed", False))
        entry["fragments_recovered"] = str(result.get("fragments_recovered", ""))
        entry["fragments_required"] = str(result.get("fragments_required", ""))
        signal = str(result.get("signal") or result.get("memory_fragment") or "").strip()
        if signal:
            signals = entry.get("signals") if isinstance(entry.get("signals"), list) else []
            if signal not in signals:
                signals.append(signal)
            entry["signals"] = signals[-12:]
            entry["last_signal"] = signal
        response = str(result.get("gleebs_response") or "").strip()
        if response:
            entry["gleebs_response"] = response
        # 282.19: Vector Arena exports a richer but still bounded result packet.
        # Keep only progression-grade values so the host remembers the run without
        # owning or duplicating the arena's local simulation state.
        if str(result.get("mode_id") or "").strip().lower() == "vector_arena":
            vector_scalar_fields = (
                "kills", "wave", "highest_wave", "wave_kind", "wave_set",
                "guardian_waves_completed", "arena_reconstructions",
                "arena_mutations_survived", "arena_family", "arena_family_name",
                "largest_arena_radius", "arena_architecture",
                "arena_architecture_piece_count", "arena_mutation",
                "arena_mutation_name", "upgrades_selected", "flanking_spawns",
                "guardian_specials_used", "hazard_activations", "hazard_hits_taken",
                "encounter_doctrine", "enemy_evolution_spawns",
                "highest_evolution_level_seen", "guardian_phase_transitions",
                "breaches_sealed", "weapon_rank", "weapon_module",
            )
            vector_counts = ("special_wave_counts", "arena_family_counts", "enemy_evolution_counts", "upgrade_stacks")
            summary = {}
            for key in vector_scalar_fields:
                value = result.get(key)
                if isinstance(value, (str, int, float, bool)):
                    summary[key] = value
            for key in vector_counts:
                value = result.get(key)
                if isinstance(value, dict):
                    summary[key] = {str(k): v for k, v in list(value.items())[:32] if isinstance(v, (str, int, float, bool))}
            entry["vector_arena"] = summary
        bucket[mode_name] = entry
        progress["dimension_results"] = bucket
        matrixcore = progress.setdefault("matrixcore", {})
        matrixcore["last_dimension_result"] = mode_name
        matrixcore["last_dimension_score_delta"] = score_delta
        if signal:
            matrixcore["last_dimension_signal"] = signal
        self.save_matrixcore_progression(progress)
        try:
            self.update_matrixcore_gate_result_state(mode_name, result, route)
        except Exception:
            pass
        return self.append_matrixcore_event({
            "kind": "dimension_result",
            "mode": mode_name,
            "route": route,
            "source": "native",
            "score_delta": score_delta,
            "completed": bool(result.get("completed", False)),
            "signal": signal,
        })

    def _shutdown_native_mode_object(self, mode_obj) -> str:
        """Run exactly one dimension teardown hook.

        Adapters in this MatrixCore line commonly implement exit() by calling
        destroy() (or vice versa).  Calling both from the host doubles cleanup
        work and can touch already-destroyed DirectGUI/audio/task state.
        """
        if mode_obj is None:
            return "none"
        for method_name in ("exit", "destroy", "cleanup"):
            method = getattr(mode_obj, method_name, None)
            if not callable(method):
                continue
            try:
                method()
                return method_name
            except Exception as exc:
                try:
                    print(f"native_mode_{method_name}_error label={self.native_mode_label} err={exc.__class__.__name__}:{exc}")
                except Exception:
                    pass
                return f"{method_name}_error"
        return "no_hook"

    def return_from_native_mode(self, reason: str = "return"):
        mode_obj = getattr(self, "active_native_mode", None)
        # Pass 282.73: a second return request (TAB plus a game's own exit, or a late callback)
        # must not run the teardown again: with no dimension active it would purge HoloVerse's
        # own tasks.
        if mode_obj is None and not bool(getattr(self, "native_mode_isolated", False)):
            return False
        native_result = self.collect_native_mode_result(mode_obj)
        self.active_native_mode = None
        self.native_mode_return_pending = False
        self._stop_native_mode_audio()
        teardown_hook = self._shutdown_native_mode_object(mode_obj)
        try:
            print(f"native_mode_teardown label={self.native_mode_label} hook={teardown_hook}")
        except Exception:
            pass
        # Some adapters own their own music/SFX objects.  After their exit hook,
        # hard-stop the shared bus again so no previous dimension song carries
        # into the restored hub soundscape.
        try:
            self._stop_native_mode_audio()
        except Exception:
            pass
        try:
            self._purge_native_task_residue(str(getattr(self, "native_mode_label", "") or ""))
        except Exception:
            pass
        try:
            self._purge_native_scene_residue(str(getattr(self, "native_mode_label", "") or ""))
        except Exception:
            pass
        try:
            self._unload_native_adapter_module()
        except Exception:
            pass
        try:
            self._remove_native_input_bridge()
            self._remove_native_import_root()
            self._remove_native_pause_listener()
            if bool(getattr(self, "native_paused", False)):
                # Held tasks belong to the dimension being torn down: drop them, do not resume.
                self._native_paused_tasks = []
                self._resume_native_dimension(quiet=True)
        except Exception:
            pass
        try:
            self._destroy_orphaned_native_gui(str(getattr(self, "native_mode_label", "") or ""))
        except Exception:
            pass
        self.native_listener_baseline = None
        host_update_alive = self._ensure_host_update_task_alive()
        host_input_ready = False
        try:
            host_input_ready = bool(self._restore_host_player_input_after_dimension())
        except Exception as exc:
            try:
                print(f"native_host_input_restore_failed err={exc.__class__.__name__}:{exc}")
            except Exception:
                pass
        # Reconnect the original HoloVerse camera before restoring its saved
        # transform/lens.  The disposable dimension camera is destroyed here.
        self._end_native_camera_isolation()
        saved = getattr(self, "native_saved_camera", None)
        if hasattr(self, "root_3d") and self.root_3d is not None and not self.root_3d.isEmpty():
            try:
                if isinstance(saved, dict) and bool(saved.get("root_3d_stashed", False)):
                    self.root_3d.stash()
                else:
                    self.root_3d.unstash()
            except Exception:
                self.root_3d.unstash()
        if hasattr(self, "hud_root") and self.hud_root is not None and not self.hud_root.isEmpty():
            try:
                if isinstance(saved, dict) and bool(saved.get("hud_hidden", False)):
                    self.hud_root.hide()
                elif getattr(self.cfg, "hud_visible", True):
                    self.hud_root.show()
            except Exception:
                pass
        if hasattr(self, "crosshair_root") and self.crosshair_root is not None and not self.crosshair_root.isEmpty():
            try:
                if isinstance(saved, dict) and bool(saved.get("crosshair_hidden", False)):
                    self.crosshair_root.hide()
                elif getattr(self.cfg, "hud_visible", True):
                    self.crosshair_root.show()
            except Exception:
                pass
        if isinstance(saved, dict):
            self.player_pos = Vec3(saved.get("player_pos", self.base_teleport))
            self.player_yaw = float(saved.get("yaw", self.player_yaw))
            self.player_pitch = float(saved.get("pitch", self.player_pitch))
            self.camera.setPos(saved.get("pos", self.player_pos))
            self.camera.setHpr(saved.get("hpr", Vec3(self.player_yaw, self.player_pitch, 0)))
            try:
                lens_fov = saved.get("lens_fov")
                if lens_fov is not None and getattr(self, "camLens", None) is not None:
                    self.camLens.setFov(lens_fov)
                near = saved.get("lens_near")
                far = saved.get("lens_far")
                if near is not None and far is not None and getattr(self, "camLens", None) is not None:
                    self.camLens.setNearFar(float(near), float(far))
            except Exception:
                pass
        # Clear transient dimension movement/flight state without undoing the
        # exact camera/lens snapshot restored above.  Pass 282.41 restored the
        # snapshot and then immediately overwrote it with hard-coded hub values.
        try:
            returned_key_for_anchor = str(getattr(self, "native_mode_label", "") or "").strip().lower()
            self._restore_hub_ground_control_state(
                reason=f"native_return_{returned_key_for_anchor or 'mode'}",
                preserve_view=True,
            )
            self.reload_default_holoverse_shell(reason=f"native_return_{returned_key_for_anchor or 'mode'}")
            self.sync_active_world_runtime_state()
        except Exception:
            pass
        # Re-assert exact host presentation after any shell rebuild.
        if isinstance(saved, dict):
            try:
                self.player_pos = Vec3(saved.get("player_pos", self.player_pos))
                self.player_yaw = float(saved.get("yaw", self.player_yaw))
                self.player_pitch = float(saved.get("pitch", self.player_pitch))
                self.camera.setPos(saved.get("pos", self.player_pos))
                self.camera.setHpr(saved.get("hpr", Vec3(self.player_yaw, self.player_pitch, 0)))
                lens_fov = saved.get("lens_fov")
                if lens_fov is not None and getattr(self, "camLens", None) is not None:
                    self.camLens.setFov(lens_fov)
                near = saved.get("lens_near")
                far = saved.get("lens_far")
                if near is not None and far is not None and getattr(self, "camLens", None) is not None:
                    self.camLens.setNearFar(float(near), float(far))
                current_bg = saved.get("current_bg_rgb")
                if current_bg is not None:
                    self.current_bg_rgb = tuple(float(v) for v in current_bg[:3])
                current_hub = saved.get("current_hub_rgb")
                if current_hub is not None:
                    self.current_hub_rgb = tuple(float(v) for v in current_hub[:3])
                background = saved.get("background_color")
                if background is not None:
                    self.setBackgroundColor(background)
            except Exception:
                pass
        self.mouse_captured = bool(saved.get("mouse_captured", True)) if isinstance(saved, dict) else True
        if self.win is not None and hasattr(self.win, "requestProperties"):
            props = WindowProperties()
            if isinstance(saved, dict):
                try:
                    props.setCursorHidden(bool(saved.get("cursor_hidden", True)))
                except Exception:
                    props.setCursorHidden(True)
                try:
                    mouse_mode = saved.get("mouse_mode")
                    if mouse_mode is not None:
                        props.setMouseMode(mouse_mode)
                except Exception:
                    pass
            else:
                props.setCursorHidden(True)
            props.setForeground(True)
            self.win.requestProperties(props)
        if not SELF_TEST and (not isinstance(saved, dict) or bool(saved.get("cursor_hidden", True))):
            self.recenter_mouse(force=True)
        if self.audio:
            self.update_soundscape(0.0, force=True)
            self.audio.play('menu_close.wav', 'sfx', 0.72)
        elapsed = max(0.0, time.monotonic() - float(getattr(self, "native_mode_start_time", time.monotonic())))
        returned_label = str(self.native_mode_label or "MODE")
        discovery_notice = str(getattr(self, "pending_dimension_discovery_notice", "") or "")
        self.pending_dimension_discovery_notice = ""
        self.center_hint["text"] = self.format_dimension_return_message(returned_label, native_result, discovery=discovery_notice)
        return_route = str(getattr(self, "native_mode_route", "") or MODE_LAUNCH_NATIVE)
        return_reason = str(reason or "return")
        if native_result:
            try:
                signal = str(native_result.get("signal") or native_result.get("memory_fragment") or "").strip()
                score_delta = int(float(native_result.get("score_delta", 0) or 0))
                completed = bool(native_result.get("completed", False))
                result_bits = []
                if signal:
                    result_bits.append(f"signal={signal}")
                if score_delta:
                    result_bits.append(f"score_delta={score_delta}")
                if completed:
                    result_bits.append("completed=true")
                if result_bits:
                    return_reason = f"{return_reason}; " + "; ".join(result_bits)
            except Exception:
                pass
        self.record_matrixcore_dimension_signal("dimension_return", returned_label, label=returned_label, route=return_route, source="native", reason=return_reason)
        if native_result:
            try:
                self.record_native_dimension_result(returned_label, return_route, native_result)
            except Exception as exc:
                try:
                    print(f"native_mode_result_record_error label={returned_label} err={exc.__class__.__name__}:{exc}")
                except Exception:
                    pass
        native_response = str(native_result.get("gleebs_response") or "") if isinstance(native_result, dict) else ""
        self.maybe_queue_gleebs_return_dialogue(returned_label, native_response)
        self._append_mode_gateway_history("native_return", label=self.native_mode_label, route=return_route, extra={"reason": reason, "elapsed": f"{elapsed:.2f}"})
        print(
            f"native_host_dormancy_end label={self.native_mode_label} "
            f"update_task_alive={int(bool(host_update_alive))} "
            f"host_input_ready={int(bool(host_input_ready))} esc_hud=restored host_audio=restored"
        )
        print(f"native_mode_return label={self.native_mode_label} reason={reason} elapsed={elapsed:.2f}")
        self.begin_screen_fade_in(0.7)      # Pass 282.62: fade HoloVerse back in instead of popping
        self.native_mode_label = ""
        self.native_mode_entry = None
        self.native_mode_route = ""
        self.native_scene_baseline = None
        self.native_task_baseline = None
        self.native_mode_isolated = False
        if bool(getattr(self, "world_shell_preloaded_default", False)):
            bridge = False
            try:
                report = getattr(self, "world_shell_preload_report", {}) or {}
                bridge = bool(report.get("source_bridge_active", False)) if isinstance(report, dict) else False
            except Exception:
                bridge = False
            self.runtime_world_signature = "HOLOVERSE DEFAULT // WORLD.PY SOURCE BRIDGE" if bridge else "HOLOVERSE DEFAULT // FULL-SCALE WORLD.PY RINGS"
        else:
            self.runtime_world_signature = "HUB STANDBY"
        self.sync_active_world_runtime_state()
        self.refresh_ui()
        # refresh_ui() derives visibility from current config/menu state and can
        # legitimately re-show HUD elements.  Native return, however, must put
        # the host back exactly as it was before the dimension mounted.  Reapply
        # the captured presentation state after that refresh so modal/title/test
        # states are not silently converted into generic gameplay presentation.
        if isinstance(saved, dict):
            try:
                if hasattr(self, "root_3d") and self.root_3d is not None and not self.root_3d.isEmpty():
                    self.root_3d.stash() if bool(saved.get("root_3d_stashed", False)) else self.root_3d.unstash()
                if hasattr(self, "hud_root") and self.hud_root is not None and not self.hud_root.isEmpty():
                    self.hud_root.hide() if bool(saved.get("hud_hidden", False)) else self.hud_root.show()
                if hasattr(self, "crosshair_root") and self.crosshair_root is not None and not self.crosshair_root.isEmpty():
                    self.crosshair_root.hide() if bool(saved.get("crosshair_hidden", False)) else self.crosshair_root.show()
            except Exception:
                pass
        self.native_saved_camera = None

    def launch_native_mode(self, mode: dict, entry: Path | None, label: str, *, source: str = "core") -> bool:
        """Mount a dimension-native adapter inside the live HoloVerse window.

        Pass 54 restores the adapter path for dimensions that already ship a
        ``holoverse_native_adapter.py``. Holo Campaign uses this so artifacts
        enter the playable campaign slice directly instead of spawning the
        crash-prone child-window host.
        """
        mode = dict(mode or {})
        manifest = dict(mode.get("manifest") or {})
        label = str(label or mode.get("name") or manifest.get("title") or "Dimension")
        if getattr(self, "active_native_mode", None) is not None:
            self.center_hint["text"] = f"CORE // {label.upper()} ALREADY ACTIVE"
            return True
        if getattr(self, "external_process", None) is not None:
            self.center_hint["text"] = "CORE // CLOSE ACTIVE MODE FIRST"
            return False
        if entry is None or not Path(entry).exists():
            self.center_hint["text"] = f"CORE // {label.upper()} ENTRY MISSING"
            return False
        adapter_path = self._mode_adapter_path(mode)
        if adapter_path is None:
            self.center_hint["text"] = f"CORE // {label.upper()} NATIVE ADAPTER MISSING"
            self._append_mode_gateway_history("native_adapter_missing", mode=mode, label=label, route=MODE_LAUNCH_NATIVE, extra={"source": source, "entry": os.fspath(entry)})
            return False
        transition_id = f"{int(time.time() * 1000)}_{re.sub(r'[^a-z0-9]+', '_', label.lower()).strip('_')}_native"
        try:
            self.sync_core()
            self.core_mode_state["launch_count"] = int(self.core_mode_state.get("launch_count", 0)) + 1
            self.core_mode_state["last_mode"] = label
            self.core_mode_state["last_entry"] = Path(entry).name
            self.core_mode_state["last_launch_type"] = MODE_LAUNCH_NATIVE
            self.core_mode_state["last_launch_source"] = str(source or "core")
            save_mode_state(self.core_mode_state)
        except Exception:
            pass
        try:
            self.record_matrixcore_dimension_signal("dimension_transition_begin", label, label=label, route=MODE_LAUNCH_NATIVE, source=str(source or "core"), reason="native_adapter_mount")
        except Exception:
            pass
        self._append_mode_gateway_history(
            "native_adapter_begin",
            mode=mode,
            label=label,
            route=MODE_LAUNCH_NATIVE,
            extra={"transition_id": transition_id, "entry": os.fspath(entry), "adapter": os.fspath(adapter_path), "source": source},
        )
        try:
            self.show_bridge_transition(f"ENTERING {label.upper()}", "MATRIXCORE", target=1.0, hold=0.18)
        except Exception:
            pass
        self._pending_native_manifest = dict(manifest)
        self.present_dimension_loading(label)
        self.suspend_for_native_mode(label)
        try:
            mode_obj = self._load_native_mode_object(mode, Path(entry), label)
            enter = getattr(mode_obj, "enter", None)
            if callable(enter):
                enter()
            # Do not reassert any HoloVerse music after the dimension has entered.
            # The adapter/source owns its soundtrack directly; HoloVerse stays
            # silent and dormant until TAB returns to MatrixCore.
            self.native_mode_audio_profile = {"label": str(label or "MODE"), "source": "dimension_only_host_silent"}
            self.active_native_mode = mode_obj
            self._after_native_mode_enter(mode_obj, label)
            self._pending_native_manifest = {}
            self.native_mode_entry = Path(entry)
            self.native_mode_label = label
            self.native_mode_route = MODE_LAUNCH_NATIVE
            self.last_launched_core_mode = label
            self.last_launched_core_entry = os.fspath(entry)
            # Native dimensions provide their own player-facing objective overlay.
            # Do not leave a Core/debug adapter banner over gameplay.
            self.center_hint["text"] = ""
            self.hide_native_status_overlay()
            self.fade_bridge_transition(hold=0.0)
            try:
                self.bridge_transition_target = 0.0
                self.bridge_transition_hold_until = 0.0
                self._set_bridge_transition_alpha(0.0)
            except Exception:
                pass
            try:
                self.record_matrixcore_dimension_signal("dimension_launch", label, label=label, route=MODE_LAUNCH_NATIVE, source=str(source or "core"), reason="native_adapter_mount")
            except Exception:
                pass
            self._append_mode_gateway_history(
                "native_adapter_active",
                mode=mode,
                label=label,
                route=MODE_LAUNCH_NATIVE,
                extra={"transition_id": transition_id, "adapter": os.fspath(adapter_path), "entry": os.fspath(entry)},
            )
            return True
        except Exception as exc:
            self._pending_native_manifest = {}
            self.active_native_mode = None
            self._append_mode_gateway_history(
                "native_adapter_failed",
                mode=mode,
                label=label,
                route=MODE_LAUNCH_NATIVE,
                extra={"transition_id": transition_id, "adapter": os.fspath(adapter_path), "error": f"{exc.__class__.__name__}: {exc}"},
            )
            try:
                print(f"native_adapter_failed label={label} error={exc.__class__.__name__}:{exc}")
            except Exception:
                pass
            try:
                self.return_from_native_mode(reason="native_adapter_failed")
            except Exception:
                pass
            return False


    def _host_window_hwnd(self) -> int:
        """Best-effort Panda3D OS window handle lookup for Windows child-window hosting."""
        try:
            handle_obj = self.win.getWindowHandle() if self.win is not None else None
        except Exception:
            handle_obj = None
        if handle_obj is None:
            return 0
        for attr in ("getIntHandle", "getOsHandle", "getHandle"):
            getter = getattr(handle_obj, attr, None)
            if callable(getter):
                try:
                    value = int(getter())
                    if value:
                        return value
                except Exception:
                    pass
        try:
            value = int(handle_obj)
            return value if value else 0
        except Exception:
            return 0

    def _host_window_geometry(self) -> tuple[int, int, int, int]:
        """HoloVerse's window origin and client size right now (falls back to the launch rect)."""
        x, y = int(LAUNCH_X), int(LAUNCH_Y)
        w, h = self._embedded_window_size()
        try:
            props = self.win.getProperties() if self.win is not None and hasattr(self.win, "getProperties") else None
            if props is not None and props.hasOrigin() and not bool(getattr(props, "getMinimized", lambda: False)()):
                x, y = int(props.getXOrigin()), int(props.getYOrigin())
        except Exception:
            pass
        return x, y, w, h

    def _embedded_window_size(self) -> tuple[int, int]:
        try:
            if self.win is not None:
                return max(640, int(self.win.getXSize() or LAUNCH_W)), max(360, int(self.win.getYSize() or LAUNCH_H))
        except Exception:
            pass
        return max(640, int(LAUNCH_W or 1280)), max(360, int(LAUNCH_H or 720))

    def launch_embedded_external_level(self, path: Path, label: str, extra_env: dict | None = None) -> bool:
        """Launch the real standalone mode and host its OS window inside HoloVerse.

        On Windows this uses SetParent/WS_CHILD to preserve the original mode
        code while making it appear on the same display. On other platforms, or
        if a host HWND cannot be found, it falls back to normal external launch.
        """
        if os.name != "nt":
            self.center_hint["text"] = f"CORE // {label} EMBED FALLBACK EXTERNAL"
            return bool(self.launch_external_level(path, label, extra_env=extra_env))
        host_hwnd = self._host_window_hwnd()
        if not host_hwnd:
            self.center_hint["text"] = f"CORE // {label} EMBED HOST HWND MISSING"
            return bool(self.launch_external_level(path, label, extra_env=extra_env))
        if path is None or not Path(path).exists():
            self.center_hint["text"] = f"CORE // {label} MISSING"
            return False
        if self.external_process is not None:
            self.center_hint["text"] = f"CORE // {label} ALREADY RUNNING"
            return False
        try:
            audio_bus_path = write_audio_bus(self.cfg)
            launch_settings_path = write_shared_launch_settings(self.cfg)
            holoverse_settings_path = write_holoverse_settings(self.cfg)
            env = os.environ.copy()
            env["MATRIX_AUDIO_CONFIG"] = os.fspath(audio_bus_path)
            env["MATRIX_LAUNCH_SETTINGS"] = os.fspath(launch_settings_path)
            env["HOLOVERSE_SETTINGS_PATH"] = os.fspath(holoverse_settings_path)
            audio_profile_path = Path(path).parent / "audio_profile.json"
            if audio_profile_path.exists():
                env["HOLOVERSE_MODE_AUDIO_PROFILE"] = os.fspath(audio_profile_path)
            env["HOLOVERSE_MODE_NAME"] = str(label)
            env["HOLOVERSE_SHARED_DATA_DIR"] = os.fspath(SHARED_HOLOVERSE_DATA_DIR)
            env["HOLOVERSE_CREATIVITY_BLUEPRINT_DIR"] = os.fspath(SHARED_HOLOVERSE_DATA_DIR / "creativity" / "blueprints")
            shared_sfx_path = CANONICAL_SHARED_SFX_DIR if CANONICAL_SHARED_SFX_DIR.exists() else CORE_SFX_DIR
            env["HOLOVERSE_AUDIO_ROOT"] = os.fspath(AUDIO_LIBRARY_DIR)
            env["HOLOVERSE_SHARED_SFX_DIR"] = os.fspath(shared_sfx_path)
            env["MATRIX_SHARED_SFX_DIR"] = os.fspath(shared_sfx_path)
            env["HOLOVERSE_CORE_SFX_DIR"] = os.fspath(CORE_SFX_DIR)
            env["HOLOVERSE_MUSIC_FILE"] = os.fspath(HOLOVERSE_MUSIC_FILE)
            env["HOLOVERSE_MUSIC_DIR"] = os.fspath(AUDIO_LIBRARY_DIR)
            env["MATRIX_MUSIC_DIR"] = os.fspath(AUDIO_LIBRARY_DIR)
            env["HOLOVERSE_OVERRIDE_SETTINGS"] = "1"
            env["HOLOVERSE_EMBEDDED_MODE"] = "1"
            env["HOLOVERSE_RETURN_KEY"] = "escape"
            env["HOLOVERSE_SINGLE_ESC_RETURN"] = "1"
            env["HOLOVERSE_ESC_SINGLE_RETURN"] = "1"
            env["HOLOVERSE_RETURN_ON_ESC"] = "1"
            env["HOLOVERSE_ROOT_OWNS_MUSIC"] = "1"
            env["NEON_DOGFIGHT_DISABLE_MUSIC"] = "1"
            payload = build_audio_bus_payload(self.cfg)
            launch_payload = build_launch_settings_payload(self.cfg)
            w, h = self._embedded_window_size()
            safe_label = re.sub(r"[^A-Za-z0-9._-]+", "_", str(label or "mode")).strip("_") or "mode"
            return_signal_path = LOG_DIR / f"embedded_return_signal_{safe_label}.json"
            try:
                return_signal_path.unlink(missing_ok=True)
            except Exception:
                pass
            env["HOLOVERSE_RETURN_SIGNAL_PATH"] = os.fspath(return_signal_path)
            self.external_return_signal_path = return_signal_path
            env["MATRIX_MASTER_VOLUME"] = str(payload["master_volume"])
            env["MATRIX_SFX_VOLUME"] = str(payload["sfx_volume"])
            env["MATRIX_MUSIC_VOLUME"] = str(payload["music_volume"])
            env["MATRIX_AMBIENCE_VOLUME"] = str(payload["ambience_volume"])
            env["MATRIX_GAME_WIDTH"] = str(w)
            env["MATRIX_GAME_HEIGHT"] = str(h)
            env["MATRIX_GAME_X"] = str(LAUNCH_X)
            env["MATRIX_GAME_Y"] = str(LAUNCH_Y)
            env["HOLOVERSE_VIRTUAL_WIDTH"] = "1920"
            env["HOLOVERSE_VIRTUAL_HEIGHT"] = "1080"
            env["HOLOVERSE_FPS_CAP"] = str(launch_payload.get("fps_cap", 60) if isinstance(launch_payload, dict) else 60)
            env["HOLOVERSE_VSYNC"] = "1" if launch_payload.get("vsync", True) else "0"
            env["HOLOVERSE_UI_SCALE"] = str(launch_payload.get("ui_scale", 1.0))
            env["HOLOVERSE_RENDER_SCALE"] = str(launch_payload.get("render_scale", 1.0))
            env["HOLOVERSE_MASTER_VOLUME"] = str(payload["master_volume"])
            env["HOLOVERSE_MUSIC_VOLUME"] = str(payload["music_volume"])
            env["HOLOVERSE_SFX_VOLUME"] = str(payload["sfx_volume"])
            env["HOLOVERSE_AMBIENCE_VOLUME"] = str(payload["ambience_volume"])
            env["HOLOVERSE_SOUNDTRACK_ENABLED"] = "1" if payload.get("soundtrack_enabled", True) else "0"
            env["HOLOVERSE_SOUNDTRACK_INTENSITY"] = str(payload.get("soundtrack_intensity", 0.55))
            env["HOLOVERSE_AMBIENCE_INTENSITY"] = str(payload.get("ambience_intensity", 0.45))
            env["HOLOVERSE_HUD_ENABLED"] = "1" if launch_payload.get("hud_visible", True) else "0"
            env["HOLOVERSE_SUBTITLES_ENABLED"] = "1" if launch_payload.get("subtitles_enabled", True) else "0"
            env["HOLOVERSE_BRIGHTNESS"] = str(launch_payload.get("brightness", 1.0))
            env["HOLOVERSE_CONTRAST"] = str(launch_payload.get("contrast", 1.0))
            env["HOLOVERSE_GAMMA"] = str(launch_payload.get("gamma", 1.0))
            env["HOLOVERSE_GRAPHICS_QUALITY"] = str(launch_payload.get("graphics_quality", "medium"))
            env["HOLOVERSE_CONTROLLER_DEADZONE"] = str(launch_payload.get("controller_deadzone", 0.12))
            env["HOLOVERSE_OVERRIDE_MODE_SETTINGS"] = "1" if launch_payload.get("override_mode_settings", True) else "0"
            env["HOLOVERSE_PAUSE_KEY"] = "escape"
            env["MATRIX_GAME_FULLSCREEN"] = "0"
            env["MATRIX_GAME_BORDERLESS"] = "0"
            env["MATRIX_GAME_BORDERED_FULLSCREEN"] = "0"
            env["MATRIX_GAME_MOUSE_SENSITIVITY"] = str(launch_payload["mouse_sensitivity"])
            env["MATRIX_GAME_INVERT_Y"] = "1" if launch_payload["invert_y"] else "0"
            env["MATRIX_GAME_HUD_VISIBLE"] = "1" if launch_payload["hud_visible"] else "0"
            env["MATRIX_GAME_GRAPHICS_QUALITY"] = str(launch_payload["graphics_quality"])
            env["MATRIX_GAME_CONTROLLER_DEADZONE"] = str(launch_payload["controller_deadzone"])
            env["MATRIX_LAUNCHER_NAME"] = GAME_NAME
            env["MATRIX_LAUNCHED_FROM_CORE"] = "1"
            env["HOLOVERSE_HOSTED"] = "1"
            env["HOLOVERSE_EMBEDDED_CHILD"] = "1"
            env["HOLOVERSE_FAST_STARTUP"] = "1"
            env["PANDA3D_EMBEDDED"] = "1"
            env["PANDA3D_LAUNCHER"] = "1"
            env["NEON_DOGFIGHT_PANDA3D_SAFE"] = "1"
            env["SDL_VIDEO_CENTERED"] = "0"
            env["SDL_VIDEO_WINDOW_POS"] = "0,0"
            env["HOLOVERSE_PARENT_HWND"] = str(host_hwnd)
            env["HOLOVERSE_HOST_CONTRACT"] = "holoverse_mode_gateway_v4_child_window"
            env["HOLOVERSE_RETURN_TARGET"] = "hub"
            env["HOLOVERSE_WINDOW_MODE"] = "embedded_child"
            env["HOLOVERSE_PARENT_PID"] = str(os.getpid())
            if extra_env:
                for key, value in extra_env.items():
                    env[str(key)] = str(value)
            self.suspend_for_external_app(label, embedded=True)
            try:
                self._start_native_mode_audio(label)
            except Exception:
                pass
            proc = _launch_mode_subprocess(path, env, label)
            self.external_process = proc
            embedder = WindowsChildWindowEmbedder(host_hwnd, proc, label, w, h)
            self.embedded_child_host = embedder
            embedder.start()
            def _focus_after_attach():
                deadline = time.monotonic() + 5.0
                while time.monotonic() < deadline and proc.poll() is None:
                    if getattr(embedder, "attached", False):
                        embedder.focus_child(force=True)
                        break
                    time.sleep(0.08)
            threading.Thread(target=_focus_after_attach, daemon=True).start()
            self.show_native_status_overlay(label, route="EMBEDDED")
            self._append_mode_gateway_history("embedded_launch", label=label, route=MODE_LAUNCH_EMBEDDED, extra={"entry": os.fspath(path), "host_hwnd": host_hwnd, "settings": os.fspath(holoverse_settings_path), "audio_profile": os.fspath(audio_profile_path) if 'audio_profile_path' in locals() and audio_profile_path.exists() else "", "console_safe_launcher": True, "python_exe": _mode_process_python_executable()})
            threading.Thread(target=self._watch_external_process, args=(proc, label), daemon=True).start()
            return True
        except Exception as exc:
            self.external_process = None
            self.external_suspended = False
            self.external_resume_pending = False
            self.embedded_child_host = None
            self.mouse_captured = True
            self.center_hint["text"] = f"CORE // {label} EMBED FAILED"
            try:
                self._append_mode_gateway_history("embedded_launch_failed", label=label, route=MODE_LAUNCH_EMBEDDED, extra={"error": str(exc)})
            except Exception:
                pass
            return False

    def launch_external_level(self, path: Path, label: str, extra_env: dict | None = None) -> bool:
        if path is None or not Path(path).exists():
            self.center_hint["text"] = f"CORE // {label} MISSING"
            return False
        if self.external_process is not None:
            self.center_hint["text"] = f"CORE // {label} ALREADY RUNNING"
            return False
        try:
            audio_bus_path = write_audio_bus(self.cfg)
            launch_settings_path = write_shared_launch_settings(self.cfg)
            holoverse_settings_path = write_holoverse_settings(self.cfg)
            env = os.environ.copy()
            env["MATRIX_AUDIO_CONFIG"] = os.fspath(audio_bus_path)
            env["MATRIX_LAUNCH_SETTINGS"] = os.fspath(launch_settings_path)
            env["HOLOVERSE_SETTINGS_PATH"] = os.fspath(holoverse_settings_path)
            audio_profile_path = Path(path).parent / "audio_profile.json"
            if audio_profile_path.exists():
                env["HOLOVERSE_MODE_AUDIO_PROFILE"] = os.fspath(audio_profile_path)
            env["HOLOVERSE_MODE_NAME"] = str(label)
            env["HOLOVERSE_SHARED_DATA_DIR"] = os.fspath(SHARED_HOLOVERSE_DATA_DIR)
            env["HOLOVERSE_CREATIVITY_BLUEPRINT_DIR"] = os.fspath(SHARED_HOLOVERSE_DATA_DIR / "creativity" / "blueprints")
            shared_sfx_path = CANONICAL_SHARED_SFX_DIR if CANONICAL_SHARED_SFX_DIR.exists() else CORE_SFX_DIR
            env["HOLOVERSE_AUDIO_ROOT"] = os.fspath(AUDIO_LIBRARY_DIR)
            env["HOLOVERSE_SHARED_SFX_DIR"] = os.fspath(shared_sfx_path)
            env["MATRIX_SHARED_SFX_DIR"] = os.fspath(shared_sfx_path)
            env["HOLOVERSE_CORE_SFX_DIR"] = os.fspath(CORE_SFX_DIR)
            env["HOLOVERSE_MUSIC_FILE"] = os.fspath(HOLOVERSE_MUSIC_FILE)
            env["HOLOVERSE_MUSIC_DIR"] = os.fspath(AUDIO_LIBRARY_DIR)
            env["MATRIX_MUSIC_DIR"] = os.fspath(AUDIO_LIBRARY_DIR)
            env["HOLOVERSE_OVERRIDE_SETTINGS"] = "1"
            env["HOLOVERSE_EMBEDDED_MODE"] = "1"
            env["HOLOVERSE_RETURN_KEY"] = "escape"
            env["HOLOVERSE_SINGLE_ESC_RETURN"] = "1"
            env["HOLOVERSE_ESC_SINGLE_RETURN"] = "1"
            env["HOLOVERSE_RETURN_ON_ESC"] = "1"
            env["HOLOVERSE_ROOT_OWNS_MUSIC"] = "1"
            env["NEON_DOGFIGHT_DISABLE_MUSIC"] = "1"
            payload = build_audio_bus_payload(self.cfg)
            launch_payload = build_launch_settings_payload(self.cfg)
            safe_label = re.sub(r"[^A-Za-z0-9._-]+", "_", str(label or "mode")).strip("_") or "mode"
            return_signal_path = LOG_DIR / f"external_return_signal_{safe_label}.json"
            try:
                return_signal_path.unlink(missing_ok=True)
            except Exception:
                pass
            env["HOLOVERSE_RETURN_SIGNAL_PATH"] = os.fspath(return_signal_path)
            self.external_return_signal_path = return_signal_path
            env["MATRIX_MASTER_VOLUME"] = str(payload["master_volume"])
            env["MATRIX_SFX_VOLUME"] = str(payload["sfx_volume"])
            env["MATRIX_MUSIC_VOLUME"] = str(payload["music_volume"])
            env["MATRIX_AMBIENCE_VOLUME"] = str(payload["ambience_volume"])
            # Pass 282.75: a game in its own window takes HoloVerse's actual window geometry.
            # launch_payload["width"/"height"] is the saved launch setting (1920x1080 by default),
            # so on a larger display (HoloVerse sized to the monitor) Operation StarFall opened as a
            # quarter-size window in the top-left corner.
            host_x, host_y, host_w, host_h = self._host_window_geometry()
            env["MATRIX_GAME_WIDTH"] = str(host_w)
            env["MATRIX_GAME_HEIGHT"] = str(host_h)
            env["MATRIX_GAME_X"] = str(host_x)
            env["MATRIX_GAME_Y"] = str(host_y)
            env["HOLOVERSE_VIRTUAL_WIDTH"] = "1920"
            env["HOLOVERSE_VIRTUAL_HEIGHT"] = "1080"
            env["HOLOVERSE_FPS_CAP"] = str(launch_payload.get("fps_cap", 60) if isinstance(launch_payload, dict) else 60)
            env["HOLOVERSE_VSYNC"] = "1" if launch_payload.get("vsync", True) else "0"
            env["HOLOVERSE_UI_SCALE"] = str(launch_payload.get("ui_scale", 1.0))
            env["MATRIX_GAME_FULLSCREEN"] = "1" if (LAUNCH_FULLSCREEN and not LAUNCH_BORDERLESS) else "0"
            env["MATRIX_GAME_BORDERLESS"] = "1" if LAUNCH_BORDERLESS else "0"
            env["MATRIX_GAME_BORDERED_FULLSCREEN"] = "1" if launch_payload.get("bordered_fullscreen", True) else "0"
            env["MATRIX_GAME_MOUSE_SENSITIVITY"] = str(launch_payload["mouse_sensitivity"])
            env["MATRIX_GAME_INVERT_Y"] = "1" if launch_payload["invert_y"] else "0"
            env["MATRIX_GAME_HUD_VISIBLE"] = "1" if launch_payload["hud_visible"] else "0"
            env["MATRIX_GAME_GRAPHICS_QUALITY"] = str(launch_payload["graphics_quality"])
            env["MATRIX_GAME_CONTROLLER_DEADZONE"] = str(launch_payload["controller_deadzone"])
            env["MATRIX_LAUNCHER_NAME"] = GAME_NAME
            env["MATRIX_LAUNCHED_FROM_CORE"] = "1"
            env["HOLOVERSE_HOSTED"] = "1"
            env["HOLOVERSE_FAST_STARTUP"] = "1"
            env["HOLOVERSE_HOST_CONTRACT"] = "holoverse_mode_gateway_v2"
            env["HOLOVERSE_RETURN_TARGET"] = "hub"
            env["HOLOVERSE_WINDOW_MODE"] = "bordered_fullscreen" if launch_payload.get("bordered_fullscreen", True) else ("borderless" if launch_payload.get("borderless") else "windowed")
            env["HOLOVERSE_PARENT_PID"] = str(os.getpid())
            if extra_env:
                for key, value in extra_env.items():
                    env[str(key)] = str(value)
            self.suspend_for_external_app(label)
            proc = _launch_mode_subprocess(path, env, label)
            self.external_process = proc
            self._append_mode_gateway_history("external_launch", label=label, route=MODE_LAUNCH_EXTERNAL, extra={"entry": os.fspath(path), "console_safe_launcher": True, "python_exe": _mode_process_python_executable()})
            threading.Thread(target=self._focus_external_window_later, args=(proc, label), daemon=True).start()
            threading.Thread(target=self._watch_external_process, args=(proc, label), daemon=True).start()
            return True
        except Exception as exc:
            self.external_process = None
            self.external_suspended = False
            self.external_resume_pending = False
            self.mouse_captured = True
            self.center_hint["text"] = f"CORE // {label} FAILED"
            try:
                self._append_mode_gateway_history("external_launch_failed", label=label, route=MODE_LAUNCH_EXTERNAL, extra={"error": str(exc)})
            except Exception:
                pass
            return False

    def interact(self):
        # E is the primary station activation key, but when the player is close
        # to MatrixCore and actually facing it, home guidance must win over a station
        # sitting behind the crosshair cone.
        if self.is_looking_at_core():
            self.open_core_console()
            print("interaction_probe source=e target=core result=gleebs_dialogue")
            return
        # Pass 282.62: an artifact you are aiming at wins over guides.  E used to
        # check guides first with a 76 m "nearest guide" fallback, so standing at
        # an artifact near the start opened IO's dialogue instead.
        if self.activate_focused_artifact(source="e"):
            return
        if self.open_focused_bot_dialogue(source="e"):
            return
        if self.is_near_core():
            self.open_core_console()
            print("interaction_probe source=e target=core result=gleebs_dialogue_fallback")
            return
        if not self.activate_nearest_artifact(source="e-nearest"):
            self.center_hint["text"] = "LOOK AT A GUIDE OR STATION"
            print("interaction_probe source=e target=none result=no_bot_station_or_core")

    def core_secondary_action(self):
        if self.is_looking_at_core():
            self.open_core_console()
            print("interaction_probe source=q target=core result=gleebs_dialogue")
            return
        if not self.activate_focused_artifact(source="q"):
            if self.is_near_core():
                self.open_core_console()
                print("interaction_probe source=q target=core result=gleebs_dialogue_fallback")
                return
            self.center_hint["text"] = "LOOK AT A STATION"

