    def _theme_gleebs_caption(self, aspect: float) -> None:
        if not hasattr(self, "gleebs_dialogue_root"):
            return
        root = self.gleebs_dialogue_root
        if getattr(self, "gleebs_caption_panel", None) is None:
            self.gleebs_caption_panel = DirectFrame(parent=root, frameColor=UI_PANEL, frameSize=(-0.8, 0.8, -0.1, 0.1))
            self.gleebs_caption_panel.setBin("fixed", 0)
            self.gleebs_caption_speaker = DirectLabel(parent=root, text="GLEEBS", text_align=TextNode.ACenter, text_scale=0.022, text_fg=UI_GLEEBS, frameColor=(0, 0, 0, 0), textMayChange=True, **self._ui_font_kw())
            for node in (self.gleebs_caption_panel, self.gleebs_caption_speaker):
                node.reparentTo(root)
        self._style_label(self.gleebs_caption_speaker, UI_GLEEBS, 0.022)
        for lbl in (self.gleebs_dialogue_shadow_wide, self.gleebs_dialogue_glow):
            lbl.hide()
        for lbl in (self.gleebs_dialogue_shadow, self.gleebs_dialogue_label, self.gleebs_dialogue_quote_label, self.gleebs_dialogue_hint):
            lbl["text_align"] = TextNode.ACenter
        self._layout_gleebs_caption()

    def _layout_gleebs_caption(self) -> None:
        """Bottom-centre subtitle box sized to the current line."""
        root = getattr(self, "gleebs_dialogue_root", None)
        if root is None or getattr(self, "gleebs_caption_panel", None) is None:
            return
        scale, wrap = 0.029, 46.0
        root.setPos(0, 0, -0.60)
        text = str(self.gleebs_dialogue_label["text"] or "")
        rows = 1
        try:
            tn = TextNode("gleebs-caption-measure")
            font = self._ui_font_kw().get("text_font")
            if font is not None:
                tn.setFont(font)
            tn.setWordwrap(wrap)
            tn.setText(text)
            rows = max(1, tn.getNumRows())
        except Exception:
            rows = max(1, int(len(text) / 40) + 1)
        line_h = scale * 1.20
        top = 0.075
        bottom = -(rows - 1) * line_h - 0.040
        half_w = min(0.90, max(0.42, min(len(text), wrap) * scale * 0.56 * 0.5 + 0.12))
        self.gleebs_caption_panel["frameSize"] = (-half_w, half_w, bottom, top)
        self.gleebs_caption_speaker.setPos(0, 0, top - 0.040)
        for lbl in (self.gleebs_dialogue_shadow, self.gleebs_dialogue_label):
            lbl["text_wordwrap"] = wrap
            lbl["text_scale"] = scale
        self.gleebs_dialogue_label.setPos(0, 0, -0.012)
        self.gleebs_dialogue_shadow.setPos(0.0022, 0, -0.0142)
        self.gleebs_dialogue_quote_label.setPos(0, 0, bottom - 0.040)
        self.gleebs_dialogue_hint.setPos(0, 0, bottom - 0.075)

