    def hud_language_smoke_setup(self, task):
        """Capture the public first-minute HUD at a primary experiment station."""
        try:
            target = next((a for a in self.artifacts if canonical_dimension_lookup_key(a.get("dimension_mode_id")) == "region_holospace"), None)
            if target is None:
                raise RuntimeError("HoloSpace artifact missing")
            pos = Vec3(target.get("pedestal_pos", target.get("pos")))
            direction = Vec3(0, -1, 0)
            self.player_pos = Vec3(pos.x, pos.y - 4.1, self.cfg.player_eye_height)
            self.camera.setPos(self.player_pos)
            self.camera.lookAt(Vec3(target.get("pos")))
            hpr = self.camera.getHpr()
            self.player_yaw = float(hpr.x)
            self.player_pitch = float(hpr.y)
            self.find_nearest_artifact()
            self.animate_accents(0.0)
            self.update_perf_hud(force=True)
            self.graphicsEngine.renderFrame()
            self.win.saveScreenshot(Filename.fromOsSpecific(str(HUD_LANGUAGE_SMOKE_SCREENSHOT)))
        except Exception as exc:
            print(f"hud_language_smoke_setup_error:{exc.__class__.__name__}:{exc}")
        return Task.done

    def collect_hud_language_smoke_report(self) -> dict:
        public_text = {
            "home": str(self.hud_label["text"] if hasattr(self, "hud_label") else ""),
            "points": str(self.perf_hud_label["text"] if hasattr(self, "perf_hud_label") else ""),
            "prompt": str(self.center_hint["text"] if hasattr(self, "center_hint") else ""),
            "menu_title": str(self.menu_title["text"] if hasattr(self, "menu_title") else ""),
            "menu_subtitle": str(self.menu_subtitle["text"] if hasattr(self, "menu_subtitle") else ""),
            "menu_action_title": str(self.menu_action_title["text"] if hasattr(self, "menu_action_title") else ""),
            "menu_action_help": str(self.menu_action_help["text"] if hasattr(self, "menu_action_help") else ""),
        }
        forbidden = ("ROUTE", "RUNTIME", "DATABASE", "VALIDATOR", "AUTHORITY", "GATEWAY", "SIGNAL ROUTER", "BOT LINK")
        hits = []
        for lane, text in public_text.items():
            upper = text.upper()
            for token in forbidden:
                if token in upper:
                    hits.append({"lane": lane, "token": token, "text": text})
        return {
            "kind": "holoverse_hud_language_smoke",
            "public_text": public_text,
            "forbidden_hits": hits,
            "station_prompt_ok": public_text.get("prompt") == "E  HOLOSPACE ARTIFACT",
            "points_compact_ok": public_text.get("points", "").startswith("PTS ") and "POINTS" not in public_text.get("points", ""),
            "menu_language_ok": public_text.get("menu_action_title", "").endswith("OPTIONS") and not any(token in (public_text.get("menu_action_title", "") + " " + public_text.get("menu_action_help", "")).upper() for token in forbidden),
            "screenshot": str(HUD_LANGUAGE_SMOKE_SCREENSHOT),
            "pass": not hits and public_text.get("prompt") == "E  HOLOSPACE ARTIFACT" and public_text.get("points", "").startswith("PTS "),
        }

    def hud_language_smoke_exit(self, task):
        report = self.collect_hud_language_smoke_report()
        HUD_LANGUAGE_SMOKE_REPORT.parent.mkdir(parents=True, exist_ok=True)
        HUD_LANGUAGE_SMOKE_REPORT.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
        print(json.dumps(report, indent=2))
        try:
            sys.stdout.flush(); sys.stderr.flush()
        except Exception:
            pass
        os._exit(0 if report.get("pass") else 2)
        return Task.done

