    def collect_bot_language_smoke_report(self) -> dict:
        public_text = {
            "title": str(self.bot_dialogue_title["text"]),
            "question": str(self.bot_dialogue_question["text"]),
            "mode": str(self.bot_dialogue_mode_label["text"]),
            "detail": str(self.bot_dialogue_detail["text"]),
            "talk_button": str(self.bot_dialogue_talk["text"]),
            "enter_button": str(self.bot_dialogue_yes["text"]),
            "back_button": str(self.bot_dialogue_no["text"]),
        }
        forbidden = ("ROUTE", "RUNTIME", "DATABASE", "VALIDATOR", "AUTHORITY", "ARTIFACT", "GATEWAY", "BOT LINK", "DIMENSION INVITE", "YES / NO", "LIVE-REGION", "GATEKEEPER", "MATRIXCORE HOLOSPACE BUTTON")
        hits = []
        for lane, text in public_text.items():
            upper = text.upper()
            for token in forbidden:
                if token in upper:
                    hits.append({"lane": lane, "token": token, "text": text})
        ok = (
            not hits
            and public_text.get("title") == "ORBIT"
            and public_text.get("mode") == "HOLOSPACE"
            and public_text.get("detail", "").startswith("ACTIVE //")
            and public_text.get("talk_button") == "TALK"
            and public_text.get("enter_button") == "ENTER"
            and public_text.get("back_button") == "BACK"
        )
        return {"kind": "holoverse_bot_language_smoke", "public_text": public_text, "forbidden_hits": hits, "screenshot": str(BOT_LANGUAGE_SMOKE_SCREENSHOT), "pass": ok}

