    def holospace_smoke_setup(self, task):
        """Enter the real HoloSpace route and capture a focused flight view."""
        try:
            entry = self.holoverse_region_entry_for_number(8) or {}
            if not self.enter_holospace_direct(entry, source="holospace_smoke"):
                raise RuntimeError("HoloSpace direct entry failed")
            self.center_hint["text"] = "H  FLIGHT HELP   //   TAB  HOME"
            self.refresh_ui()
            for _ in range(4):
                self.update_world_shell_mount(0.05)
                self.apply_world_theme(0.05)
            self.graphicsEngine.renderFrame()
            self.win.saveScreenshot(Filename.fromOsSpecific(str(HOLOSPACE_SMOKE_SCREENSHOT)))
        except Exception as exc:
            print(f"holospace_smoke_setup_error:{exc.__class__.__name__}:{exc}")
        return Task.done

    def collect_holospace_smoke_report(self) -> dict:
        runtime = getattr(getattr(self, "world_shell_mount", None), "source_runtime", None)
        shell_segments = int(getattr(runtime, "dyson_shell_total_segments", 0) or 0) if runtime is not None else 0
        asteroid_count = len(getattr(runtime, "space_layer_asteroid_nodes", []) or []) if runtime is not None else 0
        inspector_count = len(getattr(runtime, "space_layer_inspector_nodes", []) or []) if runtime is not None else 0
        lens_count = len(getattr(runtime, "space_layer_lensing_nodes", []) or []) if runtime is not None else 0
        photon_count = len(getattr(runtime, "space_layer_photon_beam_nodes", []) or []) if runtime is not None else 0
        text = str(self.center_hint["text"] if hasattr(self, "center_hint") else "")
        errors = []
        if not self.is_holospace_active(): errors.append("holospace_not_active")
        if str(self.hud_label["text"]) != "HOLOSPACE": errors.append("hud_title_not_holospace")
        if "TAB  HOME" not in text: errors.append("tab_home_missing")
        if "WASD" in text or "SHIFT BOOST" in text: errors.append("live_tutorial_too_dense")
        if shell_segments > 80: errors.append(f"shell_segments_too_dense:{shell_segments}")
        if asteroid_count > 3: errors.append(f"asteroids_too_dense:{asteroid_count}")
        if inspector_count > 3: errors.append(f"inspectors_too_dense:{inspector_count}")
        if lens_count > 8: errors.append(f"lensing_too_dense:{lens_count}")
        if photon_count > 4: errors.append(f"photon_rays_too_dense:{photon_count}")
        # First-run contract: H must open real flight help, not hide the HUD.
        self.handle_h_action()
        flight_help_open = bool(getattr(self, "menu_open", False) and getattr(self, "menu_tab", "") == "help")
        flight_help_text = str(self.menu_detail["text"] if getattr(self, "menu_detail", None) is not None else "")
        if not flight_help_open: errors.append("h_flight_help_did_not_open")
        if "W/S throttle" not in flight_help_text or "J supercruise" not in flight_help_text or "TAB return to MatrixCore" not in flight_help_text:
            errors.append("flight_help_missing_primary_controls")
        # Pass 282.59: deep-space flight owns HoloSpace, with Dyson Prime far away.
        deep = self.deep_space.report() if self.deep_space_active() else {}
        if not deep.get("active"):
            errors.append("deep_space_not_active")
        elif float(deep.get("dyson_au", 0.0)) < float(deep.get("dyson_floor_au", 1.0)):
            errors.append("dyson_prime_reachable")
        if flight_help_open:
            self.toggle_menu()
        return {
            "schema": 1, "kind": "holoverse_holospace_smoke",
            "status": "PASS" if not errors else "FAIL", "errors": errors,
            "hud_title": str(self.hud_label["text"]), "hint": text,
            "shell_segments": shell_segments, "asteroid_count": asteroid_count,
            "inspector_count": inspector_count, "lensing_node_count": lens_count,
            "photon_beam_count": photon_count, "task_count": int(len(self.taskMgr.getAllTasks())),
            "h_flight_help_opened": flight_help_open, "flight_help_text": flight_help_text,
            "deep_space": deep,
            "screenshot": str(HOLOSPACE_SMOKE_SCREENSHOT),
        }

    def holospace_smoke_exit(self, task):
        report = self.collect_holospace_smoke_report()
        HOLOSPACE_SMOKE_REPORT.parent.mkdir(parents=True, exist_ok=True)
        HOLOSPACE_SMOKE_REPORT.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
        print(json.dumps(report, indent=2))
        self.userExit()
        try:
            sys.stdout.flush(); sys.stderr.flush()
        except Exception:
            pass
        os._exit(0 if report.get("status") == "PASS" else 2)
        return Task.done

    def holocore_smoke_setup(self, task):
        """Enter external HoloCore through the same Gleebs archive route players use."""
        try:
            registry = getattr(self, "dimension_registry", None)
            if registry is None:
                raise RuntimeError("Dimension Archive unavailable")
            registry.rescan(force=True)
            record = next((r for r in list(getattr(registry, "records", []) or [])
                           if canonical_dimension_lookup_key(getattr(r, "title", "")) == "holocore"), None)
            if record is None:
                raise RuntimeError("external HoloCore record missing")
            if not bool(getattr(record, "native_launchable", False)):
                raise RuntimeError("external HoloCore native adapter unavailable")
            if Path(record.folder).resolve().is_relative_to(ROOT.resolve()):
                raise RuntimeError("HoloCore incorrectly lives inside HoloVerse")
            if not registry._launch(record):
                raise RuntimeError("Dimension Archive HoloCore launch failed")
            scene = getattr(self, "active_native_mode", None)
            self.center_hint["text"] = ""
            for _ in range(4):
                update = getattr(scene, "update", None)
                if callable(update):
                    update(0.05)
        except Exception as exc:
            print(f"holocore_smoke_setup_error:{exc.__class__.__name__}:{exc}")
        return Task.done

    def holocore_smoke_capture(self, task):
        try:
            self.center_hint["text"] = ""
            scene = getattr(self, "active_native_mode", None)
            vessel = getattr(scene, "holo_vessel", None)
            if vessel is not None and getattr(vessel, "root", None) is not None and not vessel.root.isEmpty():
                vessel_pos = Vec3(vessel.root.getPos(self.render))
                center = vessel_pos + Vec3(0.0, 0.0, 8.0)
                try:
                    bounds = vessel.root.getTightBounds(self.render)
                    if bounds:
                        lo, hi = bounds
                        center = (Vec3(lo) + Vec3(hi)) * 0.5
                        span = Vec3(hi) - Vec3(lo)
                        distance = max(26.0, max(float(span.x), float(span.y), float(span.z)) * 1.35)
                    else:
                        distance = 45.0
                except Exception:
                    distance = 45.0
                self.camera.reparentTo(self.render)
                self.camera.setPos(center + Vec3(distance * 0.72, -distance, distance * 0.34))
                self.camera.lookAt(center)
                for widget_name in ("return_prompt", "holo_vessel_prompt"):
                    widget = getattr(scene, widget_name, None)
                    if widget is not None:
                        widget.hide()
            self.refresh_ui()
            self.graphicsEngine.renderFrame(); self.graphicsEngine.renderFrame()
            self.win.saveScreenshot(Filename.fromOsSpecific(str(HOLOCORE_SMOKE_SCREENSHOT)))
        except Exception as exc:
            print(f"holocore_smoke_capture_error:{exc.__class__.__name__}:{exc}")
        return Task.done

    def collect_holocore_smoke_report(self) -> dict:
        scene = getattr(self, "active_native_mode", None)
        errors = []
        if scene is None:
            errors.append("holocore_not_active")
            return {"schema": 2, "kind": "holoverse_holocore_external_dimension_smoke", "status": "FAIL", "errors": errors}
        root_dir = Path(getattr(scene, "root_dir", ROOT))
        adapter_id = str(getattr(sys.modules.get(scene.__class__.__module__), "ADAPTER_ID", "") or "")
        if root_dir.resolve().is_relative_to(ROOT.resolve()): errors.append("holocore_embedded_inside_holoverse")
        if adapter_id != "holocore_external_native_dimension_v7": errors.append(f"adapter_id:{adapter_id}")
        vessel = getattr(scene, "holo_vessel", None)
        if vessel is None or getattr(vessel, "root", None) is None or vessel.root.isEmpty(): errors.append("crescent_runner_missing")
        return_prompt_text = ""
        try: return_prompt_text = str(scene.return_prompt["text"])
        except Exception: pass
        if "TAB" not in return_prompt_text or "DIMENSION ARCHIVE" not in return_prompt_text: errors.append("archive_return_prompt_missing")
        if "H HELP" not in return_prompt_text: errors.append("help_prompt_missing")
        # HoloCore owns local H input while HoloVerse retains TAB.
        try: scene._toggle_help_prompt()
        except Exception: pass
        help_opened = bool(getattr(scene, "help_visible", False))
        help_text = str(scene.help_prompt["text"] if getattr(scene, "help_prompt", None) is not None else "")
        if not help_opened: errors.append("h_help_did_not_open")
        if "WASD MOVE" not in help_text or "TAB RETURN TO HOLOVERSE" not in help_text: errors.append("holocore_help_controls_missing")
        try: scene._toggle_help_prompt()
        except Exception: pass
        # Exploration movement is owned by the external adapter, not host.keys.
        move_start = Vec3(scene.player.getPos(self.render)) if getattr(scene, "player", None) is not None else Vec3(0)
        try:
            scene._set_key("w", True); scene.update(0.20); scene._set_key("w", False)
        except Exception as exc:
            errors.append(f"movement_error:{exc.__class__.__name__}")
        move_end = Vec3(scene.player.getPos(self.render)) if getattr(scene, "player", None) is not None else Vec3(0)
        exploration_distance = float((move_end - move_start).length())
        if exploration_distance <= 0.25: errors.append(f"exploration_movement_failed:{exploration_distance:.3f}")
        vessel_boarded = False; vessel_piloted = False; vessel_move_distance = 0.0
        if vessel is not None:
            try:
                vessel_start = Vec3(vessel.root.getPos(self.render))
                scene.player.setPos(vessel.entry_world_position()); vessel_boarded = bool(scene._interact())
                scene.player.setPos(vessel.pilot_seat_world_position()); vessel_piloted = bool(scene._interact())
                scene._set_key("w", True); scene._update_vessel_pilot(0.30); scene._set_key("w", False)
                vessel_end = Vec3(vessel.root.getPos(self.render)); vessel_move_distance = float((vessel_end - vessel_start).length())
                if not vessel_boarded: errors.append("crescent_runner_board_failed")
                if not vessel_piloted: errors.append("crescent_runner_pilot_failed")
                if vessel_move_distance <= 0.05: errors.append(f"crescent_runner_move_failed:{vessel_move_distance:.3f}")
            except Exception as exc:
                try: scene._set_key("w", False)
                except Exception: pass
                errors.append(f"crescent_runner_test_error:{exc.__class__.__name__}")
        return {
            "schema": 2, "kind": "holoverse_holocore_external_dimension_smoke",
            "status": "PASS" if not errors else "FAIL", "errors": errors,
            "external_project_root": str(root_dir), "adapter_id": adapter_id,
            "crescent_runner_mounted": bool(vessel is not None),
            "crescent_runner_boarded": vessel_boarded, "crescent_runner_piloted": vessel_piloted,
            "crescent_runner_move_distance": round(vessel_move_distance, 4),
            "h_help_opened": help_opened, "help_text": help_text,
            "exploration_distance": round(exploration_distance, 4),
            "return_prompt": return_prompt_text, "screenshot": str(HOLOCORE_SMOKE_SCREENSHOT),
        }

    def holocore_smoke_exit(self, task):
        report = self.collect_holocore_smoke_report()
        try:
            if getattr(self, "active_native_mode", None) is not None:
                self.return_from_native_mode(reason="holocore_external_smoke_complete")
            report["task_count_after_return"] = int(len(self.taskMgr.getAllTasks()))
        except Exception as exc:
            report.setdefault("errors", []).append(f"return_error:{exc.__class__.__name__}"); report["status"] = "FAIL"
        HOLOCORE_SMOKE_REPORT.parent.mkdir(parents=True, exist_ok=True)
        HOLOCORE_SMOKE_REPORT.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
        print(json.dumps(report, indent=2))
        self.userExit()
        try: sys.stdout.flush(); sys.stderr.flush()
        except Exception: pass
        os._exit(0 if report.get("status") == "PASS" else 2)
        return Task.done

