    def collect_hub_space_shell_smoke_report(self) -> dict:
        errors = []
        tagged = 0
        try:
            matches = self.render.findAllMatches("**")
            for i in range(matches.getNumPaths()):
                np = matches.getPath(i)
                try:
                    if bool(np.getPythonTag("matrixcore_space_surface")):
                        tagged += 1
                except Exception:
                    pass
        except Exception as exc:
            errors.append(f"surface_scan:{exc.__class__.__name__}")
        tex = getattr(self, "hub_textures", {}) or {}
        space = tex.get("space")
        shared_keys = ["wall", "ceiling", "dome"]
        if space is None:
            errors.append("shared space texture failed to load")
        for key in shared_keys:
            if tex.get(key) is not space:
                errors.append(f"{key} does not share matrixcore space texture")
        core = tex.get("core")
        if core is None:
            errors.append("core texture failed to load")
        if tagged < 41:
            errors.append(f"space-surface count expected >=41, got {tagged}")
        if not (HUB_TEXTURE_DIR / "matrixcore_space.png").exists():
            errors.append("matrixcore_space.png missing")
        if (ASSETS / "generated_hub_textures").exists():
            errors.append("legacy generated_hub_textures directory still present")
        return {
            "schema": 1,
            "kind": "holoverse_matrixcore_space_shell_smoke",
            "game": GAME_NAME,
            "version": VERSION,
            "status": "PASS" if not errors else "FAIL",
            "errors": errors,
            "space_surface_nodes": tagged,
            "shared_texture_keys": shared_keys,
            "texture_path": str(HUB_TEXTURE_DIR / "matrixcore_space.png"),
            "view": "outside" if HUB_SPACE_SHELL_OUTSIDE else "inside",
            "legacy_generated_texture_dir_present": bool((ASSETS / "generated_hub_textures").exists()),
            "task_count": int(len(self.taskMgr.getAllTasks())),
        }

