    def collect_home_declutter_smoke_report(self) -> dict:
        names = {
            "navigation_rings": "home-navigation-ring",
            "navigation_spokes": "home-navigation-spoke",
            "legacy_oct_rings": "oct-ring",
            "legacy_oct_spokes": "oct-spoke",
            "legacy_perimeter_rails": "rail",
            "dome_rings": "dome-ring",
            "dome_meridians": "dome-meridian",
            "duplicate_core_cage": "matrixcore-cyan-core-ring",
            "duplicate_core_spines": "matrixcore-cyan-core-spine",
            "legacy_core_rings": "core-ring",
            "legacy_core_prism": "prism-edge",
        }
        counts = {key: self._count_render_nodes_named(value) for key, value in names.items()}
        artifact_count = len(getattr(self, "artifacts", []) or [])
        primary_station_count = sum(1 for a in (getattr(self, "artifacts", []) or []) if bool(a.get("primary_station", False)))
        worldway_count = sum(1 for a in (getattr(self, "artifacts", []) or []) if self.artifact_region_entry(a) is not None)
        errors = []
        expected = {"navigation_rings": 3, "navigation_spokes": 4, "legacy_oct_rings": 0, "legacy_oct_spokes": 0, "legacy_perimeter_rails": 0, "dome_rings": 3, "dome_meridians": 12, "duplicate_core_cage": 0, "duplicate_core_spines": 0, "legacy_core_rings": 0}
        for key, value in expected.items():
            if counts.get(key) != value:
                errors.append(f"{key}: expected {value}, got {counts.get(key)}")
        if artifact_count != 10:
            errors.append(f"artifact/station count expected 10, got {artifact_count}")
        if primary_station_count != 2:
            errors.append(f"primary station count expected 2, got {primary_station_count}")
        if worldway_count != 8:
            errors.append(f"worldway artifact count expected 8, got {worldway_count}")
        return {
            "schema": 1,
            "kind": "holoverse_matrixcore_home_declutter_smoke",
            "status": "PASS" if not errors else "FAIL",
            "errors": errors,
            "counts": counts,
            "artifact_and_station_count": artifact_count,
            "primary_station_count": primary_station_count,
            "worldway_artifact_count": worldway_count,
            "task_count": int(len(self.taskMgr.getAllTasks())),
            "screenshot": str(HOME_DECLUTTER_SMOKE_SCREENSHOT),
        }

