from holoverse.dimensions.integration import install_dimension_integration as _hv271_install_dimension_integration
_hv271_install_dimension_integration(
    CommandHubApp,
    root=ROOT,
    vec3_cls=Vec3,
    centered_gleebs_helper=globals().get("_hv263_centered_gleebs_in_front"),
)
